{
  "name": "Patwa ji – Smart Billing & Management App",
  "description": "A comprehensive mobile-first billing and inventory management tool designed for small shopkeepers with offline-first capabilities, PIN security, and PDF invoice generation.",
  "requestFramePermissions": [
    "camera"
  ]
}

export enum PaymentMethod {
  CASH = 'CASH',
  ONLINE = 'ONLINE',
  BORROW = 'BORROW'
}

export interface Product {
  id: string;
  name: string;
  price: number;
  stock: number | null; // null for unlimited
}

export interface Client {
  id: string;
  name: string;
  mobile?: string;
  email?: string;
  totalBorrowed: number;
}

export interface InvoiceItem {
  id: string;
  name: string;
  quantity: number;
  price: number;
  total: number;
}

export interface Invoice {
  id: string;
  date: string;
  clientId: string | 'WALK_IN';
  clientName: string;
  clientMobile?: string;
  items: InvoiceItem[];
  discount: number; // percentage
  subtotal: number;
  grandTotal: number;
  paymentMethod: PaymentMethod;
}

export interface AppConfig {
  ownerName: string;
  shopName: string;
  shopMobile: string;
  pin: string;
  signatureImage?: string;
  qrCodeImage?: string;
  lowStockThreshold: number;
  setupComplete: boolean;
}

export enum Tab {
  DASHBOARD = 'DASHBOARD',
  BILLING = 'BILLING',
  INVENTORY = 'INVENTORY',
  INVOICES = 'INVOICES',
  SETTINGS = 'SETTINGS'
}

export const formatCurrency = (amount: number): string => {
  return new Intl.NumberFormat('en-IN', {
    style: 'currency',
    currency: 'INR',
    maximumFractionDigits: 2,
  }).format(amount);
};

export const numberToWords = (num: number): string => {
  const a = ['', 'One ', 'Two ', 'Three ', 'Four ', 'Five ', 'Six ', 'Seven ', 'Eight ', 'Nine ', 'Ten ', 'Eleven ', 'Twelve ', 'Thirteen ', 'Fourteen ', 'Fifteen ', 'Sixteen ', 'Seventeen ', 'Eighteen ', 'Nineteen '];
  const b = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety'];

  const inWords = (n: any): string => {
    if ((n = n.toString()).length > 9) return 'overflow';
    const nArr = ('000000000' + n).substr(-9).match(/^(\d{2})(\d{2})(\d{2})(\d{1})(\d{2})$/);
    if (!nArr) return '';
    let str = '';
    str += parseInt(nArr[1]) !== 0 ? (a[Number(nArr[1])] || b[nArr[1][0]] + ' ' + a[nArr[1][1]]) + 'Crore ' : '';
    str += parseInt(nArr[2]) !== 0 ? (a[Number(nArr[2])] || b[nArr[2][0]] + ' ' + a[nArr[2][1]]) + 'Lakh ' : '';
    str += parseInt(nArr[3]) !== 0 ? (a[Number(nArr[3])] || b[nArr[3][0]] + ' ' + a[nArr[3][1]]) + 'Thousand ' : '';
    str += parseInt(nArr[4]) !== 0 ? (a[Number(nArr[4])] || b[nArr[4][0]] + ' ' + a[nArr[4][1]]) + 'Hundred ' : '';
    str += parseInt(nArr[5]) !== 0 ? ((str !== '') ? 'and ' : '') + (a[Number(nArr[5])] || b[nArr[5][0]] + ' ' + a[nArr[5][1]]) : '';
    return str.trim();
  };

  return inWords(Math.floor(num)) + ' Rupees Only';
};

export const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = error => reject(error);
  });
};

export const generateId = () => Math.random().toString(36).substr(2, 9).toUpperCase();

import React, { useState, useEffect, useCallback } from 'react';
import { 
  LayoutDashboard, 
  Receipt, 
  Package, 
  History, 
  Settings as SettingsIcon,
  Lock,
  PlusCircle,
  AlertCircle
} from 'lucide-react';
import { AppConfig, Tab, Product, Client, Invoice, PaymentMethod } from './types';
import Dashboard from './views/Dashboard';
import Billing from './views/Billing';
import Inventory from './views/Inventory';
import Invoices from './views/Invoices';
import Settings from './views/Settings';
import Setup from './components/Setup';
import PinLock from './components/PinLock';

const App: React.FC = () => {
  const [config, setConfig] = useState<AppConfig | null>(null);
  const [isLocked, setIsLocked] = useState(true);
  const [activeTab, setActiveTab] = useState<Tab>(Tab.DASHBOARD);

  // Data State
  const [products, setProducts] = useState<Product[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [invoices, setInvoices] = useState<Invoice[]>([]);

  // Load Initial Data
  useEffect(() => {
    const savedConfig = localStorage.getItem('app_config');
    const savedProducts = localStorage.getItem('products');
    const savedClients = localStorage.getItem('clients');
    const savedInvoices = localStorage.getItem('invoices');

    if (savedConfig) setConfig(JSON.parse(savedConfig));
    if (savedProducts) setProducts(JSON.parse(savedProducts));
    if (savedClients) setClients(JSON.parse(savedClients));
    if (savedInvoices) setInvoices(JSON.parse(savedInvoices));
  }, []);

  // Sync Data
  useEffect(() => {
    if (config) localStorage.setItem('app_config', JSON.stringify(config));
  }, [config]);

  useEffect(() => {
    localStorage.setItem('products', JSON.stringify(products));
  }, [products]);

  useEffect(() => {
    localStorage.setItem('clients', JSON.stringify(clients));
  }, [clients]);

  useEffect(() => {
    localStorage.setItem('invoices', JSON.stringify(invoices));
  }, [invoices]);

  const handleSetupComplete = (newConfig: AppConfig) => {
    setConfig(newConfig);
    setIsLocked(false);
  };

  const handleUnlock = () => {
    setIsLocked(false);
  };

  if (!config || !config.setupComplete) {
    return <Setup onComplete={handleSetupComplete} />;
  }

  if (isLocked) {
    return <PinLock correctPin={config.pin} onUnlock={handleUnlock} shopName={config.shopName} />;
  }

  const renderView = () => {
    switch (activeTab) {
      case Tab.DASHBOARD:
        return (
          <Dashboard 
            invoices={invoices} 
            clients={clients} 
            products={products} 
            config={config} 
            onNavigate={setActiveTab}
          />
        );
      case Tab.BILLING:
        return (
          <Billing 
            products={products} 
            clients={clients} 
            setInvoices={setInvoices}
            setProducts={setProducts}
            setClients={setClients}
            config={config}
          />
        );
      case Tab.INVENTORY:
        return (
          <Inventory 
            products={products} 
            setProducts={setProducts} 
            config={config}
          />
        );
      case Tab.INVOICES:
        return (
          <Invoices 
            invoices={invoices} 
            config={config}
          />
        );
      case Tab.SETTINGS:
        return (
          <Settings 
            config={config} 
            setConfig={setConfig} 
          />
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-24 flex flex-col">
      {/* Header */}
      <header className="bg-gradient-to-r from-blue-600 to-blue-800 text-white p-4 shadow-lg sticky top-0 z-40">
        <div className="flex justify-between items-center max-w-lg mx-auto w-full">
          <div>
            <h1 className="text-xl font-bold">{config.shopName}</h1>
            <p className="text-blue-100 text-xs">{config.ownerName}</p>
          </div>
          <button 
            onClick={() => setIsLocked(true)}
            className="p-2 bg-white/10 rounded-full hover:bg-white/20 transition-colors"
          >
            <Lock className="w-5 h-5" />
          </button>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 max-w-lg mx-auto w-full px-4 pt-4">
        {renderView()}
      </main>

      {/* FAB for Billing - only on Dashboard or Inventory */}
      {(activeTab === Tab.DASHBOARD || activeTab === Tab.INVENTORY) && (
        <button 
          onClick={() => setActiveTab(Tab.BILLING)}
          className="fixed bottom-24 right-6 w-14 h-14 bg-blue-600 text-white rounded-full shadow-2xl flex items-center justify-center hover:bg-blue-700 transition-transform active:scale-95 z-50"
        >
          <PlusCircle className="w-8 h-8" />
        </button>
      )}

      {/* Bottom Navigation */}
      <nav className="fixed bottom-0 left-0 right-0 bg-white border-t border-slate-200 px-2 py-1 safe-bottom z-40 shadow-[0_-4px_10px_rgba(0,0,0,0.05)]">
        <div className="max-w-lg mx-auto flex justify-between items-center h-16">
          <NavItem 
            active={activeTab === Tab.DASHBOARD} 
            onClick={() => setActiveTab(Tab.DASHBOARD)} 
            icon={<LayoutDashboard className="w-6 h-6" />} 
            label="Home" 
          />
          <NavItem 
            active={activeTab === Tab.BILLING} 
            onClick={() => setActiveTab(Tab.BILLING)} 
            icon={<Receipt className="w-6 h-6" />} 
            label="Billing" 
          />
          <NavItem 
            active={activeTab === Tab.INVENTORY} 
            onClick={() => setActiveTab(Tab.INVENTORY)} 
            icon={<Package className="w-6 h-6" />} 
            label="Stock" 
          />
          <NavItem 
            active={activeTab === Tab.INVOICES} 
            onClick={() => setActiveTab(Tab.INVOICES)} 
            icon={<History className="w-6 h-6" />} 
            label="History" 
          />
          <NavItem 
            active={activeTab === Tab.SETTINGS} 
            onClick={() => setActiveTab(Tab.SETTINGS)} 
            icon={<SettingsIcon className="w-6 h-6" />} 
            label="Profile" 
          />
        </div>
      </nav>
    </div>
  );
};

const NavItem: React.FC<{ active: boolean, onClick: () => void, icon: React.ReactNode, label: string }> = ({ active, onClick, icon, label }) => (
  <button 
    onClick={onClick}
    className={`flex flex-col items-center justify-center flex-1 transition-colors ${active ? 'text-blue-600' : 'text-slate-400'}`}
  >
    <div className={`p-1 rounded-xl ${active ? 'bg-blue-50' : ''}`}>
      {icon}
    </div>
    <span className="text-[10px] mt-1 font-medium">{label}</span>
  </button>
);

export default App;

import React, { useState } from 'react';
import { Camera, ShieldCheck, User, Store, Phone, PenTool } from 'lucide-react';
import { AppConfig } from '../types';
import { fileToBase64 } from '../utils/helpers';

interface SetupProps {
  onComplete: (config: AppConfig) => void;
}

const Setup: React.FC<SetupProps> = ({ onComplete }) => {
  const [formData, setFormData] = useState({
    ownerName: '',
    shopName: '',
    shopMobile: '',
    pin: '',
    confirmPin: '',
    lowStockThreshold: 5,
  });
  const [signature, setSignature] = useState<string>('');
  const [qrCode, setQrCode] = useState<string>('');
  const [error, setError] = useState('');

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>, type: 'signature' | 'qr') => {
    if (e.target.files && e.target.files[0]) {
      const base64 = await fileToBase64(e.target.files[0]);
      if (type === 'signature') setSignature(base64);
      else setQrCode(base64);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (formData.pin.length !== 4) {
      setError('PIN must be 4 digits');
      return;
    }
    if (formData.pin !== formData.confirmPin) {
      setError('PINs do not match');
      return;
    }
    if (!signature) {
      setError('Please upload an authorized signature');
      return;
    }

    onComplete({
      ...formData,
      signatureImage: signature,
      qrCodeImage: qrCode,
      setupComplete: true,
    });
  };

  return (
    <div className="min-h-screen bg-white p-6 pb-12 flex flex-col items-center">
      <div className="w-full max-w-md">
        <div className="text-center mb-8">
          <div className="w-20 h-20 bg-blue-100 text-blue-600 rounded-3xl flex items-center justify-center mx-auto mb-4">
            <Store className="w-10 h-10" />
          </div>
          <h1 className="text-2xl font-bold text-slate-900">Setup Patwa ji App</h1>
          <p className="text-slate-500 text-sm">Welcome! Let's get your shop ready.</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-5">
          {error && (
            <div className="bg-red-50 text-red-600 p-3 rounded-xl text-sm border border-red-100 flex items-center gap-2">
              <ShieldCheck className="w-4 h-4" />
              {error}
            </div>
          )}

          <div className="space-y-4">
            <div className="relative">
              <label className="text-xs font-semibold text-slate-500 uppercase ml-1">Owner Name</label>
              <div className="flex items-center mt-1">
                <div className="absolute left-3 text-slate-400"><User className="w-5 h-5" /></div>
                <input 
                  type="text" required
                  placeholder="e.g. Rahul Patwa"
                  className="w-full pl-11 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                  value={formData.ownerName}
                  onChange={e => setFormData({...formData, ownerName: e.target.value})}
                />
              </div>
            </div>

            <div className="relative">
              <label className="text-xs font-semibold text-slate-500 uppercase ml-1">Shop Name</label>
              <div className="flex items-center mt-1">
                <div className="absolute left-3 text-slate-400"><Store className="w-5 h-5" /></div>
                <input 
                  type="text" required
                  placeholder="e.g. Patwa General Store"
                  className="w-full pl-11 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                  value={formData.shopName}
                  onChange={e => setFormData({...formData, shopName: e.target.value})}
                />
              </div>
            </div>

            <div className="relative">
              <label className="text-xs font-semibold text-slate-500 uppercase ml-1">Mobile Number</label>
              <div className="flex items-center mt-1">
                <div className="absolute left-3 text-slate-400"><Phone className="w-5 h-5" /></div>
                <input 
                  type="tel" required pattern="[0-9]{10}"
                  placeholder="10 digit mobile"
                  className="w-full pl-11 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                  value={formData.shopMobile}
                  onChange={e => setFormData({...formData, shopMobile: e.target.value})}
                />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="relative">
                <label className="text-xs font-semibold text-slate-500 uppercase ml-1">4-Digit PIN</label>
                <input 
                  type="password" required maxLength={4}
                  placeholder="****"
                  className="w-full px-4 py-3 mt-1 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none text-center tracking-widest"
                  value={formData.pin}
                  onChange={e => setFormData({...formData, pin: e.target.value.replace(/[^0-9]/g, '')})}
                />
              </div>
              <div className="relative">
                <label className="text-xs font-semibold text-slate-500 uppercase ml-1">Confirm PIN</label>
                <input 
                  type="password" required maxLength={4}
                  placeholder="****"
                  className="w-full px-4 py-3 mt-1 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none text-center tracking-widest"
                  value={formData.confirmPin}
                  onChange={e => setFormData({...formData, confirmPin: e.target.value.replace(/[^0-9]/g, '')})}
                />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
               <div>
                  <label className="text-xs font-semibold text-slate-500 uppercase ml-1 block mb-2">Signature</label>
                  <label className="flex flex-col items-center justify-center h-24 bg-blue-50 border-2 border-dashed border-blue-200 rounded-2xl cursor-pointer hover:bg-blue-100 transition-colors">
                    {signature ? (
                      <img src={signature} alt="Sign" className="h-full object-contain p-2" />
                    ) : (
                      <>
                        <PenTool className="w-6 h-6 text-blue-500 mb-1" />
                        <span className="text-[10px] text-blue-600 font-medium">Upload Sign</span>
                      </>
                    )}
                    <input type="file" className="hidden" accept="image/*" onChange={e => handleImageUpload(e, 'signature')} />
                  </label>
               </div>
               <div>
                  <label className="text-xs font-semibold text-slate-500 uppercase ml-1 block mb-2">Payment QR</label>
                  <label className="flex flex-col items-center justify-center h-24 bg-blue-50 border-2 border-dashed border-blue-200 rounded-2xl cursor-pointer hover:bg-blue-100 transition-colors">
                    {qrCode ? (
                      <img src={qrCode} alt="QR" className="h-full object-contain p-2" />
                    ) : (
                      <>
                        <Camera className="w-6 h-6 text-blue-500 mb-1" />
                        <span className="text-[10px] text-blue-600 font-medium">Optional QR</span>
                      </>
                    )}
                    <input type="file" className="hidden" accept="image/*" onChange={e => handleImageUpload(e, 'qr')} />
                  </label>
               </div>
            </div>
          </div>

          <button 
            type="submit"
            className="w-full bg-blue-600 text-white py-4 rounded-2xl font-bold shadow-lg shadow-blue-200 active:scale-[0.98] transition-all mt-4"
          >
            Create My Shop
          </button>
        </form>
      </div>
    </div>
  );
};

export default Setup;

import React, { useState, useEffect } from 'react';
import { Delete, Lock, ShieldAlert } from 'lucide-react';

interface PinLockProps {
  correctPin: string;
  onUnlock: () => void;
  shopName: string;
}

const PinLock: React.FC<PinLockProps> = ({ correctPin, onUnlock, shopName }) => {
  const [pin, setPin] = useState('');
  const [error, setError] = useState(false);

  const handlePress = (num: string) => {
    if (pin.length < 4) {
      const newPin = pin + num;
      setPin(newPin);
      if (newPin.length === 4) {
        if (newPin === correctPin) {
          onUnlock();
        } else {
          setError(true);
          setTimeout(() => {
            setPin('');
            setError(false);
          }, 600);
        }
      }
    }
  };

  const handleBackspace = () => {
    setPin(pin.slice(0, -1));
  };

  return (
    <div className="min-h-screen bg-gradient-to-b from-blue-600 to-blue-800 flex flex-col items-center justify-center p-8">
      <div className="text-white text-center mb-12">
        <div className="w-20 h-20 bg-white/20 rounded-full flex items-center justify-center mx-auto mb-4 backdrop-blur-sm">
          <Lock className="w-8 h-8 text-white" />
        </div>
        <h1 className="text-2xl font-bold mb-1">{shopName}</h1>
        <p className="text-blue-100 text-sm">Enter PIN to Unlock</p>
      </div>

      {/* Dots */}
      <div className={`flex gap-6 mb-16 transition-transform ${error ? 'animate-bounce text-red-300' : ''}`}>
        {[0, 1, 2, 3].map(i => (
          <div 
            key={i} 
            className={`w-4 h-4 rounded-full border-2 border-white/50 transition-all ${pin.length > i ? 'bg-white scale-125' : 'bg-transparent'}`}
          />
        ))}
      </div>

      {/* Keypad */}
      <div className="grid grid-cols-3 gap-6 w-full max-w-xs">
        {['1', '2', '3', '4', '5', '6', '7', '8', '9'].map(num => (
          <button 
            key={num} 
            onClick={() => handlePress(num)}
            className="w-full aspect-square bg-white/10 hover:bg-white/20 active:bg-white/30 text-white text-2xl font-medium rounded-full backdrop-blur-md transition-colors flex items-center justify-center"
          >
            {num}
          </button>
        ))}
        <div />
        <button 
          onClick={() => handlePress('0')}
          className="w-full aspect-square bg-white/10 hover:bg-white/20 active:bg-white/30 text-white text-2xl font-medium rounded-full backdrop-blur-md transition-colors flex items-center justify-center"
        >
          0
        </button>
        <button 
          onClick={handleBackspace}
          className="w-full aspect-square flex items-center justify-center text-white/70 active:text-white"
        >
          <Delete className="w-8 h-8" />
        </button>
      </div>

      <button 
        onClick={() => {
          if (confirm("Forgot PIN? This will reset the app but data might be lost if you don't know the PIN. Continue to reset screen?")) {
            localStorage.clear();
            window.location.reload();
          }
        }}
        className="mt-12 text-blue-200 text-sm font-medium hover:text-white"
      >
        Forgot PIN?
      </button>
    </div>
  );
};

export default PinLock;

