            value={totalCustomers.toString()} 
            onClick={() => setModalType('CLIENTS')}
          />
          <StatCard 
            icon={<Wallet className="text-orange-600" />} 
            bg="bg-orange-50" 
            label="Udhaar (Total)" 
            value={formatCurrency(totalBorrowAmount)} 
            onClick={() => setModalType('BORROWERS')}
          />
        </div>
      </div>

      {/* Quick Actions / Lists Buttons */}
      <div className="grid grid-cols-2 gap-3">
        <ActionButton 
          icon={<AlertCircle className="w-5 h-5" />} 
          label="Low Stock Items" 
          count={lowStockItems.length}
          color="text-red-600"
          bg="bg-red-50"
          onClick={() => setModalType('LOW_STOCK')}
        />
        <ActionButton 
          icon={<Star className="w-5 h-5" />} 
          label="Top Selling" 
          color="text-yellow-600"
          bg="bg-yellow-50"
          onClick={() => setModalType('TOP_PRODUCTS')}
        />
      </div>

      {/* Recent Activity */}
      <div className="bg-white rounded-3xl p-5 shadow-sm border border-slate-100">
        <div className="flex justify-between items-center mb-4">
          <h3 className="font-bold text-slate-900">Recent Invoices</h3>
          <button onClick={() => onNavigate(Tab.INVOICES)} className="text-blue-600 text-xs font-bold flex items-center">
            View All <ChevronRight className="w-4 h-4" />
          </button>
        </div>
        <div className="space-y-4">
          {invoices.slice(-3).reverse().map(inv => (
            <div key={inv.id} className="flex justify-between items-center py-2 border-b border-slate-50 last:border-0">
              <div>
                <p className="font-semibold text-sm text-slate-800">{inv.clientName}</p>
                <p className="text-[10px] text-slate-400">{new Date(inv.date).toLocaleDateString()}</p>
              </div>
              <p className="font-bold text-sm text-blue-600">{formatCurrency(inv.grandTotal)}</p>
            </div>
          ))}
          {invoices.length === 0 && (
            <p className="text-center text-slate-400 text-sm py-4 italic">No recent transactions.</p>
          )}
        </div>
      </div>

      {/* Modals for Dynamic Lists */}
      {modalType && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-end justify-center">
          <div className="bg-white w-full max-w-lg rounded-t-[2.5rem] p-6 max-h-[85vh] overflow-y-auto animate-in slide-in-from-bottom duration-300">
            <div className="flex justify-between items-center mb-6 sticky top-0 bg-white py-2">
              <h3 className="text-xl font-bold">
                {modalType === 'BORROWERS' && 'Borrowed List'}
                {modalType === 'LOW_STOCK' && 'Low Stock Alert'}
                {modalType === 'CLIENTS' && 'Client Directory'}
                {modalType === 'TOP_PRODUCTS' && 'Best Sellers'}
              </h3>
              <button onClick={() => setModalType(null)} className="p-2 bg-slate-100 rounded-full">
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="space-y-4 pb-8">
              {modalType === 'BORROWERS' && clients.filter(c => c.totalBorrowed > 0).map(c => (
                <div key={c.id} className="flex justify-between p-4 bg-slate-50 rounded-2xl">
                  <span>{c.name}</span>
                  <span className="font-bold text-red-600">{formatCurrency(c.totalBorrowed)}</span>
                </div>
              ))}

              {modalType === 'LOW_STOCK' && lowStockItems.map(p => (
                <div key={p.id} className="flex justify-between p-4 bg-red-50 rounded-2xl border border-red-100">
                  <span>{p.name}</span>
                  <span className="font-bold text-red-700">{p.stock} Left</span>
                </div>
              ))}

              {modalType === 'CLIENTS' && clients.map(c => (
                <div key={c.id} className="p-4 bg-slate-50 rounded-2xl">
                  <p className="font-bold">{c.name}</p>
                  <p className="text-xs text-slate-500">{c.mobile || 'No Mobile'}</p>
                </div>
              ))}

              {modalType === 'TOP_PRODUCTS' && topProducts.map(([name, qty]) => (
                <div key={name} className="flex justify-between p-4 bg-yellow-50 rounded-2xl">
                  <span>{name}</span>
                  <span className="font-bold text-yellow-700">{qty as number} Units Sold</span>
                </div>
              ))}

              {/* Empty States */}
              {modalType === 'BORROWERS' && clients.filter(c => c.totalBorrowed > 0).length === 0 && <EmptyState text="No pending udhaar!" />}
              {modalType === 'LOW_STOCK' && lowStockItems.length === 0 && <EmptyState text="All stock is healthy!" />}
              {modalType === 'TOP_PRODUCTS' && topProducts.length === 0 && <EmptyState text="No sales data yet." />}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const StatCard: React.FC<{ icon: React.ReactNode, bg: string, label: string, value: string, onClick: () => void }> = ({ icon, bg, label, value, onClick }) => (
  <button onClick={onClick} className="bg-white p-4 rounded-3xl shadow-sm border border-slate-100 text-left active:scale-95 transition-transform">
    <div className={`w-10 h-10 ${bg} rounded-2xl flex items-center justify-center mb-3`}>
      {icon}
    </div>
    <p className="text-slate-500 text-[10px] font-bold uppercase tracking-wider">{label}</p>
    <p className="text-slate-900 font-bold text-lg">{value}</p>
