);

const ActionButton: React.FC<{ icon: React.ReactNode, label: string, count?: number, color: string, bg: string, onClick: () => void }> = ({ icon, label, count, color, bg, onClick }) => (
  <button onClick={onClick} className="flex items-center gap-3 p-3 bg-white rounded-2xl shadow-sm border border-slate-100 active:scale-95 transition-transform">
    <div className={`p-2 ${bg} ${color} rounded-xl`}>
      {icon}
    </div>
    <div className="text-left">
      <p className="text-[11px] font-bold text-slate-900">{label}</p>
      {count !== undefined && <p className="text-[10px] text-slate-400">{count} items</p>}
