export default Dashboard;

import React, { useState, useMemo } from 'react';
import { 
  Search, 
  UserPlus, 
  Trash2, 
  Plus, 
  Minus, 
  PlusCircle, 
  CheckCircle2,
  X,
  CreditCard,
  Banknote,
  Clock
} from 'lucide-react';
import { Product, Client, Invoice, InvoiceItem, PaymentMethod, AppConfig } from '../types';
import { generateId, formatCurrency } from '../utils/helpers';
import InvoiceDetail from '../components/InvoiceDetail';

interface BillingProps {
  products: Product[];
  clients: Client[];
  setInvoices: React.Dispatch<React.SetStateAction<Invoice[]>>;
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  setClients: React.Dispatch<React.SetStateAction<Client[]>>;
  config: AppConfig;
}

const Billing: React.FC<BillingProps> = ({ products, clients, setInvoices, setProducts, setClients, config }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [cart, setCart] = useState<InvoiceItem[]>([]);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [discount, setDiscount] = useState(0);
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>(PaymentMethod.CASH);
  const [showCheckout, setShowCheckout] = useState(false);
  const [generatedInvoice, setGeneratedInvoice] = useState<Invoice | null>(null);

  // Filtered Products
  const filteredProducts = useMemo(() => {
    if (!searchTerm) return [];
    return products.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()));
  }, [searchTerm, products]);

  const addToCart = (product: Product | { name: string, price: number }) => {
    setCart(prev => {
      const existing = prev.find(item => item.name === product.name);
      if (existing) {
        return prev.map(item => item.name === product.name ? { ...item, quantity: item.quantity + 1, total: (item.quantity + 1) * item.price } : item);
      }
      return [...prev, {
        id: ('id' in product ? product.id : generateId()),
        name: product.name,
        quantity: 1,
        price: product.price,
        total: product.price
      }];
    });
    setSearchTerm('');
  };

  const updateQuantity = (name: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.name === name) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty, total: newQty * item.price };
      }
      return item;
    }));
  };

  const removeFromCart = (name: string) => {
    setCart(prev => prev.filter(item => item.name !== name));
  };

  const subtotal = cart.reduce((acc, item) => acc + item.total, 0);
  const discountAmount = (subtotal * discount) / 100;
  const grandTotal = subtotal - discountAmount;

  const handleFinish = () => {
    const invoice: Invoice = {
      id: `INV-${Date.now().toString().slice(-6)}`,
      date: new Date().toISOString(),
      clientId: selectedClient?.id || 'WALK_IN',
      clientName: selectedClient?.name || 'Walk-in Customer',
      clientMobile: selectedClient?.mobile,
      items: [...cart],
      discount,
      subtotal,
      grandTotal,
      paymentMethod
    };

    // Save Invoice
    setInvoices(prev => [...prev, invoice]);

    // Update Stock
    setProducts(prev => prev.map(p => {
      const cartItem = cart.find(item => item.name === p.name);
      if (cartItem && p.stock !== null) {
        return { ...p, stock: p.stock - cartItem.quantity };
      }
      return p;
    }));

    // Update Client Borrowing
    if (paymentMethod === PaymentMethod.BORROW && selectedClient) {
      setClients(prev => prev.map(c => 
        c.id === selectedClient.id ? { ...c, totalBorrowed: c.totalBorrowed + grandTotal } : c
      ));
    }

    setGeneratedInvoice(invoice);
    setShowCheckout(false);
    setCart([]);
    setSelectedClient(null);
  };

  if (generatedInvoice) {
    return (
      <div className="space-y-4">
        <div className="bg-green-50 text-green-700 p-4 rounded-3xl border border-green-100 flex items-center gap-3">
          <CheckCircle2 className="w-6 h-6" />
          <p className="font-bold">Invoice generated successfully!</p>
        </div>
        <InvoiceDetail invoice={generatedInvoice} config={config} />
        <button 
          onClick={() => setGeneratedInvoice(null)}
          className="w-full bg-slate-100 text-slate-700 py-3 rounded-2xl font-bold"
        >
          Create New Bill
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-6 pb-20">
      {/* Header with Search & Client Select */}
      <div className="bg-white p-5 rounded-3xl shadow-sm border border-slate-100 space-y-4">
        <div className="flex items-center gap-2">
          <div className="flex-1 relative">
            <Search className="absolute left-3 top-3.5 w-5 h-5 text-slate-400" />
            <input 
              type="text"
              placeholder="Search product..."
              className="w-full pl-11 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl outline-none"
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
            />
          </div>
          <button 
            className={`p-3 rounded-2xl ${selectedClient ? 'bg-blue-600 text-white' : 'bg-slate-100 text-slate-500'}`}
            onClick={() => {
               // Logic to select existing client
               const c = prompt("Enter Client Name (or leave blank for Walk-in):");
               if (c) {
                 const existing = clients.find(cl => cl.name.toLowerCase() === c.toLowerCase());
                 if (existing) {
                   setSelectedClient(existing);
                 } else {
                   const newC: Client = { id: generateId(), name: c, totalBorrowed: 0 };
                   setClients(prev => [...prev, newC]);
                   setSelectedClient(newC);
                 }
               }
            }}
          >
            <UserPlus className="w-6 h-6" />
          </button>
        </div>

        {selectedClient && (
          <div className="flex justify-between items-center bg-blue-50 p-3 rounded-xl border border-blue-100">
            <div>
              <p className="text-[10px] font-bold text-blue-600 uppercase tracking-tighter">Selected Customer</p>
              <p className="text-sm font-bold text-blue-900">{selectedClient.name}</p>
            </div>
            <button onClick={() => setSelectedClient(null)} className="text-blue-400"><X className="w-4 h-4" /></button>
          </div>
        )}

        {/* Search Results Dropdown */}
        {searchTerm && (
          <div className="max-h-60 overflow-y-auto border-t border-slate-100 pt-2 space-y-2">
            {filteredProducts.map(p => (
              <button 
                key={p.id}
                onClick={() => addToCart(p)}
                className="w-full flex justify-between items-center p-3 hover:bg-slate-50 rounded-xl transition-colors"
              >
                <div className="text-left">
                  <p className="font-semibold text-slate-800">{p.name}</p>
                  <p className="text-xs text-slate-400">Stock: {p.stock === null ? '∞' : p.stock}</p>
                </div>
                <p className="font-bold text-blue-600">{formatCurrency(p.price)}</p>
              </button>
            ))}
            <button 
               onClick={() => {
                  const name = prompt("Custom Product Name:");
                  const price = parseFloat(prompt("Price (₹):") || "0");
                  if (name && price > 0) addToCart({ name, price });
               }}
               className="w-full p-3 text-blue-600 font-bold text-sm border-2 border-dashed border-blue-100 rounded-xl flex items-center justify-center gap-2"
            >
              <PlusCircle className="w-4 h-4" /> Add Custom Product
            </button>
          </div>
        )}
      </div>

      {/* Cart Items */}
      <div className="bg-white rounded-[2.5rem] p-6 shadow-sm border border-slate-100">
        <h3 className="font-bold text-slate-900 mb-6 flex items-center gap-2">
          Cart Summary <span className="bg-slate-100 text-slate-500 text-xs py-1 px-3 rounded-full">{cart.length} items</span>
        </h3>

        {cart.length === 0 ? (
          <div className="text-center py-12">
            <Package className="w-16 h-16 text-slate-100 mx-auto mb-4" />
            <p className="text-slate-400">Your cart is empty.</p>
          </div>
        ) : (
          <div className="space-y-6">
            {cart.map(item => (
              <div key={item.name} className="flex items-center justify-between group">
                <div className="flex-1">
                  <p className="font-bold text-slate-800 text-sm">{item.name}</p>
                  <p className="text-xs text-slate-400">{formatCurrency(item.price)} per unit</p>
                </div>
                <div className="flex items-center gap-4">
                  <div className="flex items-center bg-slate-100 rounded-xl px-1">
                    <button onClick={() => updateQuantity(item.name, -1)} className="p-2 text-slate-600"><Minus className="w-4 h-4" /></button>
                    <span className="w-8 text-center font-bold text-sm">{item.quantity}</span>
                    <button onClick={() => updateQuantity(item.name, 1)} className="p-2 text-slate-600"><Plus className="w-4 h-4" /></button>
                  </div>
                  <button onClick={() => removeFromCart(item.name)} className="text-slate-300 hover:text-red-500 transition-colors">
                    <Trash2 className="w-5 h-5" />
                  </button>
                </div>
              </div>
            ))}

            <div className="border-t border-slate-100 pt-6 space-y-3">
              <div className="flex justify-between text-sm text-slate-500">
                <span>Subtotal</span>
                <span>{formatCurrency(subtotal)}</span>
              </div>
              <div className="flex justify-between text-sm text-slate-500 items-center">
                <span>Discount (%)</span>
                <input 
                  type="number"
                  className="w-16 text-right bg-slate-50 border border-slate-200 rounded-lg p-1 outline-none font-bold"
                  value={discount}
                  onChange={e => setDiscount(Math.min(100, Math.max(0, parseInt(e.target.value) || 0)))}
                />
              </div>
              <div className="flex justify-between text-lg font-extrabold text-blue-700 pt-3 border-t border-blue-50">
                <span>Total Amount</span>
                <span>{formatCurrency(grandTotal)}</span>
              </div>
            </div>

            <button 
              onClick={() => setShowCheckout(true)}
              className="w-full bg-blue-600 text-white py-4 rounded-2xl font-bold shadow-lg shadow-blue-100 flex items-center justify-center gap-2 active:scale-95 transition-all"
            >
              Checkout Now <ChevronRight className="w-5 h-5" />
            </button>
          </div>
        )}
      </div>

      {/* Checkout Bottom Sheet */}
      {showCheckout && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-end justify-center">
          <div className="bg-white w-full max-w-lg rounded-t-[2.5rem] p-6 animate-in slide-in-from-bottom duration-300">
            <div className="flex justify-between items-center mb-8">
              <h3 className="text-xl font-bold">Payment Method</h3>
              <button onClick={() => setShowCheckout(false)} className="p-2 bg-slate-100 rounded-full"><X className="w-5 h-5" /></button>
            </div>

            <div className="grid grid-cols-1 gap-4 mb-8">
              <PaymentOption 
                active={paymentMethod === PaymentMethod.CASH}
                onClick={() => setPaymentMethod(PaymentMethod.CASH)}
                icon={<Banknote className="w-6 h-6" />}
                label="Cash Payment"
                desc="Fastest way to settle"
              />
              <PaymentOption 
                active={paymentMethod === PaymentMethod.ONLINE}
                onClick={() => setPaymentMethod(PaymentMethod.ONLINE)}
                icon={<CreditCard className="w-6 h-6" />}
                label="Online / UPI"
                desc="Show QR code for payment"
              />
              <PaymentOption 
                active={paymentMethod === PaymentMethod.BORROW}
                onClick={() => setPaymentMethod(PaymentMethod.BORROW)}
                icon={<Clock className="w-6 h-6" />}
                label="Udhaar (Borrow)"
                desc="Add to customer's account"
                disabled={!selectedClient}
              />
              {!selectedClient && paymentMethod === PaymentMethod.BORROW && (
                <p className="text-xs text-red-500 font-medium">* Select a customer to enable Borrowing</p>
              )}
            </div>

            <button 
              onClick={handleFinish}
              className="w-full bg-blue-600 text-white py-4 rounded-2xl font-bold shadow-lg active:scale-95 transition-all"
            >
              Generate Bill & Finish
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

const PaymentOption: React.FC<{ active: boolean, onClick: () => void, icon: React.ReactNode, label: string, desc: string, disabled?: boolean }> = ({ active, onClick, icon, label, desc, disabled }) => (
  <button 
    onClick={onClick}
    disabled={disabled}
    className={`flex items-center gap-4 p-4 rounded-2xl border-2 transition-all ${disabled ? 'opacity-50 grayscale' : ''} ${active ? 'bg-blue-50 border-blue-600' : 'bg-white border-slate-100'}`}
  >
    <div className={`p-3 rounded-xl ${active ? 'bg-blue-600 text-white' : 'bg-slate-100 text-slate-500'}`}>
      {icon}
    </div>
    <div className="text-left">
      <p className="font-bold text-slate-900">{label}</p>
      <p className="text-xs text-slate-400">{desc}</p>
    </div>
    {active && <CheckCircle2 className="w-6 h-6 text-blue-600 ml-auto" />}
  </button>
);

const ChevronRight: React.FC<{ className?: string }> = ({ className }) => (
  <svg className={className} width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="m9 18 6-6-6-6"/></svg>
);

export default Billing;

import React, { useRef } from 'react';
import { Printer, Download, Share2 } from 'lucide-react';
import { Invoice, AppConfig, PaymentMethod } from '../types';
import { formatCurrency, numberToWords } from '../utils/helpers';

interface InvoiceDetailProps {
  invoice: Invoice;
  config: AppConfig;
}

const InvoiceDetail: React.FC<InvoiceDetailProps> = ({ invoice, config }) => {
  const invoiceRef = useRef<HTMLDivElement>(null);

  const handlePrint = () => {
    window.print();
  };

  const handleDownload = async () => {
    if (!invoiceRef.current) return;
    const { jsPDF } = (window as any).jspdf;

    // Temporarily apply white background for capture
    const element = invoiceRef.current;

    try {
      const canvas = await (window as any).html2canvas(element, {
        scale: 2,
        useCORS: true,
        backgroundColor: '#ffffff'
      });
      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF('p', 'mm', 'a4');
      const imgProps = pdf.getImageProperties(imgData);
      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = (imgProps.height * pdfWidth) / imgProps.width;

      pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
      pdf.save(`Invoice_${invoice.id}.pdf`);
    } catch (err) {
      console.error("PDF Export failed", err);
      alert("Failed to generate PDF. Please try printing instead.");
    }
  };

  return (
    <div className="space-y-4">
      <div className="bg-white p-2 rounded-2xl flex justify-around no-print shadow-sm border border-slate-100">
        <button onClick={handlePrint} className="flex flex-col items-center gap-1 text-blue-600 font-bold text-[10px] p-2">
          <Printer className="w-5 h-5" /> Print
        </button>
        <button onClick={handleDownload} className="flex flex-col items-center gap-1 text-blue-600 font-bold text-[10px] p-2">
          <Download className="w-5 h-5" /> PDF
        </button>
        <button onClick={() => alert("Sharing not implemented in browser environment")} className="flex flex-col items-center gap-1 text-blue-600 font-bold text-[10px] p-2">
          <Share2 className="w-5 h-5" /> Share
        </button>
      </div>

      <div 
        ref={invoiceRef}
        className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100 print:shadow-none print:border-none print:p-0 print:m-0"
      >
        {/* Invoice Header */}
        <div className="text-center border-b-2 border-slate-100 pb-4 mb-4">
          <h1 className="text-2xl font-black text-slate-900 uppercase tracking-tight">{config.shopName}</h1>
          <p className="text-sm font-medium text-slate-600">{config.ownerName}</p>
          <p className="text-xs text-slate-500">Mo: +91 {config.shopMobile}</p>
          <div className="mt-4 flex justify-between items-end text-left px-2">
            <div>
              <p className="text-[10px] uppercase font-bold text-slate-400">Invoice To</p>
              <p className="text-sm font-bold text-slate-800">{invoice.clientName}</p>
              {invoice.clientMobile && <p className="text-[10px] text-slate-500">{invoice.clientMobile}</p>}
            </div>
            <div className="text-right">
              <p className="text-[10px] uppercase font-bold text-slate-400">Invoice No</p>
              <p className="text-sm font-bold text-blue-700">#{invoice.id}</p>
              <p className="text-[10px] text-slate-500">{new Date(invoice.date).toLocaleDateString()}</p>
            </div>
          </div>
        </div>

        {/* Items Table */}
        <table className="w-full text-left mb-6">
          <thead className="border-b border-slate-100">
            <tr>
              <th className="py-2 text-[10px] font-bold text-slate-400 uppercase">Description</th>
              <th className="py-2 text-[10px] font-bold text-slate-400 uppercase text-center">Qty</th>
              <th className="py-2 text-[10px] font-bold text-slate-400 uppercase text-right">Amount</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50">
            {invoice.items.map((item, idx) => (
              <tr key={idx}>
                <td className="py-3">
                  <p className="text-sm font-bold text-slate-800">{item.name}</p>
                  <p className="text-[10px] text-slate-400">{formatCurrency(item.price)} each</p>
                </td>
                <td className="py-3 text-center text-sm font-medium text-slate-700">{item.quantity}</td>
                <td className="py-3 text-right text-sm font-bold text-slate-900">{formatCurrency(item.total)}</td>
