          <div className="flex justify-between text-xs">
            <span className="text-slate-500">Subtotal:</span>
            <span className="font-bold text-slate-900">{formatCurrency(invoice.subtotal)}</span>
          </div>
          {invoice.discount > 0 && (
            <div className="flex justify-between text-xs">
              <span className="text-slate-500">Discount ({invoice.discount}%):</span>
              <span className="font-bold text-green-600">-{formatCurrency((invoice.subtotal * invoice.discount) / 100)}</span>
            </div>
          )}
          <div className="flex justify-between items-center bg-slate-50 p-3 rounded-xl border border-slate-100">
            <span className="text-sm font-black text-slate-900">Grand Total</span>
            <span className="text-lg font-black text-blue-700">{formatCurrency(invoice.grandTotal)}</span>
