        </div>

        <p className="text-[10px] italic text-slate-500 mb-6">
          <span className="font-bold text-slate-700 uppercase">In Words:</span> {numberToWords(invoice.grandTotal)}
        </p>

        {/* Footer */}
        <div className="grid grid-cols-2 gap-4 items-center">
          <div>
            <p className="text-[10px] uppercase font-bold text-slate-400 mb-2">Payment: {invoice.paymentMethod}</p>
            {invoice.paymentMethod === PaymentMethod.ONLINE && config.qrCodeImage && (
              <div className="w-20 h-20 border border-slate-100 p-1 rounded-lg">
