import React, { useState } from 'react';
import { Package, Search, Plus, Edit2, Trash2, Save, X, AlertTriangle } from 'lucide-react';
import { Product, AppConfig } from '../types';
import { generateId, formatCurrency } from '../utils/helpers';

interface InventoryProps {
  products: Product[];
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  config: AppConfig;
}

const Inventory: React.FC<InventoryProps> = ({ products, setProducts, config }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [showAdd, setShowAdd] = useState(false);
  const [formData, setFormData] = useState<Partial<Product>>({ name: '', price: 0, stock: null });

  const filteredProducts = products.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()));

  const handleSave = () => {
    if (!formData.name || (formData.price || 0) <= 0) {
      alert("Please provide name and price.");
      return;
    }

    if (editingId) {
      setProducts(prev => prev.map(p => p.id === editingId ? { ...p, ...formData } as Product : p));
      setEditingId(null);
    } else {
      setProducts(prev => [...prev, { ...formData, id: generateId() } as Product]);
      setShowAdd(false);
    }
    setFormData({ name: '', price: 0, stock: null });
  };

  const deleteProduct = (id: string) => {
    if (confirm("Delete this product?")) {
      setProducts(prev => prev.filter(p => p.id !== id));
    }
  };

  const startEdit = (product: Product) => {
    setEditingId(product.id);
    setFormData(product);
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-4 rounded-3xl shadow-sm border border-slate-100 flex items-center gap-2">
        <Search className="w-5 h-5 text-slate-400 ml-2" />
        <input 
          type="text"
          placeholder="Search items..."
          className="flex-1 bg-transparent border-none outline-none text-slate-800 font-medium"
          value={searchTerm}
          onChange={e => setSearchTerm(e.target.value)}
        />
        <button 
          onClick={() => setShowAdd(true)}
          className="bg-blue-600 text-white p-2 rounded-xl"
        >
          <Plus className="w-5 h-5" />
        </button>
      </div>

      {(showAdd || editingId) && (
        <div className="bg-white p-6 rounded-3xl shadow-lg border border-blue-100 space-y-4 animate-in fade-in zoom-in duration-200">
          <div className="flex justify-between items-center">
            <h3 className="font-bold text-slate-900">{editingId ? 'Edit Product' : 'Add New Product'}</h3>
            <button onClick={() => { setShowAdd(false); setEditingId(null); }} className="text-slate-400"><X className="w-5 h-5" /></button>
          </div>
          <div className="space-y-3">
            <div>
              <label className="text-xs font-bold text-slate-400 uppercase">Product Name</label>
              <input 
                type="text"
                className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 outline-none"
                value={formData.name}
                onChange={e => setFormData({...formData, name: e.target.value})}
              />
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="text-xs font-bold text-slate-400 uppercase">Price (₹)</label>
                <input 
                  type="number"
                  className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 outline-none"
                  value={formData.price}
                  onChange={e => setFormData({...formData, price: parseFloat(e.target.value) || 0})}
                />
              </div>
              <div>
                <label className="text-xs font-bold text-slate-400 uppercase">Stock (Qty)</label>
                <input 
                  type="number"
                  placeholder="∞ Unlimited"
                  className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 outline-none"
                  value={formData.stock === null ? '' : formData.stock}
                  onChange={e => setFormData({...formData, stock: e.target.value === '' ? null : parseInt(e.target.value)})}
                />
              </div>
            </div>
            <button 
              onClick={handleSave}
              className="w-full bg-blue-600 text-white py-4 rounded-2xl font-bold flex items-center justify-center gap-2"
            >
              <Save className="w-5 h-5" /> Save Product
            </button>
          </div>
        </div>
      )}

      <div className="space-y-3">
        {filteredProducts.map(p => {
          const isLowStock = p.stock !== null && p.stock <= config.lowStockThreshold;
          return (
            <div key={p.id} className="bg-white p-4 rounded-3xl shadow-sm border border-slate-100 flex items-center justify-between group">
              <div className="flex items-center gap-4">
                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center ${isLowStock ? 'bg-red-50 text-red-600' : 'bg-blue-50 text-blue-600'}`}>
                  {isLowStock ? <AlertTriangle className="w-6 h-6" /> : <Package className="w-6 h-6" />}
                </div>
                <div>
                  <h4 className="font-bold text-slate-900">{p.name}</h4>
                  <p className="text-xs text-slate-400">
                    {formatCurrency(p.price)} • {p.stock === null ? 'Unlimited' : `${p.stock} in stock`}
                  </p>
                </div>
              </div>
              <div className="flex gap-2">
                <button onClick={() => startEdit(p)} className="p-2 text-slate-400 hover:text-blue-600 transition-colors">
                  <Edit2 className="w-4 h-4" />
                </button>
                <button onClick={() => deleteProduct(p.id)} className="p-2 text-slate-400 hover:text-red-600 transition-colors">
                  <Trash2 className="w-4 h-4" />
                </button>
              </div>
            </div>
          );
        })}
        {filteredProducts.length === 0 && (
          <div className="text-center py-20 bg-white rounded-3xl border-2 border-dashed border-slate-100">
             <Package className="w-16 h-16 text-slate-100 mx-auto mb-4" />
             <p className="text-slate-400">No products found.</p>
             <button onClick={() => setShowAdd(true)} className="text-blue-600 font-bold text-sm mt-2">Add your first item</button>
          </div>
        )}
      </div>
    </div>
  );
};

export default Inventory;

import React, { useState } from 'react';
import { Search, History, Calendar, Filter, ChevronRight, X } from 'lucide-react';
import { Invoice, AppConfig } from '../types';
