interface InvoicesProps {
  invoices: Invoice[];
  config: AppConfig;
}

const Invoices: React.FC<InvoicesProps> = ({ invoices, config }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedInvoice, setSelectedInvoice] = useState<Invoice | null>(null);
  const [dateFilter, setDateFilter] = useState('');

  const filteredInvoices = invoices.filter(inv => {
    const matchesSearch = inv.clientName.toLowerCase().includes(searchTerm.toLowerCase()) || 
                         inv.id.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesDate = !dateFilter || inv.date.startsWith(dateFilter);
    return matchesSearch && matchesDate;
  }).reverse();

  return (
    <div className="space-y-6">
      {selectedInvoice ? (
        <div className="space-y-4">
           <button 
             onClick={() => setSelectedInvoice(null)}
             className="flex items-center gap-2 text-slate-500 font-bold text-sm mb-4"
           >
             <ChevronRight className="w-5 h-5 rotate-180" /> Back to History
           </button>
           <InvoiceDetail invoice={selectedInvoice} config={config} />
        </div>
      ) : (
        <>
          <div className="bg-white p-4 rounded-3xl shadow-sm border border-slate-100 flex flex-col gap-3">
            <div className="flex items-center gap-2">
              <Search className="w-5 h-5 text-slate-400" />
              <input 
                type="text"
                placeholder="Search Client or INV ID..."
                className="flex-1 bg-transparent border-none outline-none text-slate-800 font-medium"
                value={searchTerm}
                onChange={e => setSearchTerm(e.target.value)}
              />
            </div>
            <div className="flex items-center gap-2 pt-2 border-t border-slate-50">
               <Calendar className="w-4 h-4 text-blue-600" />
               <input 
                 type="date"
                 className="flex-1 bg-slate-50 rounded-lg p-2 text-xs font-bold text-slate-600 outline-none"
                 value={dateFilter}
                 onChange={e => setDateFilter(e.target.value)}
               />
               <button onClick={() => setDateFilter('')} className="p-2 bg-slate-100 rounded-lg text-slate-400">
                 <X className="w-4 h-4" />
               </button>
            </div>
          </div>

          <div className="space-y-3">
            {filteredInvoices.map(inv => (
              <button 
                key={inv.id}
                onClick={() => setSelectedInvoice(inv)}
                className="w-full bg-white p-4 rounded-3xl shadow-sm border border-slate-100 flex items-center justify-between active:scale-95 transition-transform"
              >
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 bg-slate-50 rounded-2xl flex items-center justify-center text-slate-400">
                    <History className="w-6 h-6" />
                  </div>
                  <div className="text-left">
                    <h4 className="font-bold text-slate-900">{inv.clientName}</h4>
                    <p className="text-[10px] text-slate-400">
                      ID: {inv.id} • {new Date(inv.date).toLocaleDateString()}
                    </p>
                  </div>
                </div>
                <div className="text-right">
                  <p className="font-black text-blue-600">{formatCurrency(inv.grandTotal)}</p>
                  <p className="text-[9px] uppercase font-bold text-slate-400 tracking-tighter">{inv.paymentMethod}</p>
                </div>
              </button>
            ))}
            {filteredInvoices.length === 0 && (
              <div className="text-center py-20 bg-white rounded-3xl border-2 border-dashed border-slate-100">
                 <History className="w-16 h-16 text-slate-100 mx-auto mb-4" />
                 <p className="text-slate-400">No invoices found matching criteria.</p>
              </div>
            )}
          </div>
        </>
      )}
    </div>
  );
};

export default Invoices;

import React from 'react';
