                <div>
                   <p className="font-bold text-slate-900">Digital Signature</p>
                   <p className="text-[10px] text-slate-400">Used on all invoices</p>
                </div>
              </div>
              <label className="text-blue-600 font-bold text-xs bg-blue-50 px-3 py-1 rounded-full cursor-pointer">
