interface DashboardProps {
  invoices: Invoice[];
  clients: Client[];
  products: Product[];
  config: AppConfig;
  onNavigate: (tab: Tab) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ invoices, clients, products, config, onNavigate }) => {
  const [modalType, setModalType] = useState<'BORROWERS' | 'LOW_STOCK' | 'CLIENTS' | 'TOP_PRODUCTS' | null>(null);

  const totalSales = invoices.reduce((acc, inv) => acc + inv.grandTotal, 0);
  const totalBorrowAmount = clients.reduce((acc, client) => acc + client.totalBorrowed, 0);
  const lowStockItems = products.filter(p => p.stock !== null && p.stock <= config.lowStockThreshold);
  const totalCustomers = clients.length;

  // Simple logic for top products (based on frequency in invoices)
  const productCountMap: Record<string, number> = {};
  invoices.forEach(inv => {
    inv.items.forEach(item => {
      productCountMap[item.name] = (productCountMap[item.name] || 0) + item.quantity;
    });
  });
  const topProducts = Object.entries(productCountMap)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 5);

  return (
    <div className="space-y-6">
