          <div className="relative z-10">
            <p className="text-blue-100 text-sm font-medium mb-1 uppercase tracking-wider">Total Sales (Today)</p>
            <h3 className="text-3xl font-extrabold mb-4">{formatCurrency(totalSales)}</h3>
            <div className="flex gap-2">
              <span className="bg-white/20 px-3 py-1 rounded-full text-xs flex items-center gap-1">
                <ArrowUpRight className="w-3 h-3" /> 12% increase
              </span>
            </div>
          </div>
          <div className="absolute -right-10 -bottom-10 w-40 h-40 bg-white/10 rounded-full blur-3xl" />
        </div>

        <div className="grid grid-cols-2 gap-4">
          <StatCard 
            icon={<Users className="text-purple-600" />} 
            bg="bg-purple-50" 
            label="Total Clients" 
            value={totalCustomers.toString()} 
            onClick={() => setModalType('CLIENTS')}
          />
          <StatCard 
            icon={<Wallet className="text-orange-600" />} 
            bg="bg-orange-50" 
            label="Udhaar (Total)" 
            value={formatCurrency(totalBorrowAmount)} 
            onClick={() => setModalType('BORROWERS')}
          />
        </div>
      </div>

      {/* Quick Actions / Lists Buttons */}
      <div className="grid grid-cols-2 gap-3">
        <ActionButton 
          icon={<AlertCircle className="w-5 h-5" />} 
          label="Low Stock Items" 
          count={lowStockItems.length}
          color="text-red-600"
          bg="bg-red-50"
          onClick={() => setModalType('LOW_STOCK')}
        />
        <ActionButton 
          icon={<Star className="w-5 h-5" />} 
          label="Top Selling" 
          color="text-yellow-600"
          bg="bg-yellow-50"
          onClick={() => setModalType('TOP_PRODUCTS')}
        />
      </div>

      {/* Recent Activity */}
      <div className="bg-white rounded-3xl p-5 shadow-sm border border-slate-100">
        <div className="flex justify-between items-center mb-4">
          <h3 className="font-bold text-slate-900">Recent Invoices</h3>
          <button onClick={() => onNavigate(Tab.INVOICES)} className="text-blue-600 text-xs font-bold flex items-center">
            View All <ChevronRight className="w-4 h-4" />
