import React, { useState, useMemo } from 'react';
import { 
  Search, 
  UserPlus, 
  Trash2, 
  Plus, 
  Minus, 
  PlusCircle, 
  CheckCircle2,
  X,
  CreditCard,
  Banknote,
  Clock,
  Package,
  Zap
} from 'lucide-react';
import { Product, Client, Invoice, InvoiceItem, PaymentMethod, AppConfig } from '../types';
import { generateId, formatCurrency } from '../utils/helpers';
import InvoiceDetail from '../components/InvoiceDetail';

interface BillingProps {
  products: Product[];
  clients: Client[];
  setInvoices: React.Dispatch<React.SetStateAction<Invoice[]>>;
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  setClients: React.Dispatch<React.SetStateAction<Client[]>>;
  config: AppConfig;
}

const Billing: React.FC<BillingProps> = ({ products, clients, setInvoices, setProducts, setClients, config }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [cart, setCart] = useState<InvoiceItem[]>([]);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [discount, setDiscount] = useState(0);
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>(PaymentMethod.CASH);
  const [showCheckout, setShowCheckout] = useState(false);
  const [showQuickAdd, setShowQuickAdd] = useState(false);
  const [generatedInvoice, setGeneratedInvoice] = useState<Invoice | null>(null);

  // Quick Add State
  const [quickAddForm, setQuickAddForm] = useState({
    name: '',
    price: '',
    quantity: '1'
  });

  // Filtered Products
  const filteredProducts = useMemo(() => {
    if (!searchTerm) return [];
    return products.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()));
  }, [searchTerm, products]);

  const addToCart = (product: Product | { name: string, price: number, quantity?: number }) => {
    const qtyToAdd = product.quantity || 1;
    setCart(prev => {
      const existing = prev.find(item => item.name === product.name);
      if (existing) {
        return prev.map(item => item.name === product.name ? { 
          ...item, 
          quantity: item.quantity + qtyToAdd, 
          total: (item.quantity + qtyToAdd) * item.price 
        } : item);
      }
      return [...prev, {
        id: ('id' in product ? product.id : generateId()),
        name: product.name,
        quantity: qtyToAdd,
        price: product.price,
        total: product.price * qtyToAdd
      }];
    });
    setSearchTerm('');
  };

  const handleQuickAdd = (e: React.FormEvent) => {
    e.preventDefault();
    if (!quickAddForm.name || !quickAddForm.price) return;

    addToCart({
      name: quickAddForm.name,
      price: parseFloat(quickAddForm.price),
      quantity: parseInt(quickAddForm.quantity) || 1
    });

    setQuickAddForm({ name: '', price: '', quantity: '1' });
    setShowQuickAdd(false);
  };

  const updateQuantity = (name: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.name === name) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty, total: newQty * item.price };
      }
      return item;
    }));
  };

  const removeFromCart = (name: string) => {
    setCart(prev => prev.filter(item => item.name !== name));
  };

  const subtotal = cart.reduce((acc, item) => acc + item.total, 0);
  const discountAmount = (subtotal * discount) / 100;
  const grandTotal = subtotal - discountAmount;

  const handleFinish = () => {
    const invoice: Invoice = {
      id: `INV-${Date.now().toString().slice(-6)}`,
      date: new Date().toISOString(),
      clientId: selectedClient?.id || 'WALK_IN',
      clientName: selectedClient?.name || 'Walk-in Customer',
      clientMobile: selectedClient?.mobile,
      items: [...cart],
      discount,
      subtotal,
      grandTotal,
      paymentMethod
    };

    setInvoices(prev => [...prev, invoice]);

    setProducts(prev => prev.map(p => {
      const cartItem = cart.find(item => item.name === p.name);
      if (cartItem && p.stock !== null) {
        return { ...p, stock: p.stock - cartItem.quantity };
      }
      return p;
    }));

    if (paymentMethod === PaymentMethod.BORROW && selectedClient) {
      setClients(prev => prev.map(c => 
        c.id === selectedClient.id ? { ...c, totalBorrowed: c.totalBorrowed + grandTotal } : c
      ));
    }

    setGeneratedInvoice(invoice);
    setShowCheckout(false);
    setCart([]);
    setSelectedClient(null);
  };

  if (generatedInvoice) {
    return (
      <div className="space-y-4">
        <div className="bg-green-50 text-green-700 p-4 rounded-3xl border border-green-100 flex items-center gap-3">
          <CheckCircle2 className="w-6 h-6" />
          <p className="font-bold">Invoice generated successfully!</p>
        </div>
        <InvoiceDetail invoice={generatedInvoice} config={config} />
        <button 
          onClick={() => setGeneratedInvoice(null)}
          className="w-full bg-slate-100 text-slate-700 py-3 rounded-2xl font-bold"
        >
          Create New Bill
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-6 pb-20">
      {/* Header with Search & Quick Add */}
      <div className="bg-white p-5 rounded-3xl shadow-sm border border-slate-100 space-y-4">
        <div className="flex items-center gap-2">
          <div className="flex-1 relative">
            <Search className="absolute left-3 top-3.5 w-5 h-5 text-slate-400" />
            <input 
              type="text"
              placeholder="Khojein (Search)..."
              className="w-full pl-11 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl outline-none focus:ring-2 focus:ring-blue-500 text-slate-900 font-medium"
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
            />
          </div>
          <button 
            title="Quick Add"
            onClick={() => setShowQuickAdd(true)}
            className="p-3 bg-blue-100 text-blue-600 rounded-2xl hover:bg-blue-200 transition-colors"
          >
            <Zap className="w-6 h-6" />
          </button>
          <button 
            className={`p-3 rounded-2xl ${selectedClient ? 'bg-blue-600 text-white' : 'bg-slate-100 text-slate-500'}`}
            onClick={() => {
               const c = prompt("Grahak ka naam likhein (Client Name):");
               if (c) {
                 const existing = clients.find(cl => cl.name.toLowerCase() === c.toLowerCase());
                 if (existing) {
                   setSelectedClient(existing);
                 } else {
                   const newC: Client = { id: generateId(), name: c, totalBorrowed: 0 };
                   setClients(prev => [...prev, newC]);
                   setSelectedClient(newC);
                 }
               }
            }}
          >
            <UserPlus className="w-6 h-6" />
          </button>
        </div>

        {selectedClient && (
          <div className="flex justify-between items-center bg-blue-50 p-3 rounded-xl border border-blue-100">
            <div>
              <p className="text-[10px] font-bold text-blue-600 uppercase tracking-tighter">Grahak (Customer)</p>
              <p className="text-sm font-bold text-blue-900">{selectedClient.name}</p>
            </div>
            <button onClick={() => setSelectedClient(null)} className="text-blue-400 p-1"><X className="w-4 h-4" /></button>
          </div>
        )}

        {/* Search Results Dropdown */}
        {searchTerm && (
          <div className="max-h-60 overflow-y-auto border-t border-slate-100 pt-2 space-y-2">
            {filteredProducts.map(p => (
              <button 
                key={p.id}
                onClick={() => addToCart(p)}
                className="w-full flex justify-between items-center p-3 hover:bg-slate-50 rounded-xl transition-colors"
              >
                <div className="text-left">
                  <p className="font-semibold text-slate-900">{p.name}</p>
                  <p className="text-xs text-slate-400">Stock: {p.stock === null ? '∞' : p.stock}</p>
                </div>
                <p className="font-bold text-blue-600">{formatCurrency(p.price)}</p>
              </button>
            ))}
            <button 
               onClick={() => setShowQuickAdd(true)}
               className="w-full p-3 text-blue-600 font-bold text-sm border-2 border-dashed border-blue-100 rounded-xl flex items-center justify-center gap-2 mt-2"
            >
              <PlusCircle className="w-4 h-4" /> Naya Product Jodein (New Item)
            </button>
          </div>
        )}
      </div>

      {/* Quick Add Modal */}
      {showQuickAdd && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[60] flex items-end justify-center">
          <div className="bg-white w-full max-w-lg rounded-t-[2.5rem] p-6 animate-slide-up shadow-2xl">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold text-slate-900">Turant Jodein (Quick Add)</h3>
              <button onClick={() => setShowQuickAdd(false)} className="p-2 bg-slate-100 rounded-full text-slate-500"><X className="w-5 h-5" /></button>
            </div>
            <form onSubmit={handleQuickAdd} className="space-y-4">
              <div>
                <label className="text-xs font-bold text-slate-500 uppercase ml-1">Product Ka Naam</label>
                <input 
                  type="text" 
                  autoFocus
                  required
                  placeholder="e.g. Milk, Bread"
                  className="w-full mt-1 p-4 bg-slate-50 border border-slate-200 rounded-2xl text-slate-900 font-semibold focus:ring-2 focus:ring-blue-500 outline-none"
                  value={quickAddForm.name}
                  onChange={e => setQuickAddForm({...quickAddForm, name: e.target.value})}
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-xs font-bold text-slate-500 uppercase ml-1">Price (₹)</label>
                  <input 
                    type="number" 
                    required
                    placeholder="0.00"
                    className="w-full mt-1 p-4 bg-slate-50 border border-slate-200 rounded-2xl text-slate-900 font-semibold focus:ring-2 focus:ring-blue-500 outline-none"
                    value={quickAddForm.price}
                    onChange={e => setQuickAddForm({...quickAddForm, price: e.target.value})}
                  />
                </div>
                <div>
                  <label className="text-xs font-bold text-slate-500 uppercase ml-1">Quantity</label>
                  <input 
                    type="number" 
                    required
                    placeholder="1"
                    className="w-full mt-1 p-4 bg-slate-50 border border-slate-200 rounded-2xl text-slate-900 font-semibold focus:ring-2 focus:ring-blue-500 outline-none"
                    value={quickAddForm.quantity}
                    onChange={e => setQuickAddForm({...quickAddForm, quantity: e.target.value})}
                  />
                </div>
              </div>
              <button 
                type="submit"
                className="w-full bg-blue-600 text-white py-4 rounded-2xl font-bold shadow-lg shadow-blue-200 mt-2 active:scale-95 transition-all"
              >
                Cart Mein Daalein (Add to Cart)
              </button>
            </form>
          </div>
        </div>
      )}

      {/* Cart Items */}
      <div className="bg-white rounded-[2.5rem] p-6 shadow-sm border border-slate-100">
        <h3 className="font-bold text-slate-900 mb-6 flex items-center gap-2">
          Cart Summary <span className="bg-blue-50 text-blue-600 text-xs py-1 px-3 rounded-full font-bold">{cart.length} items</span>
        </h3>

        {cart.length === 0 ? (
          <div className="text-center py-12">
            <Package className="w-16 h-16 text-slate-100 mx-auto mb-4" />
            <p className="text-slate-400 font-medium">Cart khaali hai. Items jodein!</p>
          </div>
        ) : (
          <div className="space-y-6">
            {cart.map(item => (
              <div key={item.name} className="flex items-center justify-between group">
                <div className="flex-1">
                  <p className="font-bold text-slate-900 text-sm">{item.name}</p>
                  <p className="text-xs text-slate-400 font-medium">{formatCurrency(item.price)} per unit</p>
                </div>
                <div className="flex items-center gap-4">
                  <div className="flex items-center bg-slate-50 border border-slate-100 rounded-xl px-1">
                    <button onClick={() => updateQuantity(item.name, -1)} className="p-2 text-slate-600 hover:text-blue-600"><Minus className="w-4 h-4" /></button>
                    <span className="w-8 text-center font-bold text-sm text-slate-900">{item.quantity}</span>
                    <button onClick={() => updateQuantity(item.name, 1)} className="p-2 text-slate-600 hover:text-blue-600"><Plus className="w-4 h-4" /></button>
                  </div>
                  <button onClick={() => removeFromCart(item.name)} className="text-slate-300 hover:text-red-500 transition-colors">
                    <Trash2 className="w-5 h-5" />
                  </button>
                </div>
              </div>
            ))}

            <div className="border-t border-slate-100 pt-6 space-y-3">
              <div className="flex justify-between text-sm text-slate-500 font-medium">
                <span>Subtotal</span>
                <span>{formatCurrency(subtotal)}</span>
              </div>
              <div className="flex justify-between text-sm text-slate-500 items-center font-medium">
                <span>Discount (%)</span>
                <input 
                  type="number"
                  className="w-16 text-right bg-slate-50 border border-slate-200 rounded-lg p-1 outline-none font-bold text-slate-900 focus:border-blue-500"
                  value={discount}
                  onChange={e => setDiscount(Math.min(100, Math.max(0, parseInt(e.target.value) || 0)))}
                />
              </div>
              <div className="flex justify-between text-lg font-black text-blue-700 pt-3 border-t border-blue-50">
                <span>Total Amount</span>
                <span>{formatCurrency(grandTotal)}</span>
              </div>
            </div>

            <button 
              onClick={() => setShowCheckout(true)}
              className="w-full bg-blue-600 text-white py-4 rounded-2xl font-bold shadow-lg shadow-blue-100 flex items-center justify-center gap-2 active:scale-95 transition-all"
            >
              Checkout Karein <ChevronRight className="w-5 h-5" />
            </button>
          </div>
        )}
      </div>

      {/* Checkout Bottom Sheet */}
      {showCheckout && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[70] flex items-end justify-center">
          <div className="bg-white w-full max-w-lg rounded-t-[2.5rem] p-6 animate-slide-up">
            <div className="flex justify-between items-center mb-8">
              <h3 className="text-xl font-bold text-slate-900">Payment Chuney (Payment)</h3>
              <button onClick={() => setShowCheckout(false)} className="p-2 bg-slate-100 rounded-full text-slate-400"><X className="w-5 h-5" /></button>
            </div>

            <div className="grid grid-cols-1 gap-4 mb-8">
              <PaymentOption 
                active={paymentMethod === PaymentMethod.CASH}
                onClick={() => setPaymentMethod(PaymentMethod.CASH)}
                icon={<Banknote className="w-6 h-6" />}
                label="Cash Payment"
                desc="Fastest way to settle"
              />
              <PaymentOption 
                active={paymentMethod === PaymentMethod.ONLINE}
                onClick={() => setPaymentMethod(PaymentMethod.ONLINE)}
                icon={<CreditCard className="w-6 h-6" />}
                label="Online / UPI"
                desc="Show QR code for payment"
              />
              <PaymentOption 
                active={paymentMethod === PaymentMethod.BORROW}
                onClick={() => setPaymentMethod(PaymentMethod.BORROW)}
                icon={<Clock className="w-6 h-6" />}
                label="Udhaar (Borrow)"
                desc="Add to customer's account"
                disabled={!selectedClient}
              />
              {!selectedClient && (
                <p className="text-xs text-red-500 font-medium px-2">* Udhaar ke liye grahak chuney</p>
              )}
            </div>

            <button 
              onClick={handleFinish}
              className="w-full bg-blue-600 text-white py-4 rounded-2xl font-bold shadow-lg active:scale-95 transition-all"
            >
              Bill Banayein (Generate Bill)
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

const PaymentOption: React.FC<{ active: boolean, onClick: () => void, icon: React.ReactNode, label: string, desc: string, disabled?: boolean }> = ({ active, onClick, icon, label, desc, disabled }) => (
  <button 
    onClick={onClick}
    disabled={disabled}
    className={`flex items-center gap-4 p-4 rounded-2xl border-2 transition-all ${disabled ? 'opacity-50 grayscale cursor-not-allowed' : 'cursor-pointer'} ${active ? 'bg-blue-50 border-blue-600' : 'bg-white border-slate-100 hover:border-blue-200'}`}
  >
    <div className={`p-3 rounded-xl ${active ? 'bg-blue-600 text-white' : 'bg-slate-50 text-slate-400'}`}>
      {icon}
    </div>
    <div className="text-left">
      <p className="font-bold text-slate-900">{label}</p>
      <p className="text-xs text-slate-400 font-medium">{desc}</p>
    </div>
    {active && <CheckCircle2 className="w-6 h-6 text-blue-600 ml-auto" />}
  </button>
);

const ChevronRight: React.FC<{ className?: string }> = ({ className }) => (
  <svg className={className} width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><path d="m9 18 6-6-6-6"/></svg>
);

export default Billing;

import React, { useState, useMemo } from 'react';
import { 
  Search, 
  UserPlus, 
  Trash2, 
  Plus, 
  Minus, 
  PlusCircle, 
  CheckCircle2,
  X,
  CreditCard,
  Banknote,
  Clock,
  Package,
  Zap
} from 'lucide-react';
import { Product, Client, Invoice, InvoiceItem, PaymentMethod, AppConfig } from '../types';
import { generateId, formatCurrency } from '../utils/helpers';
import InvoiceDetail from '../components/InvoiceDetail';

interface BillingProps {
  products: Product[];
  clients: Client[];
  setInvoices: React.Dispatch<React.SetStateAction<Invoice[]>>;
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  setClients: React.Dispatch<React.SetStateAction<Client[]>>;
  config: AppConfig;
}

const Billing: React.FC<BillingProps> = ({ products, clients, setInvoices, setProducts, setClients, config }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [cart, setCart] = useState<InvoiceItem[]>([]);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [discount, setDiscount] = useState(0);
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>(PaymentMethod.CASH);
  const [showCheckout, setShowCheckout] = useState(false);
  const [showQuickAdd, setShowQuickAdd] = useState(false);
  const [generatedInvoice, setGeneratedInvoice] = useState<Invoice | null>(null);

  // Quick Add State
  const [quickAddForm, setQuickAddForm] = useState({
    name: '',
    price: '',
    quantity: '1'
  });

  // Filtered Products
  const filteredProducts = useMemo(() => {
    if (!searchTerm) return [];
    return products.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()));
  }, [searchTerm, products]);

  // Fix: Correctly access quantity from union type using 'in' operator to safely check for property existence
  const addToCart = (product: Product | { name: string, price: number, quantity?: number }) => {
    const qtyToAdd = 'quantity' in product ? (product.quantity || 1) : 1;
    setCart(prev => {
      const existing = prev.find(item => item.name === product.name);
      if (existing) {
        return prev.map(item => item.name === product.name ? { 
          ...item, 
          quantity: item.quantity + qtyToAdd, 
          total: (item.quantity + qtyToAdd) * item.price 
        } : item);
      }
      return [...prev, {
        id: ('id' in product ? product.id : generateId()),
        name: product.name,
        quantity: qtyToAdd,
        price: product.price,
        total: product.price * qtyToAdd
      }];
    });
    setSearchTerm('');
  };

  const handleQuickAdd = (e: React.FormEvent) => {
    e.preventDefault();
    if (!quickAddForm.name || !quickAddForm.price) return;

    addToCart({
      name: quickAddForm.name,
      price: parseFloat(quickAddForm.price),
      quantity: parseInt(quickAddForm.quantity) || 1
    });

    setQuickAddForm({ name: '', price: '', quantity: '1' });
    setShowQuickAdd(false);
  };

  const updateQuantity = (name: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.name === name) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty, total: newQty * item.price };
      }
      return item;
    }));
  };

  const removeFromCart = (name: string) => {
    setCart(prev => prev.filter(item => item.name !== name));
  };

  const subtotal = cart.reduce((acc, item) => acc + item.total, 0);
  const discountAmount = (subtotal * discount) / 100;
  const grandTotal = subtotal - discountAmount;

  const handleFinish = () => {
    const invoice: Invoice = {
      id: `INV-${Date.now().toString().slice(-6)}`,
      date: new Date().toISOString(),
      clientId: selectedClient?.id || 'WALK_IN',
      clientName: selectedClient?.name || 'Walk-in Customer',
      clientMobile: selectedClient?.mobile,
      items: [...cart],
      discount,
      subtotal,
      grandTotal,
      paymentMethod
    };

    setInvoices(prev => [...prev, invoice]);

    setProducts(prev => prev.map(p => {
      const cartItem = cart.find(item => item.name === p.name);
      if (cartItem && p.stock !== null) {
        return { ...p, stock: p.stock - cartItem.quantity };
      }
      return p;
    }));

    if (paymentMethod === PaymentMethod.BORROW && selectedClient) {
      setClients(prev => prev.map(c => 
        c.id === selectedClient.id ? { ...c, totalBorrowed: c.totalBorrowed + grandTotal } : c
      ));
    }

    setGeneratedInvoice(invoice);
    setShowCheckout(false);
    setCart([]);
    setSelectedClient(null);
  };

  if (generatedInvoice) {
    return (
      <div className="space-y-4">
        <div className="bg-green-50 text-green-700 p-4 rounded-3xl border border-green-100 flex items-center gap-3">
          <CheckCircle2 className="w-6 h-6" />
          <p className="font-bold">Invoice generated successfully!</p>
        </div>
        <InvoiceDetail invoice={generatedInvoice} config={config} />
        <button 
          onClick={() => setGeneratedInvoice(null)}
          className="w-full bg-slate-100 text-slate-700 py-3 rounded-2xl font-bold"
        >
          Create New Bill
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-6 pb-20">
      {/* Header with Search & Quick Add */}
      <div className="bg-white p-5 rounded-3xl shadow-sm border border-slate-100 space-y-4">
        <div className="flex items-center gap-2">
          <div className="flex-1 relative">
            <Search className="absolute left-3 top-3.5 w-5 h-5 text-slate-400" />
            <input 
              type="text"
              placeholder="Khojein (Search)..."
              className="w-full pl-11 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl outline-none focus:ring-2 focus:ring-blue-500 text-slate-900 font-medium"
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
            />
          </div>
          <button 
            title="Quick Add"
            onClick={() => setShowQuickAdd(true)}
            className="p-3 bg-blue-100 text-blue-600 rounded-2xl hover:bg-blue-200 transition-colors"
          >
            <Zap className="w-6 h-6" />
          </button>
          <button 
            className={`p-3 rounded-2xl ${selectedClient ? 'bg-blue-600 text-white' : 'bg-slate-100 text-slate-500'}`}
            onClick={() => {
               const c = prompt("Grahak ka naam likhein (Client Name):");
               if (c) {
                 const existing = clients.find(cl => cl.name.toLowerCase() === c.toLowerCase());
                 if (existing) {
                   setSelectedClient(existing);
                 } else {
                   const newC: Client = { id: generateId(), name: c, totalBorrowed: 0 };
                   setClients(prev => [...prev, newC]);
                   setSelectedClient(newC);
                 }
               }
            }}
          >
            <UserPlus className="w-6 h-6" />
          </button>
        </div>

        {selectedClient && (
          <div className="flex justify-between items-center bg-blue-50 p-3 rounded-xl border border-blue-100">
            <div>
              <p className="text-[10px] font-bold text-blue-600 uppercase tracking-tighter">Grahak (Customer)</p>
              <p className="text-sm font-bold text-blue-900">{selectedClient.name}</p>
            </div>
            <button onClick={() => setSelectedClient(null)} className="text-blue-400 p-1"><X className="w-4 h-4" /></button>
          </div>
        )}

        {/* Search Results Dropdown */}
        {searchTerm && (
          <div className="max-h-60 overflow-y-auto border-t border-slate-100 pt-2 space-y-2">
            {filteredProducts.map(p => (
              <button 
                key={p.id}
                onClick={() => addToCart(p)}
                className="w-full flex justify-between items-center p-3 hover:bg-slate-50 rounded-xl transition-colors"
              >
                <div className="text-left">
                  <p className="font-semibold text-slate-900">{p.name}</p>
                  <p className="text-xs text-slate-400">Stock: {p.stock === null ? '∞' : p.stock}</p>
                </div>
                <p className="font-bold text-blue-600">{formatCurrency(p.price)}</p>
              </button>
            ))}
            <button 
               onClick={() => setShowQuickAdd(true)}
               className="w-full p-3 text-blue-600 font-bold text-sm border-2 border-dashed border-blue-100 rounded-xl flex items-center justify-center gap-2 mt-2"
            >
              <PlusCircle className="w-4 h-4" /> Naya Product Jodein (New Item)
            </button>
          </div>
        )}
      </div>

      {/* Quick Add Modal */}
      {showQuickAdd && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[60] flex items-end justify-center">
          <div className="bg-white w-full max-w-lg rounded-t-[2.5rem] p-6 animate-slide-up shadow-2xl">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold text-slate-900">Turant Jodein (Quick Add)</h3>
              <button onClick={() => setShowQuickAdd(false)} className="p-2 bg-slate-100 rounded-full text-slate-500"><X className="w-5 h-5" /></button>
            </div>
            <form onSubmit={handleQuickAdd} className="space-y-4">
              <div>
                <label className="text-xs font-bold text-slate-500 uppercase ml-1">Product Ka Naam</label>
                <input 
                  type="text" 
                  autoFocus
                  required
                  placeholder="e.g. Milk, Bread"
                  className="w-full mt-1 p-4 bg-slate-50 border border-slate-200 rounded-2xl text-slate-900 font-semibold focus:ring-2 focus:ring-blue-500 outline-none"
                  value={quickAddForm.name}
                  onChange={e => setQuickAddForm({...quickAddForm, name: e.target.value})}
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-xs font-bold text-slate-500 uppercase ml-1">Price (₹)</label>
                  <input 
                    type="number" 
                    required
                    placeholder="0.00"
                    className="w-full mt-1 p-4 bg-slate-50 border border-slate-200 rounded-2xl text-slate-900 font-semibold focus:ring-2 focus:ring-blue-500 outline-none"
                    value={quickAddForm.price}
                    onChange={e => setQuickAddForm({...quickAddForm, price: e.target.value})}
                  />
                </div>
                <div>
                  <label className="text-xs font-bold text-slate-500 uppercase ml-1">Quantity</label>
                  <input 
                    type="number" 
                    required
                    placeholder="1"
                    className="w-full mt-1 p-4 bg-slate-50 border border-slate-200 rounded-2xl text-slate-900 font-semibold focus:ring-2 focus:ring-blue-500 outline-none"
                    value={quickAddForm.quantity}
                    onChange={e => setQuickAddForm({...quickAddForm, quantity: e.target.value})}
                  />
                </div>
              </div>
              <button 
                type="submit"
                className="w-full bg-blue-600 text-white py-4 rounded-2xl font-bold shadow-lg shadow-blue-200 mt-2 active:scale-95 transition-all"
              >
                Cart Mein Daalein (Add to Cart)
              </button>
            </form>
          </div>
        </div>
      )}

      {/* Cart Items */}
      <div className="bg-white rounded-[2.5rem] p-6 shadow-sm border border-slate-100">
        <h3 className="font-bold text-slate-900 mb-6 flex items-center gap-2">
          Cart Summary <span className="bg-blue-50 text-blue-600 text-xs py-1 px-3 rounded-full font-bold">{cart.length} items</span>
        </h3>

        {cart.length === 0 ? (
          <div className="text-center py-12">
            <Package className="w-16 h-16 text-slate-100 mx-auto mb-4" />
            <p className="text-slate-400 font-medium">Cart khaali hai. Items jodein!</p>
          </div>
        ) : (
          <div className="space-y-6">
            {cart.map(item => (
              <div key={item.name} className="flex items-center justify-between group">
                <div className="flex-1">
                  <p className="font-bold text-slate-900 text-sm">{item.name}</p>
                  <p className="text-xs text-slate-400 font-medium">{formatCurrency(item.price)} per unit</p>
                </div>
                <div className="flex items-center gap-4">
                  <div className="flex items-center bg-slate-50 border border-slate-100 rounded-xl px-1">
                    <button onClick={() => updateQuantity(item.name, -1)} className="p-2 text-slate-600 hover:text-blue-600"><Minus className="w-4 h-4" /></button>
                    <span className="w-8 text-center font-bold text-sm text-slate-900">{item.quantity}</span>
                    <button onClick={() => updateQuantity(item.name, 1)} className="p-2 text-slate-600 hover:text-blue-600"><Plus className="w-4 h-4" /></button>
                  </div>
                  <button onClick={() => removeFromCart(item.name)} className="text-slate-300 hover:text-red-500 transition-colors">
                    <Trash2 className="w-5 h-5" />
                  </button>
                </div>
              </div>
            ))}

            <div className="border-t border-slate-100 pt-6 space-y-3">
              <div className="flex justify-between text-sm text-slate-500 font-medium">
                <span>Subtotal</span>
                <span>{formatCurrency(subtotal)}</span>
              </div>
              <div className="flex justify-between text-sm text-slate-500 items-center font-medium">
                <span>Discount (%)</span>
                <input 
                  type="number"
                  className="w-16 text-right bg-slate-50 border border-slate-200 rounded-lg p-1 outline-none font-bold text-slate-900 focus:border-blue-500"
                  value={discount}
                  onChange={e => setDiscount(Math.min(100, Math.max(0, parseInt(e.target.value) || 0)))}
                />
              </div>
              <div className="flex justify-between text-lg font-black text-blue-700 pt-3 border-t border-blue-50">
                <span>Total Amount</span>
                <span>{formatCurrency(grandTotal)}</span>
              </div>
            </div>

            <button 
              onClick={() => setShowCheckout(true)}
              className="w-full bg-blue-600 text-white py-4 rounded-2xl font-bold shadow-lg shadow-blue-100 flex items-center justify-center gap-2 active:scale-95 transition-all"
            >
              Checkout Karein <ChevronRight className="w-5 h-5" />
            </button>
          </div>
        )}
      </div>

      {/* Checkout Bottom Sheet */}
      {showCheckout && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[70] flex items-end justify-center">
          <div className="bg-white w-full max-w-lg rounded-t-[2.5rem] p-6 animate-slide-up">
            <div className="flex justify-between items-center mb-8">
              <h3 className="text-xl font-bold text-slate-900">Payment Chuney (Payment)</h3>
              <button onClick={() => setShowCheckout(false)} className="p-2 bg-slate-100 rounded-full text-slate-400"><X className="w-5 h-5" /></button>
            </div>

            <div className="grid grid-cols-1 gap-4 mb-8">
              <PaymentOption 
                active={paymentMethod === PaymentMethod.CASH}
                onClick={() => setPaymentMethod(PaymentMethod.CASH)}
                icon={<Banknote className="w-6 h-6" />}
                label="Cash Payment"
                desc="Fastest way to settle"
              />
              <PaymentOption 
                active={paymentMethod === PaymentMethod.ONLINE}
                onClick={() => setPaymentMethod(PaymentMethod.ONLINE)}
                icon={<CreditCard className="w-6 h-6" />}
                label="Online / UPI"
                desc="Show QR code for payment"
              />
              <PaymentOption 
                active={paymentMethod === PaymentMethod.BORROW}
                onClick={() => setPaymentMethod(PaymentMethod.BORROW)}
                icon={<Clock className="w-6 h-6" />}
                label="Udhaar (Borrow)"
                desc="Add to customer's account"
                disabled={!selectedClient}
              />
              {!selectedClient && (
                <p className="text-xs text-red-500 font-medium px-2">* Udhaar ke liye grahak chuney</p>
              )}
            </div>

            <button 
              onClick={handleFinish}
              className="w-full bg-blue-600 text-white py-4 rounded-2xl font-bold shadow-lg active:scale-95 transition-all"
            >
              Bill Banayein (Generate Bill)
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

const PaymentOption: React.FC<{ active: boolean, onClick: () => void, icon: React.ReactNode, label: string, desc: string, disabled?: boolean }> = ({ active, onClick, icon, label, desc, disabled }) => (
  <button 
    onClick={onClick}
    disabled={disabled}
    className={`flex items-center gap-4 p-4 rounded-2xl border-2 transition-all ${disabled ? 'opacity-50 grayscale cursor-not-allowed' : 'cursor-pointer'} ${active ? 'bg-blue-50 border-blue-600' : 'bg-white border-slate-100 hover:border-blue-200'}`}
  >
    <div className={`p-3 rounded-xl ${active ? 'bg-blue-600 text-white' : 'bg-slate-50 text-slate-400'}`}>
      {icon}
    </div>
    <div className="text-left">
      <p className="font-bold text-slate-900">{label}</p>
      <p className="text-xs text-slate-400 font-medium">{desc}</p>
    </div>
    {active && <CheckCircle2 className="w-6 h-6 text-blue-600 ml-auto" />}
  </button>
);

const ChevronRight: React.FC<{ className?: string }> = ({ className }) => (
  <svg className={className} width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><path d="m9 18 6-6-6-6"/></svg>
);

export default Billing;

import React, { useState, useMemo } from 'react';
import { 
  Search, 
  UserPlus, 
  Trash2, 
  Plus, 
  Minus, 
  PlusCircle, 
  CheckCircle2,
  X,
  CreditCard,
  Banknote,
  Clock,
  Package,
  Zap,
  Users
} from 'lucide-react';
import { Product, Client, Invoice, InvoiceItem, PaymentMethod, AppConfig } from '../types';
import { generateId, formatCurrency } from '../utils/helpers';
import InvoiceDetail from '../components/InvoiceDetail';

interface BillingProps {
  products: Product[];
  clients: Client[];
  setInvoices: React.Dispatch<React.SetStateAction<Invoice[]>>;
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  setClients: React.Dispatch<React.SetStateAction<Client[]>>;
  config: AppConfig;
}

const Billing: React.FC<BillingProps> = ({ products, clients, setInvoices, setProducts, setClients, config }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [cart, setCart] = useState<InvoiceItem[]>([]);
  const [custName, setCustName] = useState('');
  const [custMobile, setCustMobile] = useState('');
  const [selectedClientId, setSelectedClientId] = useState<string | null>(null);

  const [discount, setDiscount] = useState(0);
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>(PaymentMethod.CASH);
  const [showCheckout, setShowCheckout] = useState(false);
  const [showQuickAdd, setShowQuickAdd] = useState(false);
  const [showClientList, setShowClientList] = useState(false);
  const [generatedInvoice, setGeneratedInvoice] = useState<Invoice | null>(null);

  const [quickAddForm, setQuickAddForm] = useState({ name: '', price: '', quantity: '1' });

  const filteredProducts = useMemo(() => {
    if (!searchTerm) return [];
    return products.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()));
  }, [searchTerm, products]);

  const addToCart = (product: Product | { name: string, price: number, quantity?: number }) => {
    const qtyToAdd = 'quantity' in product ? (product.quantity || 1) : 1;
    setCart(prev => {
      const existing = prev.find(item => item.name === product.name);
      if (existing) {
        return prev.map(item => item.name === product.name ? { 
          ...item, 
          quantity: item.quantity + qtyToAdd, 
          total: (item.quantity + qtyToAdd) * item.price 
        } : item);
      }
      return [...prev, {
        id: ('id' in product ? product.id : generateId()),
        name: product.name,
        quantity: qtyToAdd,
        price: product.price,
        total: product.price * qtyToAdd
      }];
    });
    setSearchTerm('');
  };

  const handleFinish = () => {
    if (!custName) {
      alert("Kripya Grahak ka naam likhein!");
      return;
    }

    const invoice: Invoice = {
      id: `INV-${Date.now().toString().slice(-6)}`,
      date: new Date().toISOString(),
      clientId: selectedClientId || 'WALK_IN',
      clientName: custName,
      clientMobile: custMobile,
      items: [...cart],
      discount,
      subtotal: cart.reduce((acc, i) => acc + i.total, 0),
      grandTotal: (cart.reduce((acc, i) => acc + i.total, 0)) * (1 - discount/100),
      paymentMethod
    };

    setInvoices(prev => [...prev, invoice]);

    setProducts(prev => prev.map(p => {
      const cartItem = cart.find(item => item.name === p.name);
      return (cartItem && p.stock !== null) ? { ...p, stock: p.stock - cartItem.quantity } : p;
    }));

    if (paymentMethod === PaymentMethod.BORROW) {
      // Find or create client for borrowing
      setClients(prev => {
        const existingIdx = prev.findIndex(c => c.name === custName || c.id === selectedClientId);
        if (existingIdx > -1) {
          const updated = [...prev];
          updated[existingIdx].totalBorrowed += invoice.grandTotal;
          return updated;
        } else {
          return [...prev, { id: generateId(), name: custName, mobile: custMobile, totalBorrowed: invoice.grandTotal }];
        }
      });
    }

    setGeneratedInvoice(invoice);
    setShowCheckout(false);
    setCart([]);
    setCustName('');
    setCustMobile('');
    setSelectedClientId(null);
  };

  if (generatedInvoice) {
    return (
      <div className="space-y-4">
        <div className="bg-green-50 text-green-700 p-4 rounded-3xl border border-green-100 flex items-center gap-3">
          <CheckCircle2 className="w-6 h-6" />
          <p className="font-bold">Bill generate ho gaya!</p>
        </div>
        <InvoiceDetail invoice={generatedInvoice} config={config} />
        <button onClick={() => setGeneratedInvoice(null)} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold">Naya Bill Banayein</button>
      </div>
    );
  }

  const subtotal = cart.reduce((acc, item) => acc + item.total, 0);
  const grandTotal = subtotal * (1 - discount / 100);

  return (
    <div className="space-y-6 pb-24">
      {/* Customer Info Card */}
      <div className="bg-white p-5 rounded-3xl shadow-sm border border-slate-100 space-y-4">
        <div className="flex justify-between items-center mb-2">
          <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest">Grahak Ki Detail</h3>
          <button onClick={() => setShowClientList(true)} className="flex items-center gap-1 text-blue-600 font-bold text-xs bg-blue-50 px-3 py-1.5 rounded-full">
            <Users className="w-3.5 h-3.5" /> List se Chunein
          </button>
        </div>
        <div className="grid grid-cols-1 gap-3">
          <input 
            type="text" placeholder="Grahak ka Naam (Name) *" 
            className="w-full p-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-slate-900 font-bold outline-none focus:ring-2 focus:ring-blue-500"
            value={custName} onChange={e => setCustName(e.target.value)}
          />
          <input 
            type="tel" placeholder="Mobile Number (Optional)" 
            className="w-full p-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-slate-900 font-bold outline-none focus:ring-2 focus:ring-blue-500"
            value={custMobile} onChange={e => setCustMobile(e.target.value.replace(/[^0-9]/g, ''))}
          />
        </div>
      </div>

      {/* Search & Quick Add */}
      <div className="bg-white p-5 rounded-3xl shadow-sm border border-slate-100 space-y-4">
        <div className="flex items-center gap-2">
          <div className="flex-1 relative">
            <Search className="absolute left-3 top-3.5 w-5 h-5 text-slate-400" />
            <input 
              type="text" placeholder="Product Khojein..." 
              className="w-full pl-11 pr-4 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-slate-900 font-bold outline-none focus:ring-2 focus:ring-blue-500"
              value={searchTerm} onChange={e => setSearchTerm(e.target.value)}
            />
          </div>
          <button onClick={() => setShowQuickAdd(true)} className="p-3.5 bg-blue-600 text-white rounded-2xl shadow-lg shadow-blue-100"><Zap className="w-6 h-6" /></button>
        </div>

        {searchTerm && filteredProducts.length > 0 && (
          <div className="max-h-60 overflow-y-auto border-t border-slate-100 pt-2 space-y-2">
            {filteredProducts.map(p => (
              <button key={p.id} onClick={() => addToCart(p)} className="w-full flex justify-between items-center p-3 hover:bg-slate-50 rounded-xl transition-colors">
                <div className="text-left">
                  <p className="font-bold text-slate-900">{p.name}</p>
                  <p className="text-[10px] text-slate-400 font-bold uppercase">Stock: {p.stock ?? '∞'}</p>
                </div>
                <p className="font-black text-blue-600">{formatCurrency(p.price)}</p>
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Cart List */}
      <div className="bg-white rounded-[2.5rem] p-6 shadow-sm border border-slate-100">
        <h3 className="font-bold text-slate-900 mb-6">Cart List ({cart.length})</h3>
        {cart.length === 0 ? (
          <div className="text-center py-10"><Package className="w-16 h-16 text-slate-100 mx-auto mb-4" /><p className="text-slate-400 font-medium italic">Cart khaali hai</p></div>
        ) : (
          <div className="space-y-6">
            {cart.map(item => (
              <div key={item.name} className="flex items-center justify-between">
                <div className="flex-1">
                  <p className="font-bold text-slate-900">{item.name}</p>
                  <p className="text-xs text-slate-400 font-bold">{formatCurrency(item.price)}</p>
                </div>
                <div className="flex items-center gap-3">
                  <div className="flex items-center bg-slate-50 border rounded-xl p-1">
                    <button onClick={() => { setCart(prev => prev.map(i => i.name === item.name ? {...i, quantity: Math.max(1, i.quantity - 1), total: Math.max(1, i.quantity - 1)*i.price} : i)) }} className="p-1"><Minus className="w-4 h-4" /></button>
                    <span className="w-8 text-center font-bold text-slate-900">{item.quantity}</span>
                    <button onClick={() => { setCart(prev => prev.map(i => i.name === item.name ? {...i, quantity: i.quantity + 1, total: (i.quantity+1)*i.price} : i)) }} className="p-1"><Plus className="w-4 h-4" /></button>
                  </div>
                  <button onClick={() => setCart(prev => prev.filter(i => i.name !== item.name))} className="text-slate-300"><Trash2 className="w-5 h-5" /></button>
                </div>
              </div>
            ))}
            <div className="border-t border-slate-100 pt-6 space-y-3">
              <div className="flex justify-between text-sm text-slate-500 font-bold"><span>Subtotal</span><span>{formatCurrency(subtotal)}</span></div>
              <div className="flex justify-between items-center text-sm text-slate-500 font-bold">
                <span>Discount (%)</span>
                <input type="number" className="w-16 text-right p-1 bg-slate-50 border rounded-lg font-bold text-slate-900" value={discount} onChange={e => setDiscount(Number(e.target.value) || 0)} />
              </div>
              <div className="flex justify-between text-lg font-black text-blue-700 pt-3 border-t border-blue-50"><span>Grand Total</span><span>{formatCurrency(grandTotal)}</span></div>
            </div>
            <button onClick={() => setShowCheckout(true)} className="w-full bg-blue-600 text-white py-4 rounded-2xl font-bold shadow-lg shadow-blue-200">Payment Karein</button>
          </div>
        )}
      </div>

      {/* Modals */}
      {showClientList && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[80] flex items-end justify-center">
          <div className="bg-white w-full max-w-lg rounded-t-[2.5rem] p-6 animate-slide-up max-h-[80vh] overflow-y-auto">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold text-slate-900">Grahak Chunein</h3>
              <button onClick={() => setShowClientList(false)} className="p-2 bg-slate-100 rounded-full"><X className="w-5 h-5" /></button>
            </div>
            <div className="space-y-2">
              {clients.map(c => (
                <button key={c.id} onClick={() => { setCustName(c.name); setCustMobile(c.mobile || ''); setSelectedClientId(c.id); setShowClientList(false); }} className="w-full p-4 bg-slate-50 rounded-2xl text-left hover:bg-blue-50 border border-transparent hover:border-blue-100 flex justify-between items-center group">
                  <div><p className="font-bold text-slate-900 group-hover:text-blue-700">{c.name}</p><p className="text-xs text-slate-400 font-bold">{c.mobile || 'No mobile'}</p></div>
                  {c.totalBorrowed > 0 && <span className="text-[10px] bg-red-100 text-red-600 px-2 py-1 rounded-full font-bold">Udhaar: ₹{c.totalBorrowed}</span>}
                </button>
              ))}
              {clients.length === 0 && <p className="text-center text-slate-400 py-10 italic">Koi grahak nahi hai</p>}
            </div>
          </div>
        </div>
      )}

      {showQuickAdd && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[80] flex items-end justify-center">
          <div className="bg-white w-full max-w-lg rounded-t-[2.5rem] p-6 animate-slide-up shadow-2xl">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold text-slate-900">Turant Jodein (Quick Add)</h3>
              <button onClick={() => setShowQuickAdd(false)} className="p-2 bg-slate-100 rounded-full text-slate-500"><X className="w-5 h-5" /></button>
            </div>
            <div className="space-y-4">
              <input type="text" autoFocus placeholder="Product Naam" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl text-slate-900 font-bold outline-none" value={quickAddForm.name} onChange={e => setQuickAddForm({...quickAddForm, name: e.target.value})} />
              <div className="grid grid-cols-2 gap-4">
                <input type="number" placeholder="Price (₹)" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl text-slate-900 font-bold outline-none" value={quickAddForm.price} onChange={e => setQuickAddForm({...quickAddForm, price: e.target.value})} />
                <input type="number" placeholder="Quantity" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl text-slate-900 font-bold outline-none" value={quickAddForm.quantity} onChange={e => setQuickAddForm({...quickAddForm, quantity: e.target.value})} />
              </div>
              <button onClick={() => { if(quickAddForm.name && quickAddForm.price) { addToCart({name: quickAddForm.name, price: Number(quickAddForm.price), quantity: Number(quickAddForm.quantity)}); setQuickAddForm({name:'', price:'', quantity:'1'}); setShowQuickAdd(false); } }} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold">Cart Mein Daalein</button>
            </div>
          </div>
        </div>
      )}

      {showCheckout && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[90] flex items-end justify-center">
          <div className="bg-white w-full max-w-lg rounded-t-[2.5rem] p-6 animate-slide-up shadow-2xl">
            <div className="flex justify-between items-center mb-8"><h3 className="text-xl font-bold text-slate-900">Payment Chuney</h3><button onClick={() => setShowCheckout(false)} className="p-2 bg-slate-100 rounded-full"><X className="w-5 h-5" /></button></div>
            <div className="grid grid-cols-1 gap-4 mb-8">
              <button onClick={() => setPaymentMethod(PaymentMethod.CASH)} className={`flex items-center gap-4 p-4 rounded-2xl border-2 transition-all ${paymentMethod === PaymentMethod.CASH ? 'bg-blue-50 border-blue-600' : 'bg-white border-slate-100'}`}><Banknote className="w-6 h-6 text-slate-600" /> <div className="text-left font-bold"><p className="text-slate-900">Cash Payment</p><p className="text-xs text-slate-400">Turant rokda</p></div></button>
              <button onClick={() => setPaymentMethod(PaymentMethod.ONLINE)} className={`flex items-center gap-4 p-4 rounded-2xl border-2 transition-all ${paymentMethod === PaymentMethod.ONLINE ? 'bg-blue-50 border-blue-600' : 'bg-white border-slate-100'}`}><CreditCard className="w-6 h-6 text-slate-600" /> <div className="text-left font-bold"><p className="text-slate-900">Online / UPI</p><p className="text-xs text-slate-400">QR Code dikhayein</p></div></button>
              <button onClick={() => setPaymentMethod(PaymentMethod.BORROW)} className={`flex items-center gap-4 p-4 rounded-2xl border-2 transition-all ${paymentMethod === PaymentMethod.BORROW ? 'bg-blue-50 border-blue-600' : 'bg-white border-slate-100'}`}><Clock className="w-6 h-6 text-slate-600" /> <div className="text-left font-bold"><p className="text-slate-900">Udhaar (Borrow)</p><p className="text-xs text-slate-400">Khaate mein jodein</p></div></button>
            </div>
            <button onClick={handleFinish} className="w-full bg-blue-600 text-white py-4 rounded-2xl font-bold shadow-lg active:scale-95 transition-all">Bill Banayein</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default Billing;

import React, { useState } from 'react';
import { Search, History, Calendar, ChevronRight, X, MessageSquare, Download, Share2 } from 'lucide-react';
import { Invoice, AppConfig } from '../types';
import { formatCurrency } from '../utils/helpers';
import InvoiceDetail from '../components/InvoiceDetail';

interface InvoicesProps {
  invoices: Invoice[];
  config: AppConfig;
}

const Invoices: React.FC<InvoicesProps> = ({ invoices, config }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedInvoice, setSelectedInvoice] = useState<Invoice | null>(null);
  const [dateFilter, setDateFilter] = useState('');

  const filteredInvoices = invoices.filter(inv => {
    const matchesSearch = inv.clientName.toLowerCase().includes(searchTerm.toLowerCase()) || 
                         inv.id.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesDate = !dateFilter || inv.date.startsWith(dateFilter);
    return matchesSearch && matchesDate;
  }).reverse();

  const handleWhatsApp = (inv: Invoice) => {
    if (!inv.clientMobile) {
      alert("Grahak ka mobile number nahi hai!");
      return;
    }
    const message = `Namaste! ${config.shopName} se aapka bill.\nBill No: ${inv.id}\nAmount: ${formatCurrency(inv.grandTotal)}\nDhanyawad!`;
    const url = `https://wa.me/91${inv.clientMobile}?text=${encodeURIComponent(message)}`;
    window.open(url, '_blank');
  };

  const handleSMS = (inv: Invoice) => {
    if (!inv.clientMobile) {
      alert("Grahak ka mobile number nahi hai!");
      return;
    }
    const message = `Namaste! ${config.shopName} se aapka bill. Total: ${formatCurrency(inv.grandTotal)}. Bill No: ${inv.id}. Dhanyawad!`;
    window.location.href = `sms:91${inv.clientMobile}?body=${encodeURIComponent(message)}`;
  };

  return (
    <div className="space-y-6 pb-20">
      {selectedInvoice ? (
        <div className="space-y-4">
           <button onClick={() => setSelectedInvoice(null)} className="flex items-center gap-2 text-slate-900 font-black text-sm mb-4"><ChevronRight className="w-5 h-5 rotate-180" /> Peeche Jayein</button>
           <InvoiceDetail invoice={selectedInvoice} config={config} />
        </div>
      ) : (
        <>
          <div className="bg-white p-5 rounded-3xl shadow-sm border border-slate-100 space-y-3">
            <div className="flex items-center gap-2">
              <Search className="w-5 h-5 text-slate-400" />
              <input type="text" placeholder="Grahak ya Bill ID Khojein..." className="flex-1 bg-transparent border-none outline-none text-slate-900 font-bold" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
            </div>
            <div className="flex items-center gap-2 pt-2 border-t border-slate-50">
               <Calendar className="w-4 h-4 text-blue-600" />
               <input type="date" className="flex-1 bg-slate-50 rounded-lg p-2 text-xs font-black text-slate-900 outline-none" value={dateFilter} onChange={e => setDateFilter(e.target.value)} />
               <button onClick={() => setDateFilter('')} className="p-2 bg-slate-100 rounded-lg text-slate-400"><X className="w-4 h-4" /></button>
            </div>
          </div>

          <div className="space-y-4">
            {filteredInvoices.map(inv => (
              <div key={inv.id} className="bg-white p-5 rounded-3xl shadow-sm border border-slate-100 flex flex-col gap-4 active:scale-[0.98] transition-all">
                <div className="flex justify-between items-start" onClick={() => setSelectedInvoice(inv)}>
                  <div className="flex gap-4">
                    <div className="w-12 h-12 bg-slate-50 rounded-2xl flex items-center justify-center text-slate-400"><History className="w-6 h-6" /></div>
                    <div className="text-left">
                      <h4 className="font-black text-slate-900 leading-none mb-1">{inv.clientName}</h4>
                      <p className="text-[10px] text-slate-400 font-bold">ID: {inv.id} • {new Date(inv.date).toLocaleDateString()}</p>
                    </div>
                  </div>
                  <div className="text-right">
