                  <span className="font-bold text-slate-800">{p.name}</span>
                  <div className="flex items-center gap-2 text-red-700 font-black">
                    <AlertCircle className="w-4 h-4" />
                    <span>{p.stock} Left</span>
                  </div>
                </div>
              ))}

              {modalType === 'CLIENTS' && clients.map(c => (
                <div key={c.id} className="p-5 bg-slate-50 rounded-[2rem] border border-slate-100">
                  <p className="font-black text-slate-900 mb-1">{c.name}</p>
                  <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest">{c.mobile || 'MOBILE NAHI HAI'}</p>
                </div>
              ))}

              {/* Empty States */}
              {modalType === 'BORROWERS' && clients.filter(c => c.totalBorrowed > 0).length === 0 && <EmptyState text="Koi udhaar pending nahi hai!" />}
              {modalType === 'LOW_STOCK' && lowStockItems.length === 0 && <EmptyState text="Stock ekdum sahi hai!" />}
              {modalType === 'CLIENTS' && clients.length === 0 && <EmptyState text="Koi grahak save nahi hai." />}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

