import React, { useState, useMemo } from 'react';
import { 
  Search, 
  Trash2, 
  Plus, 
  Minus, 
  PlusCircle, 
  CheckCircle2,
  X,
  CreditCard,
  Banknote,
  Clock,
  Package,
  Zap,
  Users,
  ChevronRight
} from 'lucide-react';
import { Product, Client, Invoice, InvoiceItem, PaymentMethod, AppConfig } from '../types';
import { generateId, formatCurrency } from '../utils/helpers';
import InvoiceDetail from '../components/InvoiceDetail';

interface BillingProps {
  products: Product[];
  clients: Client[];
  setInvoices: React.Dispatch<React.SetStateAction<Invoice[]>>;
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  setClients: React.Dispatch<React.SetStateAction<Client[]>>;
  config: AppConfig;
}

const Billing: React.FC<BillingProps> = ({ products, clients, setInvoices, setProducts, setClients, config }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [cart, setCart] = useState<InvoiceItem[]>([]);
  const [custName, setCustName] = useState('');
  const [custMobile, setCustMobile] = useState('');
  const [selectedClientId, setSelectedClientId] = useState<string | null>(null);

  const [discount, setDiscount] = useState(0);
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>(PaymentMethod.CASH);
  const [showCheckout, setShowCheckout] = useState(false);
  const [showQuickAdd, setShowQuickAdd] = useState(false);
  const [showClientList, setShowClientList] = useState(false);
  const [generatedInvoice, setGeneratedInvoice] = useState<Invoice | null>(null);

  const [quickAddForm, setQuickAddForm] = useState({ name: '', price: '', quantity: '1' });

  const filteredProducts = useMemo(() => {
    if (!searchTerm) return [];
    return products.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()));
  }, [searchTerm, products]);

  const addToCart = (product: Product | { name: string, price: number, quantity?: number }) => {
    const qtyToAdd = 'quantity' in product ? (product.quantity || 1) : 1;
    setCart(prev => {
      const existing = prev.find(item => item.name === product.name);
      if (existing) {
        return prev.map(item => item.name === product.name ? { 
          ...item, 
          quantity: item.quantity + qtyToAdd, 
          total: (item.quantity + qtyToAdd) * item.price 
        } : item);
      }
      return [...prev, {
        id: ('id' in product ? product.id : generateId()),
        name: product.name,
        quantity: qtyToAdd,
        price: product.price,
        total: product.price * qtyToAdd
      }];
    });
    setSearchTerm('');
  };

  const handleQuickAdd = (e: React.FormEvent) => {
    e.preventDefault();
    if (!quickAddForm.name || !quickAddForm.price) return;

    const name = quickAddForm.name.trim();
    const price = parseFloat(quickAddForm.price);
    const quantity = parseInt(quickAddForm.quantity) || 1;

    // 1. Create product if it doesn't exist in inventory
    const existingInInventory = products.find(p => p.name.toLowerCase() === name.toLowerCase());
    let productToCart: Product;

    if (!existingInInventory) {
      const newProduct: Product = {
        id: generateId(),
        name: name,
        price: price,
        stock: null // Unlimited stock as requested
      };
      setProducts(prev => [...prev, newProduct]);
      productToCart = newProduct;
    } else {
      productToCart = existingInInventory;
    }

    // 2. Add to Cart
    addToCart({ ...productToCart, quantity });

    // 3. Reset and Close
    setQuickAddForm({ name: '', price: '', quantity: '1' });
    setShowQuickAdd(false);
  };

  const handleFinish = () => {
    if (!custName) {
      alert("Kripya Grahak ka naam likhein!");
      return;
    }

    const subtotalVal = cart.reduce((acc, i) => acc + i.total, 0);
    const totalVal = subtotalVal * (1 - discount/100);

    const invoice: Invoice = {
      id: `INV-${Date.now().toString().slice(-6)}`,
      date: new Date().toISOString(),
      clientId: selectedClientId || 'WALK_IN',
      clientName: custName,
      clientMobile: custMobile,
      items: [...cart],
      discount,
      subtotal: subtotalVal,
      grandTotal: totalVal,
      paymentMethod
    };

    setInvoices(prev => [...prev, invoice]);

    setProducts(prev => prev.map(p => {
      const cartItem = cart.find(item => item.name === p.name);
      return (cartItem && p.stock !== null) ? { ...p, stock: p.stock - cartItem.quantity } : p;
    }));

    if (paymentMethod === PaymentMethod.BORROW) {
      setClients(prev => {
        const existingIdx = prev.findIndex(c => c.name === custName || c.id === selectedClientId);
        if (existingIdx > -1) {
          const updated = [...prev];
          updated[existingIdx].totalBorrowed += invoice.grandTotal;
          return updated;
        } else {
          return [...prev, { id: generateId(), name: custName, mobile: custMobile, totalBorrowed: invoice.grandTotal }];
        }
      });
    }

    setGeneratedInvoice(invoice);
    setShowCheckout(false);
    setCart([]);
    setCustName('');
    setCustMobile('');
    setSelectedClientId(null);
  };

  if (generatedInvoice) {
    return (
      <div className="space-y-4">
        <div className="bg-green-50 text-green-700 p-4 rounded-3xl border border-green-100 flex items-center gap-3">
          <CheckCircle2 className="w-6 h-6" />
          <p className="font-bold">Bill generate ho gaya!</p>
        </div>
        <InvoiceDetail invoice={generatedInvoice} config={config} />
        <button onClick={() => setGeneratedInvoice(null)} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold">Naya Bill Banayein</button>
      </div>
    );
  }

  const subtotal = cart.reduce((acc, item) => acc + item.total, 0);
  const grandTotal = subtotal * (1 - discount / 100);

  return (
    <div className="space-y-6 pb-24">
