import React, { useRef, useState, useEffect } from 'react';
import { Eraser, Check, X } from 'lucide-react';

interface SignaturePadProps {
  onSave: (base64: string) => void;
  onCancel: () => void;
}

const SignaturePad: React.FC<SignaturePadProps> = ({ onSave, onCancel }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isDrawing, setIsDrawing] = useState(false);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const resize = () => {
      const rect = canvas.getBoundingClientRect();
      const ratio = window.devicePixelRatio || 1;
      canvas.width = rect.width * ratio;
      canvas.height = rect.height * ratio;
      ctx.scale(ratio, ratio);

      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.strokeStyle = '#0f172a';
      ctx.lineWidth = 3;
    };

    resize();
    window.addEventListener('resize', resize);
    return () => window.removeEventListener('resize', resize);
  }, []);

  const getCoordinates = (e: React.MouseEvent | React.TouchEvent) => {
    const canvas = canvasRef.current;
    if (!canvas) return { x: 0, y: 0 };
    const rect = canvas.getBoundingClientRect();

    let clientX, clientY;
    if ('touches' in e) {
      clientX = e.touches[0].clientX;
      clientY = e.touches[0].clientY;
    } else {
      clientX = (e as React.MouseEvent).clientX;
      clientY = (e as React.MouseEvent).clientY;
    }

    return {
      x: clientX - rect.left,
      y: clientY - rect.top
    };
  };

  const startDrawing = (e: React.MouseEvent | React.TouchEvent) => {
    setIsDrawing(true);
    const { x, y } = getCoordinates(e);
    const ctx = canvasRef.current?.getContext('2d');
    if (ctx) {
      ctx.beginPath();
      ctx.moveTo(x, y);
    }
    if ('touches' in e) {
      if (e.cancelable) e.preventDefault();
    }
  };

  const draw = (e: React.MouseEvent | React.TouchEvent) => {
    if (!isDrawing) return;
    const { x, y } = getCoordinates(e);
    const ctx = canvasRef.current?.getContext('2d');
    if (ctx) {
      ctx.lineTo(x, y);
      ctx.stroke();
    }
    if ('touches' in e) {
      if (e.cancelable) e.preventDefault();
    }
  };

  const stopDrawing = () => {
    setIsDrawing(false);
  };

  const clear = () => {
    const canvas = canvasRef.current;
    if (canvas) {
      const ctx = canvas.getContext('2d');
      if (ctx) {
        // Clear based on the actual visible dimensions
        const rect = canvas.getBoundingClientRect();
        ctx.clearRect(0, 0, rect.width, rect.height);
      }
    }
  };

  const save = () => {
    const canvas = canvasRef.current;
    if (canvas) {
      const dataUrl = canvas.toDataURL('image/png');
      onSave(dataUrl);
    }
  };

  return (
    <div className="fixed inset-0 bg-slate-900/95 z-[100] flex flex-col p-4 md:p-8">
      <div className="flex justify-between items-center mb-6 text-white px-2">
        <h3 className="text-xl font-black uppercase tracking-tight">Signature Pad</h3>
        <button onClick={onCancel} className="p-3 bg-white/10 rounded-full active:scale-90 transition-transform"><X className="w-6 h-6" /></button>
      </div>

      <div className="flex-1 bg-white rounded-[2.5rem] overflow-hidden relative shadow-2xl border-4 border-blue-500">
        <canvas
          ref={canvasRef}
          className="w-full h-full touch-none cursor-crosshair"
          onMouseDown={startDrawing}
          onMouseMove={draw}
          onMouseUp={stopDrawing}
          onMouseLeave={stopDrawing}
          onTouchStart={startDrawing}
          onTouchMove={draw}
          onTouchEnd={stopDrawing}
        />
        <div className="absolute bottom-6 left-6 right-6 flex gap-4">
          <button 
            onClick={clear}
            className="flex-1 bg-slate-100 text-slate-600 py-4 rounded-2xl font-black uppercase text-xs tracking-widest flex items-center justify-center gap-2 active:scale-95 transition-all"
          >
            <Eraser className="w-5 h-5" /> Saaf Karein
          </button>
          <button 
            onClick={save}
            className="flex-1 bg-blue-600 text-white py-4 rounded-2xl font-black uppercase text-xs tracking-widest flex items-center justify-center gap-2 shadow-lg shadow-blue-500/30 active:scale-95 transition-all"
          >
            <Check className="w-5 h-5" /> Done
          </button>
        </div>
      </div>
      <p className="text-center text-blue-200 text-xs mt-6 font-bold uppercase tracking-widest animate-pulse">Uper box mein signature karein</p>
    </div>
  );
};

export default SignaturePad;

import React, { useRef } from 'react';
import { Printer, Download, Share2 } from 'lucide-react';
import { Invoice, AppConfig, PaymentMethod } from '../types';
import { formatCurrency, numberToWords } from '../utils/helpers';

interface InvoiceDetailProps {
  invoice: Invoice;
  config: AppConfig;
}

const InvoiceDetail: React.FC<InvoiceDetailProps> = ({ invoice, config }) => {
  const invoiceRef = useRef<HTMLDivElement>(null);

  const handlePrint = () => {
    window.print();
  };

  const handleDownload = async () => {
    if (!invoiceRef.current) return;
    const { jsPDF } = (window as any).jspdf;

    const element = invoiceRef.current;

    try {
      const canvas = await (window as any).html2canvas(element, {
        scale: 3, // Increased scale for even better text clarity in PDF
        useCORS: true,
        backgroundColor: '#ffffff',
        logging: false,
      });
      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF('p', 'mm', 'a4');
      const imgProps = pdf.getImageProperties(imgData);
      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = (imgProps.height * pdfWidth) / imgProps.width;

      pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
      const fileName = `Bill_${invoice.id}_${invoice.clientName.replace(/[^a-z0-9]/gi, '_').toLowerCase()}.pdf`;
      pdf.save(fileName);
    } catch (err) {
      console.error("PDF Export failed", err);
      alert("Failed to generate PDF. Please try printing instead.");
    }
  };

  const handleShare = async () => {
    if (!invoice.clientMobile) {
      alert("Grahak ka mobile number nahi hai!");
      return;
    }
    const message = `Namaste! ${config.shopName} se aapka bill.\nBill No: ${invoice.id}\nAmount: ${formatCurrency(invoice.grandTotal)}\nDhanyawad!`;
    const url = `https://wa.me/91${invoice.clientMobile}?text=${encodeURIComponent(message)}`;
