             )}
             <div className="border-t border-slate-200 pt-2">
                <p className="text-xs font-black text-slate-900 uppercase tracking-tighter">{config.ownerName}</p>
                <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Authorized Signatory</p>
             </div>
          </div>
        </div>

        <div className="mt-12 text-center border-t border-slate-50 pt-6">
           <p className="text-[10px] text-slate-500 font-bold uppercase tracking-[0.2em]">Thank you for your visit!</p>
           <p className="text-[8px] text-slate-300 mt-2 font-black uppercase tracking-widest">System Generated Invoice by Patwa ji App</p>
        </div>
