import React, { useRef } from 'react';
import { Printer, Download, Share2 } from 'lucide-react';
import { Invoice, AppConfig, PaymentMethod, InvoiceTheme } from '../types';
import { formatCurrency, numberToWords } from '../utils/helpers';

interface InvoiceDetailProps {
  invoice: Invoice;
  config: AppConfig;
}

const InvoiceDetail: React.FC<InvoiceDetailProps> = ({ invoice, config }) => {
  const invoiceRef = useRef<HTMLDivElement>(null);
  const currentTheme = config.invoiceTheme || InvoiceTheme.MODERN;

  const handlePrint = () => {
    window.print();
  };

  const handleDownload = async () => {
    if (!invoiceRef.current) return;
    const { jsPDF } = (window as any).jspdf;

    const element = invoiceRef.current;

    try {
      const canvas = await (window as any).html2canvas(element, {
        scale: 3,
        useCORS: true,
        backgroundColor: '#ffffff',
        logging: false,
      });
      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF('p', 'mm', 'a4');
      const imgProps = pdf.getImageProperties(imgData);
      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = (imgProps.height * pdfWidth) / imgProps.width;

      pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
      const fileName = `Bill_${invoice.id}_${invoice.clientName.replace(/[^a-z0-9]/gi, '_').toLowerCase()}.pdf`;
      pdf.save(fileName);
    } catch (err) {
      console.error("PDF Export failed", err);
      alert("Failed to generate PDF. Please try printing instead.");
    }
  };

  const handleShare = async () => {
    if (!invoice.clientMobile) {
      alert("Grahak ka mobile number nahi hai!");
      return;
    }
    const message = `Namaste! ${config.shopName} se aapka bill.\nBill No: ${invoice.id}\nAmount: ${formatCurrency(invoice.grandTotal)}\nDhanyawad!`;
    const url = `https://wa.me/91${invoice.clientMobile}?text=${encodeURIComponent(message)}`;
    window.open(url, '_blank');
  };

  // Theme Styles
  const themeStyles = {
    [InvoiceTheme.MODERN]: {
      bg: 'bg-white',
      header: 'text-center border-b-2 border-slate-100 pb-6 mb-6',
      title: 'text-3xl font-black text-slate-900 uppercase tracking-tighter',
      accent: 'text-blue-600',
      box: 'bg-slate-50 p-4 rounded-2xl border border-slate-100',
      tableHeader: 'border-b-2 border-slate-900',
      totalBox: 'bg-slate-900 p-4 rounded-2xl text-white shadow-lg',
    },
    [InvoiceTheme.CLASSIC]: {
      bg: 'bg-white',
      header: 'text-left border-b-4 border-black pb-4 mb-6',
      title: 'text-3xl font-serif font-black text-black uppercase',
      accent: 'text-black underline',
      box: 'border-2 border-black p-4 mb-4',
      tableHeader: 'border-y-2 border-black bg-slate-50',
      totalBox: 'border-2 border-black p-4 text-black font-black',
    },
    [InvoiceTheme.ELEGANT]: {
      bg: 'bg-white',
      header: 'text-center pb-8 mb-8 relative',
      title: 'text-4xl font-serif text-indigo-900 tracking-wide font-light italic',
      accent: 'text-amber-600 font-serif',
      box: 'bg-indigo-50/30 p-6 border-l-4 border-indigo-600',
      tableHeader: 'bg-indigo-900 text-white rounded-t-xl',
      totalBox: 'bg-indigo-900 p-5 rounded-xl text-white shadow-xl shadow-indigo-100',
    },
    [InvoiceTheme.MINIMAL]: {
      bg: 'bg-white',
      header: 'text-left mb-10',
      title: 'text-2xl font-medium text-slate-800 tracking-tight',
      accent: 'text-slate-500',
      box: 'border-b border-slate-100 pb-6 mb-6',
      tableHeader: 'border-b border-slate-200',
      totalBox: 'pt-4 border-t-2 border-slate-100 text-slate-900 font-bold',
    }
  };

  const style = themeStyles[currentTheme];

  return (
    <div className="space-y-4">
      <div className="bg-white p-2 rounded-2xl flex justify-around no-print shadow-sm border border-slate-100">
        <button onClick={handlePrint} className="flex flex-col items-center gap-1 text-blue-600 font-bold text-[10px] p-2 active:scale-95 transition-all">
          <Printer className="w-5 h-5" /> Print
        </button>
        <button onClick={handleDownload} className="flex flex-col items-center gap-1 text-blue-600 font-bold text-[10px] p-2 active:scale-95 transition-all">
          <Download className="w-5 h-5" /> PDF
        </button>
        <button onClick={handleShare} className="flex flex-col items-center gap-1 text-green-600 font-bold text-[10px] p-2 active:scale-95 transition-all">
          <Share2 className="w-5 h-5" /> WhatsApp
        </button>
      </div>

      <div 
        ref={invoiceRef}
        className={`${style.bg} p-8 rounded-[2rem] shadow-sm border border-slate-100 print:shadow-none print:border-none print:p-0 print:m-0`}
      >
        {/* Invoice Header */}
        <div className={style.header}>
          <h1 className={style.title}>{config.shopName}</h1>
          <p className="text-sm font-bold text-slate-500 mt-1">{config.ownerName}</p>
          <p className={`text-xs font-bold ${style.accent}`}>Mobile: +91 {config.shopMobile}</p>

          <div className={`mt-8 flex justify-between items-start text-left ${style.box}`}>
            <div className="flex-1">
              <p className="text-[10px] uppercase font-black text-slate-400 tracking-widest mb-1">Grahak (Customer)</p>
              <p className="text-base font-black text-slate-900 leading-tight">{invoice.clientName}</p>
              {invoice.clientMobile ? (
                <p className="text-xs font-bold text-slate-600 mt-1 flex items-center gap-1">
                  Mob: <span className="text-slate-900 font-black">{invoice.clientMobile}</span>
                </p>
              ) : (
                <p className="text-[10px] font-bold text-slate-300 mt-1 italic">Mobile not provided</p>
              )}
            </div>
            <div className="text-right">
              <p className="text-[10px] uppercase font-black text-slate-400 tracking-widest mb-1">Bill Details</p>
