import SignaturePad from '../components/SignaturePad';

interface SettingsProps {
  config: AppConfig;
  setConfig: React.Dispatch<React.SetStateAction<AppConfig | null>>;
}

const Settings: React.FC<SettingsProps> = ({ config, setConfig }) => {
  const [showSignPad, setShowSignPad] = useState(false);
  const [swipeX, setSwipeX] = useState(0);
  const sliderRef = useRef<HTMLDivElement>(null);

  const handleUpdate = (updates: Partial<AppConfig>) => {
    const newConfig = { ...config, ...updates };
    setConfig(newConfig);
    localStorage.setItem('app_config', JSON.stringify(newConfig));
  };

  const handleImageChange = async (e: React.ChangeEvent<HTMLInputElement>, type: 'qr') => {
     if (e.target.files && e.target.files[0]) {
       const base64 = await fileToBase64(e.target.files[0]);
       handleUpdate({ qrCodeImage: base64 });
     }
  };

  const themes = [
    { id: InvoiceTheme.MODERN, name: 'Modern', desc: 'Blue & Bold', color: 'bg-blue-600' },
    { id: InvoiceTheme.CLASSIC, name: 'Classic', desc: 'Traditional B&W', color: 'bg-slate-900' },
    { id: InvoiceTheme.ELEGANT, name: 'Elegant', desc: 'Indigo & Gold', color: 'bg-indigo-700' },
    { id: InvoiceTheme.MINIMAL, name: 'Minimal', desc: 'Clean & Simple', color: 'bg-slate-400' },
  ];

  // Swipe to Pro Logic
  const handleSwipeStart = (e: React.TouchEvent | React.MouseEvent) => {
    const startX = 'touches' in e ? e.touches[0].clientX : (e as React.MouseEvent).clientX;
    const moveListener = (moveEvent: TouchEvent | MouseEvent) => {
      const currentX = 'touches' in moveEvent ? moveEvent.touches[0].clientX : (moveEvent as MouseEvent).clientX;
      const diff = Math.max(0, Math.min(currentX - startX, 240)); // limit swipe
      setSwipeX(diff);

      if (diff >= 230) { // Threshold met
        handleUpdate({ isProMode: !config.isProMode });
        setSwipeX(0);
        document.removeEventListener('mousemove', moveListener);
        document.removeEventListener('touchmove', moveListener);
      }
    };
    const endListener = () => {
      setSwipeX(0);
      document.removeEventListener('mousemove', moveListener);
      document.removeEventListener('touchmove', moveListener);
    };
    document.addEventListener('mousemove', moveListener);
    document.addEventListener('mouseup', endListener);
    document.addEventListener('touchmove', moveListener, { passive: false });
    document.addEventListener('touchend', endListener);
  };

  return (
    <div className="space-y-6 pb-24 animate-in fade-in duration-500">
      {/* Profile Summary */}
      <div className={`p-8 rounded-[2.5rem] text-white shadow-xl relative overflow-hidden transition-all duration-500 ${
        config.isProMode 
          ? 'bg-gradient-to-br from-pro-600 to-pro-900 shadow-pro-600/30' 
          : 'bg-gradient-to-br from-blue-600 to-indigo-800 shadow-blue-100 dark:shadow-none'
      }`}>
        <div className="flex flex-col items-center text-center">
          <div className="w-20 h-20 bg-white/20 rounded-[1.5rem] flex items-center justify-center mb-4 backdrop-blur-md shadow-2xl">
            <Store className="w-10 h-10" />
          </div>
          <h2 className="text-2xl font-black tracking-tight">{config.shopName}</h2>
          <p className="text-white/70 text-[10px] font-black uppercase tracking-widest mt-1">{config.ownerName} • +91 {config.shopMobile}</p>
          {config.isProMode && (
            <div className="mt-4 bg-yellow-400 text-slate-900 text-[10px] font-black px-4 py-1.5 rounded-full flex items-center gap-2 animate-bounce">
              <Zap className="w-3.5 h-3.5 fill-current" /> PRO BUSINESS ACTIVE
            </div>
          )}
        </div>
        <div className="absolute top-0 right-0 p-8 opacity-5">
          <Building2 className="w-24 h-24" />
        </div>
      </div>

      {/* Swipe to Pro Mode */}
      <div className="bg-white dark:bg-slate-900 rounded-[2rem] p-6 shadow-sm border border-slate-100 dark:border-slate-800">
        <div className="flex items-center gap-4 mb-4">
          <div className={`p-2 rounded-xl ${config.isProMode ? 'bg-pro-50 text-pro-600' : 'bg-slate-100 text-slate-500'}`}>
            <Zap className="w-5 h-5" />
          </div>
          <div>
            <h4 className="font-black text-slate-900 dark:text-white text-sm">Business Mode</h4>
            <p className="text-[10px] text-slate-400 font-bold uppercase">Swipe karein {config.isProMode ? 'Lite' : 'Pro'} mode ke liye</p>
          </div>
        </div>

        <div className="swipe-track relative cursor-pointer select-none" ref={sliderRef} onMouseDown={handleSwipeStart} onTouchStart={handleSwipeStart}>
          <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
            <span className="text-[10px] font-black text-slate-400 dark:text-slate-600 uppercase tracking-[0.3em]">
              {config.isProMode ? 'SWIPE LEFT TO LITE' : 'SWIPE RIGHT TO PRO'}
            </span>
          </div>
          <div 
            className={`swipe-thumb absolute left-1 flex items-center justify-center transition-shadow shadow-lg ${config.isProMode ? 'bg-pro-600 text-white' : 'bg-white text-blue-600'}`}
            style={{ transform: `translateX(${swipeX}px)` }}
          >
            {config.isProMode ? <Zap className="w-6 h-6" /> : <ChevronRight className="w-6 h-6" />}
          </div>
        </div>
      </div>

      {/* Mode Controls */}
      <div className="bg-white dark:bg-slate-900 rounded-[2rem] p-6 shadow-sm border border-slate-100 dark:border-slate-800 flex justify-between items-center">
        <div className="flex items-center gap-4">
          <div className={`p-3 rounded-2xl ${config.isDarkMode ? 'bg-slate-800 text-yellow-400' : 'bg-slate-100 text-slate-600'}`}>
            {config.isDarkMode ? <Moon className="w-6 h-6" /> : <Sun className="w-6 h-6" />}
          </div>
          <div>
            <h4 className="font-black text-slate-900 dark:text-white text-sm">Theme Mode</h4>
            <p className="text-[10px] text-slate-400 font-bold uppercase">{config.isDarkMode ? 'Dark' : 'Light'} Mode Active</p>
          </div>
        </div>
        <button 
          onClick={() => handleUpdate({ isDarkMode: !config.isDarkMode })}
          className={`w-14 h-8 rounded-full relative transition-all ${config.isDarkMode ? 'bg-pro-600' : 'bg-slate-200'}`}
        >
          <div className={`absolute top-1 w-6 h-6 bg-white rounded-full shadow-md transition-all ${config.isDarkMode ? 'right-1' : 'left-1'}`} />
        </button>
      </div>

      {/* Pro Business Settings */}
      {config.isProMode && (
        <div className="bg-white dark:bg-slate-900 rounded-[2rem] p-6 shadow-sm border border-slate-100 dark:border-slate-800 space-y-4">
          <div className="flex items-center gap-4 mb-2">
            <div className="p-3 bg-pro-50 dark:bg-pro-900/20 text-pro-600 rounded-2xl"><Building2 className="w-6 h-6" /></div>
