                value={config.gstNumber || ''}
                onChange={e => handleUpdate({ gstNumber: e.target.value.toUpperCase() })}
              />
            </div>
            <div>
              <label className="text-[10px] font-black text-slate-400 uppercase ml-1">State Code</label>
              <input 
                type="text"
                placeholder="e.g. 27 for Maharashtra"
                className="w-full p-4 mt-1 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl text-slate-900 dark:text-white font-black"
                value={config.stateCode || ''}
                onChange={e => handleUpdate({ stateCode: e.target.value })}
              />
            </div>
          </div>
        </div>
