      {/* Media & Sign */}
      <div className="bg-white dark:bg-slate-900 rounded-[2rem] p-6 shadow-sm border border-slate-100 dark:border-slate-800 space-y-6">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              <div className="p-3 bg-blue-50 dark:bg-blue-900/20 text-blue-600 rounded-2xl"><PenTool className="w-6 h-6" /></div>
              <h4 className="font-bold text-slate-900 dark:text-white text-sm">Digital Signature</h4>
            </div>
            <button onClick={() => setShowSignPad(true)} className="text-[10px] font-black bg-blue-50 dark:bg-blue-900/40 text-blue-600 px-4 py-2 rounded-full uppercase">Update</button>
          </div>
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              <div className="p-3 bg-orange-50 dark:bg-orange-900/20 text-orange-600 rounded-2xl"><Camera className="w-6 h-6" /></div>
              <h4 className="font-bold text-slate-900 dark:text-white text-sm">Payment QR Code</h4>
            </div>
            <label className="text-[10px] font-black bg-orange-50 dark:bg-orange-900/40 text-orange-600 px-4 py-2 rounded-full uppercase cursor-pointer">
              Upload <input type="file" className="hidden" accept="image/*" onChange={e => handleImageChange(e, 'qr')} />
            </label>
          </div>
      </div>

      {/* Security */}
      <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] p-6 shadow-sm border border-slate-100 dark:border-slate-800 space-y-5">
          <SettingItem 
            icon={<Lock className="w-6 h-6 text-slate-600" />} 
            bg="bg-slate-100 dark:bg-slate-800"
            label="Change App PIN"
            onClick={() => {
              const p = prompt("Naya 4-digit PIN likhein:");
              if (p && p.length === 4) {
                handleUpdate({ pin: p });
                alert("PIN badal diya gaya!");
              }
            }}
          />
          <button 
            onClick={() => { if(confirm("Kya aap pura data delete karna chahte hain?")) { localStorage.clear(); window.location.reload(); } }}
            className="w-full flex items-center justify-center gap-3 p-5 text-red-600 font-black text-sm bg-red-50 dark:bg-red-900/20 rounded-2xl active:bg-red-100 transition-colors"
          >
            <Trash2 className="w-5 h-5" /> Reset App Data
          </button>
      </div>

      <p className="text-center text-slate-300 dark:text-slate-700 text-[10px] font-black py-8 uppercase tracking-[0.3em]">Patwa ji v1.5 PRO Edition</p>

      {showSignPad && (
        <SignaturePad 
          onSave={(base64) => { handleUpdate({ signatureImage: base64 }); setShowSignPad(false); }}
          onCancel={() => setShowSignPad(false)}
        />
      )}
    </div>
  );
};

const SettingItem: React.FC<{ icon: React.ReactNode, bg: string, label: string, onClick: () => void }> = ({ icon, bg, label, onClick }) => (
  <button 
    onClick={onClick}
    className="w-full flex items-center justify-between group"
  >
    <div className="flex items-center gap-5">
      <div className={`p-3 ${bg} rounded-xl`}>{icon}</div>
      <p className="font-bold text-slate-900 dark:text-white text-sm">{label}</p>
    </div>
    <ChevronRight className="w-5 h-5 text-slate-300" />
  </button>
);

export default Settings;

import React, { useState } from 'react';
import { 
  Users, 
  Wallet, 
  TrendingUp, 
  ArrowUpRight, 
  Package, 
  ChevronRight,
  X,
  AlertCircle,
  QrCode,
  Share2,
  Camera,
  PieChart,
  Zap,
  BarChart4,
  IndianRupee,
  FileText
} from 'lucide-react';
import { Invoice, Client, Product, AppConfig, Tab } from '../types';
import { formatCurrency, fileToBase64 } from '../utils/helpers';

interface DashboardProps {
  invoices: Invoice[];
  clients: Client[];
  products: Product[];
  config: AppConfig;
  onNavigate: (tab: Tab) => void;
  setConfig?: (config: AppConfig) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ invoices, clients, products, config, onNavigate, setConfig }) => {
  const [modalType, setModalType] = useState<'BORROWERS' | 'LOW_STOCK' | 'CLIENTS' | 'QR_MODAL' | null>(null);

  const totalSales = invoices.reduce((acc, inv) => acc + inv.grandTotal, 0);
  const totalTax = invoices.reduce((acc, inv) => acc + (inv.taxTotal || 0), 0);
  const totalBorrowAmount = clients.reduce((acc, client) => acc + client.totalBorrowed, 0);
  const lowStockItems = products.filter(p => p.stock !== null && p.stock <= config.lowStockThreshold);

  // Pro Mode Calculations
  const today = new Date().toISOString().split('T')[0];
  const dailyTurnover = invoices
    .filter(inv => inv.date.startsWith(today))
    .reduce((acc, inv) => acc + inv.grandTotal, 0);

  const currentMonth = new Date().getMonth();
  const monthlyTurnover = invoices
    .filter(inv => new Date(inv.date).getMonth() === currentMonth)
    .reduce((acc, inv) => acc + inv.grandTotal, 0);

  const inventoryValue = products.reduce((acc, p) => acc + (p.price * (p.stock || 0)), 0);

  const handleQRUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0] && setConfig) {
      const base64 = await fileToBase64(e.target.files[0]);
      const newConfig = { ...config, qrCodeImage: base64 };
      setConfig(newConfig);
      localStorage.setItem('app_config', JSON.stringify(newConfig));
    }
  };

  return (
    <div className="space-y-6 pb-12">
      {/* Header Stat */}
      <div className={`p-8 rounded-[2.5rem] text-white shadow-xl relative overflow-hidden transition-all duration-700 ${
        config.isProMode 
          ? 'bg-gradient-to-br from-pro-600 via-pro-700 to-pro-900 shadow-pro-600/30' 
          : 'bg-gradient-to-br from-blue-600 to-indigo-800 shadow-blue-600/20'
      }`}>
        <div className="relative z-10">
          <p className="text-white/70 text-[10px] font-black uppercase tracking-[0.2em] mb-2 flex items-center gap-2">
            {config.isProMode ? <Zap className="w-3 h-3 fill-current text-yellow-400" /> : <TrendingUp className="w-3 h-3" />}
            {config.isProMode ? 'Pro Business Turnover' : 'Total Revenue'}
          </p>
          <h3 className="text-4xl font-black tracking-tight mb-4">
            {formatCurrency(config.isProMode ? monthlyTurnover : totalSales)}
          </h3>
          <div className="flex gap-2">
            <span className="bg-white/10 backdrop-blur-md px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest flex items-center gap-2 border border-white/5">
              <ArrowUpRight className="w-3 h-3" /> Growth +14%
            </span>
            {config.isProMode && (
              <span className="bg-yellow-400/20 backdrop-blur-md px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest flex items-center gap-2 text-yellow-400 border border-yellow-400/20">
                Today: {formatCurrency(dailyTurnover)}
              </span>
            )}
          </div>
        </div>
        <div className="absolute -right-12 -bottom-12 w-48 h-48 bg-white/5 rounded-full blur-3xl" />
      </div>

      {/* Advanced Pro Analytics */}
      {config.isProMode && (
        <div className="grid grid-cols-2 gap-4 animate-in slide-in-from-bottom duration-500">
          <div className="bg-white dark:bg-slate-900 p-5 rounded-[2rem] border border-slate-100 dark:border-slate-800 shadow-sm">
             <div className="flex items-center gap-3 mb-2">
                <div className="p-2 bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 rounded-xl"><PieChart className="w-4 h-4" /></div>
                <p className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase">Stock Value</p>
             </div>
             <p className="text-lg font-black text-slate-900 dark:text-white">{formatCurrency(inventoryValue)}</p>
          </div>
          <div className="bg-white dark:bg-slate-900 p-5 rounded-[2rem] border border-slate-100 dark:border-slate-800 shadow-sm">
             <div className="flex items-center gap-3 mb-2">
                <div className="p-2 bg-amber-50 dark:bg-amber-900/20 text-amber-600 rounded-xl"><FileText className="w-4 h-4" /></div>
                <p className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase">Tax Owed</p>
             </div>
             <p className="text-lg font-black text-slate-900 dark:text-white">{formatCurrency(totalTax)}</p>
          </div>
        </div>
      )}

      {/* Quick Stats */}
      <div className="grid grid-cols-2 gap-4">
        <StatCard 
          icon={<Users className="w-5 h-5 text-purple-600" />} 
          bg="bg-purple-50 dark:bg-purple-900/20" 
          label="Total Clients" 
          value={clients.length.toString()} 
          onClick={() => setModalType('CLIENTS')}
          isDark={config.isDarkMode}
        />
        <StatCard 
          icon={<Wallet className="w-5 h-5 text-orange-600" />} 
          bg="bg-orange-50 dark:bg-orange-900/20" 
          label="Total Credit" 
          value={formatCurrency(totalBorrowAmount)} 
          onClick={() => setModalType('BORROWERS')}
          isDark={config.isDarkMode}
        />
      </div>

      {/* Action Area */}
      <div className="grid grid-cols-2 gap-3">
        <ActionButton 
          icon={<AlertCircle className="w-5 h-5" />} 
          label="Low Stock" 
          count={lowStockItems.length}
          color="text-red-600"
          bg="bg-red-50 dark:bg-red-900/20"
          onClick={() => setModalType('LOW_STOCK')}
          isDark={config.isDarkMode}
        />
        <ActionButton 
          icon={<QrCode className="w-5 h-5" />} 
          label="Shop QR" 
          color="text-blue-600"
          bg="bg-blue-50 dark:bg-blue-900/20"
          onClick={() => setModalType('QR_MODAL')}
          isDark={config.isDarkMode}
        />
      </div>

      {/* Latest Invoices */}
      <div className="bg-white dark:bg-slate-900 rounded-[2rem] p-6 shadow-sm border border-slate-100 dark:border-slate-800">
        <div className="flex justify-between items-center mb-6">
          <h4 className="font-black text-slate-900 dark:text-white text-sm tracking-tight uppercase">Latest Transactions</h4>
          <button onClick={() => onNavigate(Tab.INVOICES)} className="text-[10px] font-black text-pro-600 uppercase tracking-widest bg-pro-50 dark:bg-pro-900/20 px-3 py-1 rounded-full">See All</button>
        </div>
        <div className="space-y-4">
          {invoices.slice(-5).reverse().map(inv => (
            <div key={inv.id} className="flex justify-between items-center group cursor-pointer" onClick={() => onNavigate(Tab.INVOICES)}>
              <div className="flex gap-4 items-center">
                <div className="w-10 h-10 bg-slate-50 dark:bg-slate-800 rounded-xl flex items-center justify-center text-slate-400 group-hover:text-pro-600 transition-colors"><FileText className="w-5 h-5" /></div>
                <div>
                  <p className="font-bold text-xs text-slate-800 dark:text-slate-200">{inv.clientName}</p>
                  <p className="text-[8px] text-slate-400 font-bold uppercase">{new Date(inv.date).toLocaleDateString()}</p>
                </div>
              </div>
              <p className="font-black text-xs text-pro-600">{formatCurrency(inv.grandTotal)}</p>
            </div>
          ))}
          {invoices.length === 0 && <p className="text-center text-slate-300 py-6 text-xs font-bold uppercase tracking-widest">No activity found</p>}
        </div>
      </div>

      {/* Modals */}
      {modalType && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-md z-[100] flex items-end justify-center">
          <div className="bg-white dark:bg-slate-950 w-full max-w-lg rounded-t-[3rem] p-8 animate-slide-up shadow-2xl">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-black text-slate-900 dark:text-white uppercase tracking-tight">{modalType.replace('_', ' ')}</h3>
              <button onClick={() => setModalType(null)} className="p-2 bg-slate-100 dark:bg-slate-800 text-slate-500 rounded-full"><X className="w-6 h-6" /></button>
            </div>

            <div className="max-h-[60vh] overflow-y-auto space-y-3 pb-8">
              {modalType === 'QR_MODAL' && (
                <div className="flex flex-col items-center gap-6 py-6">
                  {config.qrCodeImage ? (
                    <div className="w-56 h-56 p-2 bg-white rounded-3xl border-2 border-slate-100 shadow-inner flex items-center justify-center">
                      <img src={config.qrCodeImage} alt="QR" className="w-full h-full object-contain" />
                    </div>
                  ) : (
                    <div className="text-center space-y-4">
                      <QrCode className="w-16 h-16 text-slate-200 mx-auto" />
                      <p className="text-xs text-slate-400 font-bold uppercase">No QR code found in settings</p>
                    </div>
                  )}
                  <label className="bg-pro-600 text-white px-8 py-3 rounded-2xl font-black text-xs uppercase tracking-widest cursor-pointer active:scale-95 transition-all">
                    Update Photo <input type="file" className="hidden" accept="image/*" onChange={handleQRUpload} />
                  </label>
                </div>
              )}
              {modalType === 'BORROWERS' && clients.filter(c => c.totalBorrowed > 0).map(c => (
                <div key={c.id} className="p-4 bg-slate-50 dark:bg-slate-900 rounded-2xl flex justify-between items-center">
                  <div><p className="font-bold text-slate-900 dark:text-white text-sm">{c.name}</p><p className="text-[10px] text-slate-400 font-bold">{c.mobile}</p></div>
                  <p className="font-black text-red-600 text-sm">{formatCurrency(c.totalBorrowed)}</p>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const StatCard: React.FC<{ icon: React.ReactNode, bg: string, label: string, value: string, onClick: () => void, isDark: boolean }> = ({ icon, bg, label, value, onClick, isDark }) => (
  <button onClick={onClick} className="bg-white dark:bg-slate-900 p-5 rounded-[2rem] border border-slate-100 dark:border-slate-800 shadow-sm text-left flex flex-col gap-3 group active:scale-95 transition-all">
    <div className={`w-10 h-10 ${bg} rounded-xl flex items-center justify-center group-hover:scale-110 transition-transform`}>{icon}</div>
    <div>
      <p className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-1">{label}</p>
      <p className="text-lg font-black text-slate-900 dark:text-white leading-none">{value}</p>
    </div>
  </button>
);

const ActionButton: React.FC<{ icon: React.ReactNode, label: string, color: string, bg: string, onClick: () => void, count?: number, isDark: boolean }> = ({ icon, label, color, bg, onClick, count, isDark }) => (
  <button onClick={onClick} className="bg-white dark:bg-slate-900 p-5 rounded-[2rem] border border-slate-100 dark:border-slate-800 shadow-sm flex items-center justify-between group active:scale-95 transition-all">
    <div className="flex items-center gap-3">
      <div className={`p-2.5 ${bg} ${color} rounded-xl`}>{icon}</div>
      <p className="text-xs font-black text-slate-900 dark:text-white uppercase tracking-tight">{label}</p>
    </div>
    {count !== undefined && count > 0 && <span className="bg-red-600 text-white text-[9px] font-black w-5 h-5 rounded-full flex items-center justify-center shadow-lg shadow-red-200">{count}</span>}
  </button>
);

export default Dashboard;

import React, { useState } from 'react';
import { Package, Search, Plus, Edit2, Trash2, Save, X, AlertTriangle, FileText, IndianRupee } from 'lucide-react';
import { Product, AppConfig } from '../types';
import { generateId, formatCurrency } from '../utils/helpers';

interface InventoryProps {
  products: Product[];
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  config: AppConfig;
}

const Inventory: React.FC<InventoryProps> = ({ products, setProducts, config }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [showAdd, setShowAdd] = useState(false);
  const [formData, setFormData] = useState<Partial<Product>>({ name: '', price: 0, stock: null, hsnCode: '', gstRate: 0 });

  const filteredProducts = products.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()));

  const handleSave = () => {
    if (!formData.name || (formData.price || 0) <= 0) {
      alert("Kripya Naam aur Price likhein!");
      return;
    }

    if (editingId) {
      setProducts(prev => prev.map(p => p.id === editingId ? { ...p, ...formData } as Product : p));
      setEditingId(null);
    } else {
      setProducts(prev => [...prev, { ...formData, id: generateId() } as Product]);
      setShowAdd(false);
    }
    setFormData({ name: '', price: 0, stock: null, hsnCode: '', gstRate: 0 });
  };

  const startEdit = (product: Product) => {
    setEditingId(product.id);
    setFormData(product);
  };

  const gstRates = [0, 5, 12, 18, 28];

  return (
    <div className="space-y-6 pb-24">
      {/* Search Bar */}
      <div className="bg-white dark:bg-slate-900 p-4 rounded-3xl shadow-sm border border-slate-100 dark:border-slate-800 flex items-center gap-3">
        <Search className="w-5 h-5 text-slate-400" />
        <input 
          type="text"
          placeholder="Inventory search..."
          className="flex-1 bg-transparent border-none outline-none text-slate-800 dark:text-white font-bold"
          value={searchTerm}
          onChange={e => setSearchTerm(e.target.value)}
        />
        <button 
          onClick={() => setShowAdd(true)}
          className="bg-pro-600 text-white p-2.5 rounded-xl active:scale-95 transition-all shadow-lg shadow-pro-100 dark:shadow-none"
        >
          <Plus className="w-5 h-5" />
        </button>
      </div>

      {/* Add/Edit Form */}
      {(showAdd || editingId) && (
        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] shadow-2xl border border-pro-100 dark:border-pro-900 animate-in zoom-in duration-300">
          <div className="flex justify-between items-center mb-6">
            <h3 className="font-black text-slate-900 dark:text-white tracking-tight uppercase">{editingId ? 'Edit Item' : 'Add New Item'}</h3>
            <button onClick={() => { setShowAdd(false); setEditingId(null); }} className="p-2 bg-slate-100 dark:bg-slate-800 rounded-full"><X className="w-5 h-5" /></button>
          </div>
          <div className="space-y-5">
            <div>
              <label className="text-[10px] font-black text-slate-400 uppercase ml-1">Product Name</label>
              <input 
                type="text"
                className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl p-4 outline-none font-bold text-slate-900 dark:text-white"
                value={formData.name}
                onChange={e => setFormData({...formData, name: e.target.value})}
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase ml-1">Sale Price (₹)</label>
                <input 
                  type="number"
                  className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl p-4 outline-none font-bold text-slate-900 dark:text-white"
                  value={formData.price}
                  onChange={e => setFormData({...formData, price: parseFloat(e.target.value) || 0})}
                />
              </div>
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase ml-1">Stock (Qty)</label>
                <input 
                  type="number"
                  placeholder="∞ Unlimited"
                  className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl p-4 outline-none font-bold text-slate-900 dark:text-white"
                  value={formData.stock === null ? '' : formData.stock}
                  onChange={e => setFormData({...formData, stock: e.target.value === '' ? null : parseInt(e.target.value)})}
                />
              </div>
            </div>

            {config.isProMode && (
              <div className="grid grid-cols-2 gap-4 border-t border-slate-50 dark:border-slate-800 pt-5">
                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase ml-1">HSN Code</label>
                  <input 
                    type="text"
                    className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl p-4 outline-none font-bold text-slate-900 dark:text-white"
                    value={formData.hsnCode || ''}
                    onChange={e => setFormData({...formData, hsnCode: e.target.value})}
                  />
                </div>
                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase ml-1">GST Rate (%)</label>
                  <select 
                    className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl p-4 outline-none font-bold text-slate-900 dark:text-white"
                    value={formData.gstRate}
                    onChange={e => setFormData({...formData, gstRate: parseInt(e.target.value)})}
                  >
                    {gstRates.map(r => <option key={r} value={r}>{r}%</option>)}
                  </select>
                </div>
              </div>
            )}

            <button 
              onClick={handleSave}
              className="w-full bg-pro-600 text-white py-4 rounded-2xl font-black flex items-center justify-center gap-3 shadow-lg shadow-pro-100 dark:shadow-none active:scale-95 transition-all"
            >
              <Save className="w-5 h-5" /> {editingId ? 'Update Stock' : 'Add to Stock'}
            </button>
          </div>
        </div>
      )}

      {/* List */}
      <div className="space-y-3">
        {filteredProducts.map(p => {
          const isLow = p.stock !== null && p.stock <= config.lowStockThreshold;
          return (
            <div key={p.id} className="bg-white dark:bg-slate-900 p-5 rounded-[2rem] border border-slate-100 dark:border-slate-800 flex items-center justify-between shadow-sm group">
              <div className="flex items-center gap-4">
                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center ${isLow ? 'bg-red-50 text-red-600' : 'bg-pro-50 text-pro-600'}`}>
                  {isLow ? <AlertTriangle className="w-6 h-6" /> : <Package className="w-6 h-6" />}
                </div>
                <div>
                  <h4 className="font-black text-slate-900 dark:text-white text-sm tracking-tight">{p.name}</h4>
                  <div className="flex items-center gap-2 mt-0.5">
                    <p className="text-[10px] text-slate-400 font-bold">{formatCurrency(p.price)}</p>
                    <span className="text-[10px] text-slate-300 dark:text-slate-600">•</span>
                    <p className={`text-[10px] font-black uppercase ${isLow ? 'text-red-500' : 'text-slate-500'}`}>
                      Stock: {p.stock === null ? '∞' : p.stock}
                    </p>
                    {config.isProMode && p.gstRate ? (
                      <span className="text-[8px] bg-slate-50 dark:bg-slate-800 text-slate-500 px-1.5 py-0.5 rounded font-black">{p.gstRate}% GST</span>
                    ) : null}
                  </div>
                </div>
              </div>
              <div className="flex gap-1">
                <button onClick={() => startEdit(p)} className="p-3 text-slate-400 dark:text-slate-600 active:text-pro-600 transition-colors">
                  <Edit2 className="w-5 h-5" />
                </button>
                <button onClick={() => { if(confirm("Delete karein?")) setProducts(prev => prev.filter(x => x.id !== p.id)); }} className="p-3 text-slate-400 dark:text-slate-600 active:text-red-600 transition-colors">
                  <Trash2 className="w-5 h-5" />
                </button>
              </div>
            </div>
          );
        })}
        {filteredProducts.length === 0 && (
          <div className="text-center py-20 bg-white dark:bg-slate-900 rounded-[2.5rem] border-2 border-dashed border-slate-100 dark:border-slate-800">
             <Package className="w-16 h-16 text-slate-200 dark:text-slate-800 mx-auto mb-4" />
             <p className="text-slate-400 font-bold uppercase tracking-widest text-[10px]">No items found</p>
          </div>
        )}
      </div>
    </div>
  );
};

