import React, { useState, useRef, useEffect } from 'react';
import { 
  Store, 
  Shield, 
  Trash2, 
  HelpCircle, 
  Info,
  ChevronRight,
  Camera,
  PenTool,
  AlertCircle,
  Plus,
  Minus,
  Palette,
  Check,
  Moon,
  Sun,
  Zap,
  Building2,
  Lock,
  Globe,
  Settings2
} from 'lucide-react';
import { AppConfig, InvoiceTheme } from '../types';
import { fileToBase64 } from '../utils/helpers';
import SignaturePad from '../components/SignaturePad';

interface SettingsProps {
  config: AppConfig;
  setConfig: React.Dispatch<React.SetStateAction<AppConfig | null>>;
}

const Settings: React.FC<SettingsProps> = ({ config, setConfig }) => {
  const [showSignPad, setShowSignPad] = useState(false);
  const [swipeX, setSwipeX] = useState(0);
  const sliderRef = useRef<HTMLDivElement>(null);

  const handleUpdate = (updates: Partial<AppConfig>) => {
    const newConfig = { ...config, ...updates };
    setConfig(newConfig);
    localStorage.setItem('app_config', JSON.stringify(newConfig));
  };

  const handleImageChange = async (e: React.ChangeEvent<HTMLInputElement>, type: 'qr') => {
     if (e.target.files && e.target.files[0]) {
       const base64 = await fileToBase64(e.target.files[0]);
       handleUpdate({ qrCodeImage: base64 });
     }
  };

  const themes = [
    { id: InvoiceTheme.MODERN, name: 'Modern', desc: 'Blue & Bold', color: 'bg-blue-600' },
    { id: InvoiceTheme.CLASSIC, name: 'Classic', desc: 'Tradition B&W', color: 'bg-slate-900' },
    { id: InvoiceTheme.ELEGANT, name: 'Elegant', desc: 'Indigo & Gold', color: 'bg-indigo-700' },
    { id: InvoiceTheme.MINIMAL, name: 'Minimal', desc: 'Clean & Simple', color: 'bg-slate-400' },
  ];

  const handleSwipeStart = (e: React.TouchEvent | React.MouseEvent) => {
    const startX = 'touches' in e ? e.touches[0].clientX : (e as React.MouseEvent).clientX;
    const trackWidth = sliderRef.current?.offsetWidth || 300;
    const thumbWidth = 52;
    const maxSwipe = trackWidth - thumbWidth - 8;

    const moveListener = (moveEvent: TouchEvent | MouseEvent) => {
      const currentX = 'touches' in moveEvent ? moveEvent.touches[0].clientX : (moveEvent as MouseEvent).clientX;
      const diff = Math.max(0, Math.min(currentX - startX, maxSwipe));
      setSwipeX(diff);

      if (diff >= maxSwipe - 5) {
        handleUpdate({ isProMode: !config.isProMode });
        setSwipeX(0);
        cleanup();
      }
    };

    const cleanup = () => {
      setSwipeX(0);
      document.removeEventListener('mousemove', moveListener);
      document.removeEventListener('mouseup', cleanup);
      document.removeEventListener('touchmove', moveListener);
      document.removeEventListener('touchend', cleanup);
    };

    document.addEventListener('mousemove', moveListener);
    document.addEventListener('mouseup', cleanup);
    document.addEventListener('touchmove', moveListener, { passive: false });
    document.addEventListener('touchend', cleanup);
  };

  return (
    <div className="space-y-6 pb-24 animate-in fade-in slide-in-from-bottom-4 duration-500">
      {/* Visual Identity Header */}
      <div className={`p-8 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden transition-all duration-700 ${
        config.isProMode 
          ? 'bg-gradient-to-br from-pro-600 to-pro-900' 
          : 'bg-gradient-to-br from-indigo-600 to-blue-700'
      }`}>
        <div className="relative z-10 flex flex-col items-center text-center">
          <div className="w-24 h-24 bg-white/20 rounded-[2rem] flex items-center justify-center mb-6 backdrop-blur-xl shadow-2xl border border-white/30">
            <Store className="w-12 h-12" />
          </div>
          <h2 className="text-3xl font-black tracking-tight">{config.shopName}</h2>
          <div className="flex items-center gap-2 mt-2 opacity-80">
            <p className="text-[10px] font-black uppercase tracking-widest">{config.ownerName}</p>
            <span className="w-1 h-1 bg-white rounded-full"></span>
            <p className="text-[10px] font-black tracking-widest">+91 {config.shopMobile}</p>
          </div>
          {config.isProMode && (
            <div className="mt-6 inline-flex items-center gap-2 bg-yellow-400 text-slate-950 px-5 py-2 rounded-full font-black text-[10px] uppercase tracking-widest animate-pulse shadow-lg shadow-yellow-400/20">
              <Zap className="w-3 h-3 fill-current" /> Advanced Pro Enterprise
            </div>
          )}
        </div>
        <div className="absolute -top-10 -right-10 w-40 h-40 bg-white/5 rounded-full blur-3xl"></div>
        <div className="absolute -bottom-10 -left-10 w-40 h-40 bg-black/10 rounded-full blur-3xl"></div>
      </div>

      {/* Theme Selection - Dark/Light */}
      <div className="bg-white dark:bg-slate-900 rounded-[2.2rem] p-6 shadow-sm border border-slate-100 dark:border-slate-800">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className={`p-3 rounded-2xl ${config.isDarkMode ? 'bg-indigo-900/40 text-yellow-400' : 'bg-orange-50 text-orange-500'}`}>
              {config.isDarkMode ? <Moon className="w-6 h-6" /> : <Sun className="w-6 h-6" />}
            </div>
            <div>
              <h4 className="font-black text-slate-900 dark:text-white text-sm">App Theme</h4>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tight">Toggle Dark & Light Mode</p>
            </div>
          </div>
          <button 
            onClick={() => handleUpdate({ isDarkMode: !config.isDarkMode })}
            className={`w-16 h-9 rounded-full relative transition-all duration-300 ${config.isDarkMode ? 'bg-indigo-600' : 'bg-slate-200'}`}
          >
            <div className={`absolute top-1 w-7 h-7 bg-white rounded-full shadow-lg transition-all transform ${config.isDarkMode ? 'translate-x-8' : 'translate-x-1'}`}>
              <div className="w-full h-full flex items-center justify-center">
                {config.isDarkMode ? <Moon className="w-3 h-3 text-indigo-600" /> : <Sun className="w-3 h-3 text-orange-500" />}
              </div>
            </div>
          </button>
        </div>
      </div>

      {/* Swipe to Pro Mode Slider */}
      <div className="bg-white dark:bg-slate-900 rounded-[2.2rem] p-6 shadow-sm border border-slate-100 dark:border-slate-800">
        <div className="flex items-center gap-4 mb-5">
          <div className={`p-3 rounded-2xl ${config.isProMode ? 'bg-pro-50 dark:bg-pro-900/30 text-pro-600' : 'bg-slate-100 dark:bg-slate-800 text-slate-400'}`}>
            <Zap className="w-6 h-6" />
          </div>
          <div>
            <h4 className="font-black text-slate-900 dark:text-white text-sm">Switch Mode</h4>
            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tight">Swipe to unlock business tools</p>
          </div>
        </div>

        <div 
          className="swipe-track relative h-16 bg-slate-50 dark:bg-slate-800 rounded-2xl flex items-center justify-center select-none overflow-hidden border border-slate-100 dark:border-slate-700" 
          ref={sliderRef}
          onMouseDown={handleSwipeStart}
          onTouchStart={handleSwipeStart}
        >
          <p className={`text-[10px] font-black uppercase tracking-[0.3em] transition-opacity duration-300 ${swipeX > 50 ? 'opacity-0' : 'opacity-40 text-slate-500'}`}>
            {config.isProMode ? 'Swipe Left for Lite' : 'Swipe Right for Pro'}
          </p>
          <div 
            className={`swipe-thumb absolute left-1 w-14 h-14 rounded-xl shadow-2xl flex items-center justify-center transition-shadow ${
              config.isProMode ? 'bg-pro-600 text-white' : 'bg-white dark:bg-slate-700 text-blue-600'
            }`}
            style={{ transform: `translateX(${swipeX}px)` }}
          >
            {config.isProMode ? <Zap className="w-7 h-7 fill-current" /> : <ChevronRight className="w-7 h-7" />}
          </div>
        </div>
      </div>

      {/* Business Intelligence (Pro Mode Only) */}
      {config.isProMode && (
        <div className="bg-white dark:bg-slate-900 rounded-[2.2rem] p-6 shadow-sm border border-slate-100 dark:border-slate-800 space-y-6 animate-in zoom-in-95 duration-500">
          <div className="flex items-center gap-4">
            <div className="p-3 bg-pro-50 dark:bg-pro-900/30 text-pro-600 rounded-2xl"><Building2 className="w-6 h-6" /></div>
            <div>
              <h4 className="font-black text-slate-900 dark:text-white text-sm">GST & Compliance</h4>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tight">Professional Taxation Settings</p>
            </div>
          </div>
          <div className="grid grid-cols-1 gap-5">
            <div className="group">
              <label className="text-[10px] font-black text-slate-400 uppercase ml-1 group-focus-within:text-pro-600 transition-colors">Business GSTIN</label>
              <input 
                type="text"
                placeholder="27AAAAA0000A1Z5"
                className="w-full p-4 mt-2 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl text-slate-900 dark:text-white font-black uppercase placeholder:text-slate-300 dark:placeholder:text-slate-600 focus:ring-2 focus:ring-pro-600 outline-none transition-all"
                value={config.gstNumber || ''}
                onChange={e => handleUpdate({ gstNumber: e.target.value })}
              />
            </div>
            <div className="group">
              <label className="text-[10px] font-black text-slate-400 uppercase ml-1 group-focus-within:text-pro-600 transition-colors">State / Pos Code</label>
              <input 
                type="text"
                placeholder="e.g. 27"
                className="w-full p-4 mt-2 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl text-slate-900 dark:text-white font-black placeholder:text-slate-300 focus:ring-2 focus:ring-pro-600 outline-none transition-all"
                value={config.stateCode || ''}
                onChange={e => handleUpdate({ stateCode: e.target.value })}
              />
            </div>
          </div>
        </div>
      )}

      {/* Aesthetic Options */}
      <div className="bg-white dark:bg-slate-900 rounded-[2.2rem] p-6 shadow-sm border border-slate-100 dark:border-slate-800">
        <div className="flex items-center gap-4 mb-6">
          <div className="p-3 bg-purple-50 dark:bg-purple-900/30 text-purple-600 rounded-2xl"><Palette className="w-6 h-6" /></div>
          <div>
            <h4 className="font-black text-slate-900 dark:text-white text-sm">Bill Aesthetics</h4>
            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tight">Select Printed Invoice Design</p>
          </div>
        </div>
        <div className="grid grid-cols-2 gap-4">
          {themes.map((t) => (
            <button
              key={t.id}
              onClick={() => handleUpdate({ invoiceTheme: t.id })}
              className={`relative p-5 rounded-[1.8rem] border-2 transition-all flex flex-col items-start gap-3 ${
                (config.invoiceTheme || InvoiceTheme.MODERN) === t.id 
                  ? 'border-pro-600 bg-pro-50 dark:bg-pro-900/20' 
                  : 'border-slate-50 dark:border-slate-800 bg-slate-50 dark:bg-slate-800/40'
              }`}
            >
              <div className={`w-10 h-10 ${t.color} rounded-2xl shadow-lg flex items-center justify-center transition-transform hover:scale-110`}>
                {(config.invoiceTheme || InvoiceTheme.MODERN) === t.id && <Check className="w-5 h-5 text-white" />}
              </div>
              <div className="text-left">
                <p className={`font-black text-xs ${(config.invoiceTheme || InvoiceTheme.MODERN) === t.id ? 'text-pro-700 dark:text-pro-400' : 'text-slate-900 dark:text-slate-200'}`}>{t.name}</p>
                <p className="text-[8px] text-slate-400 font-bold uppercase tracking-widest mt-0.5">{t.desc}</p>
              </div>
            </button>
          ))}
        </div>
      </div>

      {/* Security & System */}
      <div className="bg-white dark:bg-slate-900 rounded-[2.2rem] p-6 shadow-sm border border-slate-100 dark:border-slate-800 space-y-4">
        <div className="flex items-center gap-4 mb-2">
          <div className="p-3 bg-slate-100 dark:bg-slate-800 text-slate-600 rounded-2xl"><Settings2 className="w-6 h-6" /></div>
          <h4 className="font-black text-slate-900 dark:text-white text-sm">System Management</h4>
        </div>
        <div className="space-y-2">
          <SettingItem 
            icon={<Lock className="w-5 h-5" />} 
            bg="bg-slate-50 dark:bg-slate-800 text-slate-600 dark:text-slate-400"
            label="Security PIN Settings"
            onClick={() => {
              const p = prompt("Enter new 4-digit PIN:");
              if (p && p.length === 4) { handleUpdate({ pin: p }); alert("PIN updated successfully."); }
            }}
          />
          <SettingItem 
            icon={<HelpCircle className="w-5 h-5" />} 
            bg="bg-blue-50 dark:bg-blue-900/30 text-blue-600"
            label="Support & Training"
            onClick={() => window.open('https://patwaji.shop/help')}
          />
          <button 
            onClick={() => { if(confirm("This will permanently erase all business data. Proceed?")) { localStorage.clear(); window.location.reload(); } }}
            className="w-full flex items-center justify-center gap-3 p-5 text-red-600 font-black text-xs bg-red-50 dark:bg-red-900/10 rounded-[1.8rem] active:scale-95 transition-all mt-4 border border-red-100 dark:border-red-900/20"
          >
            <Trash2 className="w-5 h-5" /> Factory Reset App
          </button>
        </div>
      </div>

      <div className="flex flex-col items-center gap-3 py-10 opacity-30">
        <div className="flex items-center gap-2">
          <Globe className="w-4 h-4" />
          <p className="text-[10px] font-black uppercase tracking-[0.4em]">Patwa ji Global Business Suite</p>
        </div>
        <p className="text-[8px] font-black uppercase tracking-widest">Version 1.5.0-PRO-BETA • Built for Bharat</p>
      </div>

      {showSignPad && (
        <SignaturePad 
          onSave={(base64) => { handleUpdate({ signatureImage: base64 }); setShowSignPad(false); }}
          onCancel={() => setShowSignPad(false)}
        />
      )}
    </div>
  );
};

