);

const ActionButton: React.FC<{ icon: React.ReactNode, label: string, color: string, bg: string, onClick: () => void, count?: number }> = ({ icon, label, color, bg, onClick, count }) => (
  <button onClick={onClick} className="bg-white dark:bg-slate-900 p-6 rounded-[2.2rem] border border-slate-100 dark:border-slate-800 shadow-sm flex items-center justify-between group active:scale-[0.97] transition-all">
    <div className="flex items-center gap-4">
      <div className={`p-3 ${bg} ${color} rounded-2xl transition-transform group-hover:scale-110`}>{icon}</div>
      <p className="text-xs font-black text-slate-900 dark:text-white uppercase tracking-tighter">{label}</p>
    </div>
    {count !== undefined && count > 0 && (
      <span className="bg-red-600 text-white text-[10px] font-black w-6 h-6 rounded-full flex items-center justify-center shadow-xl shadow-red-600/30 animate-pulse">
