import React, { useState, useMemo } from 'react';
import { 
  Users, 
  Wallet, 
  TrendingUp, 
  ArrowUpRight, 
  Package, 
  ChevronRight,
  X,
  AlertCircle,
  QrCode,
  Share2,
  FileText,
  IndianRupee,
  Calendar,
  CreditCard,
  Banknote
} from 'lucide-react';
import { Invoice, Client, Product, AppConfig, Tab, PaymentMethod } from '../types';
import { formatCurrency, fileToBase64 } from '../utils/helpers';

interface DashboardProps {
  invoices: Invoice[];
  clients: Client[];
  products: Product[];
  config: AppConfig;
  onNavigate: (tab: Tab) => void;
  setConfig?: (config: AppConfig) => void;
}

type DateFilter = 'TODAY' | 'TOMORROW' | 'CUSTOM';

const Dashboard: React.FC<DashboardProps> = ({ invoices, clients, products, config, onNavigate, setConfig }) => {
  const [modalType, setModalType] = useState<'BORROWERS' | 'LOW_STOCK' | 'CLIENTS' | 'QR_MODAL' | null>(null);
  const [dateFilter, setDateFilter] = useState<DateFilter>('TODAY');
  const [customDate, setCustomDate] = useState(new Date().toISOString().split('T')[0]);
  const [showFilterDropdown, setShowFilterDropdown] = useState(false);

  const targetDateStr = useMemo(() => {
    if (dateFilter === 'TODAY') return new Date().toISOString().split('T')[0];
    if (dateFilter === 'TOMORROW') {
      const tomorrow = new Date();
      tomorrow.setDate(tomorrow.getDate() + 1);
      return tomorrow.toISOString().split('T')[0];
    }
    return customDate;
  }, [dateFilter, customDate]);

  const filteredInvoices = useMemo(() => {
    return invoices.filter(inv => inv.date.startsWith(targetDateStr));
  }, [invoices, targetDateStr]);

  const stats = useMemo(() => {
    const total = filteredInvoices.reduce((acc, inv) => acc + inv.grandTotal, 0);
    const cash = filteredInvoices
      .filter(inv => inv.paymentMethod === PaymentMethod.CASH)
      .reduce((acc, inv) => acc + inv.grandTotal, 0);
    const online = filteredInvoices
      .filter(inv => inv.paymentMethod === PaymentMethod.ONLINE)
      .reduce((acc, inv) => acc + inv.grandTotal, 0);
    const credit = filteredInvoices
      .filter(inv => inv.paymentMethod === PaymentMethod.BORROW)
      .reduce((acc, inv) => acc + inv.grandTotal, 0);

    return { total, cash, online, credit };
  }, [filteredInvoices]);

  const lowStockItems = products.filter(p => p.stock !== null && p.stock <= config.lowStockThreshold);

  const handleQRUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0] && setConfig) {
      const base64 = await fileToBase64(e.target.files[0]);
      const newConfig = { ...config, qrCodeImage: base64 };
      setConfig(newConfig);
      localStorage.setItem('app_config', JSON.stringify(newConfig));
    }
  };

  return (
    <div className="space-y-6 pb-20 animate-in fade-in duration-700">
      {/* Date Filter Bar */}
      <div className="flex justify-between items-center relative">
        <button 
          onClick={() => setShowFilterDropdown(!showFilterDropdown)}
          className="flex items-center gap-2 bg-white dark:bg-slate-900 px-4 py-2 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-800 text-[10px] font-black uppercase tracking-widest text-blue-600"
        >
          <Calendar className="w-4 h-4" />
          {dateFilter === 'CUSTOM' ? targetDateStr : dateFilter}
          <ChevronRight className={`w-3 h-3 transition-transform ${showFilterDropdown ? 'rotate-90' : ''}`} />
        </button>

        {showFilterDropdown && (
          <div className="absolute top-12 left-0 w-48 bg-white dark:bg-slate-900 rounded-2xl shadow-xl border border-slate-100 dark:border-slate-800 z-50 p-2 space-y-1">
            <button onClick={() => { setDateFilter('TODAY'); setShowFilterDropdown(false); }} className="w-full text-left px-4 py-3 text-[10px] font-black uppercase hover:bg-slate-50 dark:hover:bg-slate-800 rounded-xl">Today</button>
            <button onClick={() => { setDateFilter('TOMORROW'); setShowFilterDropdown(false); }} className="w-full text-left px-4 py-3 text-[10px] font-black uppercase hover:bg-slate-50 dark:hover:bg-slate-800 rounded-xl">Tomorrow</button>
            <div className="px-4 py-2 border-t border-slate-50 dark:border-slate-800">
              <p className="text-[8px] font-black text-slate-400 uppercase mb-2">Select Date</p>
              <input 
                type="date" 
                className="w-full bg-slate-50 dark:bg-slate-800 p-2 rounded-lg text-[10px] outline-none" 
                value={customDate}
                onChange={(e) => { setCustomDate(e.target.value); setDateFilter('CUSTOM'); setShowFilterDropdown(false); }}
              />
            </div>
          </div>
        )}

        {config.businessLogo && (
          <div className="w-10 h-10 rounded-xl overflow-hidden border border-slate-100 dark:border-slate-800 shadow-sm bg-white">
            <img src={config.businessLogo} alt="Logo" className="w-full h-full object-contain" />
          </div>
        )}
      </div>

      {/* Header Stat */}
      <div className={`p-8 rounded-[3rem] text-white shadow-2xl relative overflow-hidden transition-all duration-700 bg-gradient-to-br from-indigo-600 via-blue-600 to-indigo-800 shadow-indigo-600/20`}>
        <div className="relative z-10">
          <p className="text-white/60 text-[10px] font-black uppercase tracking-[0.3em] mb-3 flex items-center gap-2">
            <TrendingUp className="w-3 h-3" />
            {dateFilter} Revenue
          </p>
          <h3 className="text-5xl font-black tracking-tighter mb-6">
            {formatCurrency(stats.total)}
          </h3>
          <div className="flex flex-wrap gap-2">
            <span className="bg-white/10 backdrop-blur-xl px-4 py-2 rounded-full text-[9px] font-black uppercase tracking-widest flex items-center gap-2 border border-white/10">
              <ArrowUpRight className="w-3.5 h-3.5 text-emerald-400" /> {filteredInvoices.length} Invoices
            </span>
          </div>
        </div>
        <div className="absolute -right-16 -bottom-16 w-64 h-64 bg-white/5 rounded-full blur-3xl" />
      </div>

      {/* Payment Breakdown Cards */}
      <div className="grid grid-cols-2 gap-4">
        <div className="bg-white dark:bg-slate-900 p-5 rounded-[2rem] border border-slate-100 dark:border-slate-800 shadow-sm">
          <div className="flex items-center gap-3 mb-2">
            <div className="p-2 bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 rounded-xl"><Banknote className="w-4 h-4" /></div>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Cash Collection</p>
          </div>
          <p className="text-lg font-black text-slate-900 dark:text-white leading-none">{formatCurrency(stats.cash)}</p>
        </div>
        <div className="bg-white dark:bg-slate-900 p-5 rounded-[2rem] border border-slate-100 dark:border-slate-800 shadow-sm">
          <div className="flex items-center gap-3 mb-2">
            <div className="p-2 bg-blue-50 dark:bg-blue-900/20 text-blue-600 rounded-xl"><CreditCard className="w-4 h-4" /></div>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Online / UPI</p>
          </div>
          <p className="text-lg font-black text-slate-900 dark:text-white leading-none">{formatCurrency(stats.online)}</p>
        </div>
      </div>

      {/* Primary Metrics */}
      <div className="grid grid-cols-2 gap-4">
        <StatCard 
          icon={<Users className="w-6 h-6" />} 
          bg="bg-purple-50 dark:bg-purple-900/20" 
          label="Total Clients" 
          value={clients.length.toString()} 
          color="text-purple-600"
          onClick={() => setModalType('CLIENTS')}
        />
        <StatCard 
          icon={<Wallet className="w-6 h-6" />} 
          bg="bg-orange-50 dark:bg-orange-900/20" 
          label="Outstanding Credit" 
          value={formatCurrency(clients.reduce((acc, c) => acc + c.totalBorrowed, 0))} 
          color="text-orange-600"
          onClick={() => setModalType('BORROWERS')}
        />
      </div>

      {/* Functional Actions */}
      <div className="grid grid-cols-2 gap-3">
        <ActionButton 
          icon={<AlertCircle className="w-5 h-5" />} 
          label="Low Inventory" 
          count={lowStockItems.length}
          color="text-red-600"
          bg="bg-red-50 dark:bg-red-900/20"
          onClick={() => setModalType('LOW_STOCK')}
        />
        <ActionButton 
          icon={<QrCode className="w-5 h-5" />} 
          label="Payment QR" 
          color="text-blue-600"
          bg="bg-blue-50 dark:bg-blue-900/20"
          onClick={() => setModalType('QR_MODAL')}
        />
      </div>

      {/* Transaction Feed */}
      <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] p-8 shadow-sm border border-slate-100 dark:border-slate-800">
