      box: 'bg-slate-50 p-4 rounded-2xl border border-slate-100',
      tableHeader: 'border-b-2 border-slate-900',
      totalBox: 'bg-slate-900 p-4 rounded-2xl text-white shadow-lg',
    },
    [InvoiceTheme.CLASSIC]: {
      bg: 'bg-white',
      header: 'text-left border-b-4 border-black pb-4 mb-6',
      title: 'text-3xl font-serif font-black text-black uppercase',
      accent: 'text-black underline',
      box: 'border-2 border-black p-4 mb-4',
      tableHeader: 'border-y-2 border-black bg-slate-50',
      totalBox: 'border-2 border-black p-4 text-black font-black',
    },
    [InvoiceTheme.ELEGANT]: {
      bg: 'bg-white',
      header: 'text-center pb-8 mb-8 relative',
      title: 'text-4xl font-serif text-indigo-900 tracking-wide font-light italic',
