import React, { useRef, useEffect, useState } from 'react';
import { X, Zap, Camera } from 'lucide-react';

interface BarcodeScannerProps {
  onScan: (barcode: string) => void;
  onClose: () => void;
  title?: string;
}

const BarcodeScanner: React.FC<BarcodeScannerProps> = ({ onScan, onClose, title = "Scanner" }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [error, setError] = useState<string | null>(null);
  const [isSupported, setIsSupported] = useState<boolean>(true);

  useEffect(() => {
    // Check for BarcodeDetector support
    if (!('BarcodeDetector' in window)) {
      console.warn('BarcodeDetector is not supported in this browser.');
      // We will try to provide a fallback or just inform the user
      // Most modern Android Chrome and iOS 17+ support this.
    }

    let stream: MediaStream | null = null;
    let detectorInterval: number | null = null;

    const startCamera = async () => {
      try {
        stream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } }
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.play();
          setupDetection();
        }
      } catch (err) {
        setError("Camera access denied or not available.");
        setIsSupported(false);
      }
    };

    const setupDetection = () => {
      // @ts-ignore - BarcodeDetector might not be in the types
      if ('BarcodeDetector' in window) {
        // @ts-ignore
        const barcodeDetector = new window.BarcodeDetector({
          formats: ['code_128', 'ean_13', 'ean_8', 'qr_code', 'upc_a', 'upc_e', 'code_39']
        });

        detectorInterval = window.setInterval(async () => {
          if (videoRef.current && videoRef.current.readyState === videoRef.current.HAVE_ENOUGH_DATA) {
            try {
              const barcodes = await barcodeDetector.detect(videoRef.current);
              if (barcodes.length > 0) {
                onScan(barcodes[0].rawValue);
                // Vibrate on success if supported
                if ('vibrate' in navigator) navigator.vibrate(100);
                stopCamera();
              }
            } catch (e) {
              console.error('Detection error:', e);
            }
          }
        }, 200);
      } else {
        setError("Browser version doesn't support native scanning. Please use a modern browser.");
      }
    };

    const stopCamera = () => {
      if (detectorInterval) clearInterval(detectorInterval);
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
    };

    startCamera();

    return () => {
      stopCamera();
    };
  }, []);

  return (
    <div className="fixed inset-0 bg-black z-[200] flex flex-col items-center justify-center animate-in fade-in duration-300">
      <div className="absolute top-0 left-0 right-0 p-6 flex justify-between items-center z-10">
        <div className="text-white">
          <h3 className="text-lg font-black uppercase tracking-tight">{title}</h3>
          <p className="text-[10px] text-white/60 font-bold uppercase tracking-widest">Point camera at barcode</p>
        </div>
        <button onClick={onClose} className="p-4 bg-white/10 backdrop-blur-md rounded-full text-white active:scale-90 transition-transform">
          <X className="w-6 h-6" />
        </button>
      </div>

      <div className="relative w-full h-full flex items-center justify-center overflow-hidden">
        {error ? (
          <div className="p-8 text-center text-white space-y-4">
            <Camera className="w-16 h-16 mx-auto opacity-20" />
            <p className="font-bold text-sm text-red-400">{error}</p>
            <button onClick={onClose} className="bg-white/10 px-6 py-3 rounded-2xl font-black uppercase text-[10px]">Go Back</button>
          </div>
        ) : (
          <>
            <video 
              ref={videoRef} 
              className="w-full h-full object-cover" 
              playsInline 
              muted 
            />
            {/* Scanning UI Overlay */}
            <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
              <div className="w-72 h-48 border-2 border-white/30 rounded-[2rem] relative">
                <div className="absolute top-0 left-0 w-8 h-8 border-t-4 border-l-4 border-blue-500 rounded-tl-2xl"></div>
                <div className="absolute top-0 right-0 w-8 h-8 border-t-4 border-r-4 border-blue-500 rounded-tr-2xl"></div>
                <div className="absolute bottom-0 left-0 w-8 h-8 border-b-4 border-l-4 border-blue-500 rounded-bl-2xl"></div>
                <div className="absolute bottom-0 right-0 w-8 h-8 border-b-4 border-r-4 border-blue-500 rounded-br-2xl"></div>

                <div className="absolute top-1/2 left-0 right-0 h-0.5 bg-blue-500/50 animate-pulse shadow-[0_0_15px_rgba(59,130,246,0.5)]"></div>
              </div>
            </div>

            <div className="absolute bottom-12 text-center text-white/40 font-black uppercase tracking-[0.3em] text-[10px]">
              Align barcode within frame
            </div>
          </>
        )}
      </div>
    </div>
  );
};

export default BarcodeScanner;

import React, { useState } from 'react';
import { Package, Search, Plus, Edit2, Trash2, Save, X, AlertTriangle, ScanLine } from 'lucide-react';
import { Product, AppConfig } from '../types';
import { generateId, formatCurrency } from '../utils/helpers';
import BarcodeScanner from '../components/BarcodeScanner';

interface InventoryProps {
  products: Product[];
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  config: AppConfig;
}

const Inventory: React.FC<InventoryProps> = ({ products, setProducts, config }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [showAdd, setShowAdd] = useState(false);
  const [showScanner, setShowScanner] = useState(false);
  const [formData, setFormData] = useState<Partial<Product>>({ name: '', price: 0, stock: null, barcode: '' });

  const filteredProducts = products.filter(p => 
    p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    (p.barcode && p.barcode.includes(searchTerm))
  );

  const handleSave = () => {
    if (!formData.name || (formData.price || 0) <= 0) {
      alert("Kripya Naam aur Price likhein!");
      return;
    }

    if (editingId) {
      setProducts(prev => prev.map(p => p.id === editingId ? { ...p, ...formData } as Product : p));
      setEditingId(null);
    } else {
      setProducts(prev => [...prev, { ...formData, id: generateId() } as Product]);
      setShowAdd(false);
    }
    setFormData({ name: '', price: 0, stock: null, barcode: '' });
  };

  const startEdit = (product: Product) => {
    setEditingId(product.id);
    setFormData(product);
  };

  const handleBarcodeScanned = (barcode: string) => {
    setShowScanner(false);
    // Check if product with this barcode already exists
    const existing = products.find(p => p.barcode === barcode);
    if (existing) {
      startEdit(existing);
    } else {
      setFormData({ name: '', price: 0, stock: null, barcode });
      setShowAdd(true);
    }
  };

  return (
    <div className="space-y-6 pb-24">
      {/* Search Bar */}
      <div className="bg-white dark:bg-slate-900 p-4 rounded-3xl shadow-sm border border-slate-100 dark:border-slate-800 flex items-center gap-3">
        <Search className="w-5 h-5 text-slate-400" />
        <input 
          type="text"
          placeholder="Search by name or barcode..."
          className="flex-1 bg-transparent border-none outline-none text-slate-800 dark:text-white font-bold"
          value={searchTerm}
          onChange={e => setSearchTerm(e.target.value)}
        />
        <div className="flex gap-2">
          <button 
            onClick={() => setShowScanner(true)}
            className="bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 p-2.5 rounded-xl active:scale-95 transition-all"
          >
            <ScanLine className="w-5 h-5" />
          </button>
          <button 
            onClick={() => setShowAdd(true)}
            className="bg-blue-600 text-white p-2.5 rounded-xl active:scale-95 transition-all shadow-lg shadow-blue-100 dark:shadow-none"
          >
            <Plus className="w-5 h-5" />
          </button>
        </div>
      </div>

      {/* Scanner Modal */}
      {showScanner && (
        <BarcodeScanner 
          onScan={handleBarcodeScanned} 
          onClose={() => setShowScanner(false)} 
          title="Inventory Scanner"
        />
      )}

      {/* Add/Edit Form */}
      {(showAdd || editingId) && (
        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] shadow-2xl border border-blue-100 dark:border-blue-900 animate-in zoom-in duration-300">
          <div className="flex justify-between items-center mb-6">
            <h3 className="font-black text-slate-900 dark:text-white tracking-tight uppercase">{editingId ? 'Edit Item' : 'Add New Item'}</h3>
            <button onClick={() => { setShowAdd(false); setEditingId(null); }} className="p-2 bg-slate-100 dark:bg-slate-800 rounded-full text-slate-400"><X className="w-5 h-5" /></button>
          </div>
          <div className="space-y-5">
            <div className="flex gap-3">
              <div className="flex-1">
                <label className="text-[10px] font-black text-slate-400 uppercase ml-1">Barcode (ID)</label>
                <div className="relative">
                  <input 
                    type="text"
                    placeholder="Auto-filled via scan"
                    className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl p-4 outline-none font-bold text-slate-900 dark:text-white"
                    value={formData.barcode || ''}
                    onChange={e => setFormData({...formData, barcode: e.target.value})}
                  />
                  <button 
                    onClick={() => setShowScanner(true)}
                    className="absolute right-4 top-4 text-blue-600 active:scale-90 transition-transform"
                  >
                    <ScanLine className="w-5 h-5" />
                  </button>
                </div>
              </div>
            </div>

            <div>
              <label className="text-[10px] font-black text-slate-400 uppercase ml-1">Product Name</label>
              <input 
                type="text"
                className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl p-4 outline-none font-bold text-slate-900 dark:text-white"
                value={formData.name}
                onChange={e => setFormData({...formData, name: e.target.value})}
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase ml-1">Sale Price (₹)</label>
                <input 
                  type="number"
                  className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl p-4 outline-none font-bold text-slate-900 dark:text-white"
                  value={formData.price}
                  onChange={e => setFormData({...formData, price: parseFloat(e.target.value) || 0})}
                />
              </div>
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase ml-1">Stock (Qty)</label>
                <input 
                  type="number"
                  placeholder="∞ Unlimited"
                  className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl p-4 outline-none font-bold text-slate-900 dark:text-white"
                  value={formData.stock === null ? '' : formData.stock}
                  onChange={e => setFormData({...formData, stock: e.target.value === '' ? null : parseInt(e.target.value)})}
                />
              </div>
            </div>

            <button 
              onClick={handleSave}
              className="w-full bg-blue-600 text-white py-4 rounded-2xl font-black flex items-center justify-center gap-3 shadow-lg shadow-blue-100 dark:shadow-none active:scale-95 transition-all"
            >
              <Save className="w-5 h-5" /> {editingId ? 'Update Stock' : 'Add to Stock'}
            </button>
          </div>
        </div>
      )}

      {/* List */}
      <div className="space-y-3">
        {filteredProducts.map(p => {
          const isLow = p.stock !== null && p.stock <= config.lowStockThreshold;
          return (
            <div key={p.id} className="bg-white dark:bg-slate-900 p-5 rounded-[2rem] border border-slate-100 dark:border-slate-800 flex items-center justify-between shadow-sm group">
              <div className="flex items-center gap-4">
                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center ${isLow ? 'bg-red-50 text-red-600' : 'bg-blue-50 text-blue-600'}`}>
                  {isLow ? <AlertTriangle className="w-6 h-6" /> : <Package className="w-6 h-6" />}
                </div>
                <div>
                  <h4 className="font-black text-slate-900 dark:text-white text-sm tracking-tight">{p.name}</h4>
                  <div className="flex items-center gap-2 mt-0.5">
                    <p className="text-[10px] text-slate-400 font-bold">{formatCurrency(p.price)}</p>
                    {p.barcode && (
                      <>
                        <span className="text-[10px] text-slate-300 dark:text-slate-600">•</span>
                        <p className="text-[9px] text-slate-400 font-black uppercase tracking-widest">{p.barcode}</p>
                      </>
                    )}
                    <span className="text-[10px] text-slate-300 dark:text-slate-600">•</span>
                    <p className={`text-[10px] font-black uppercase ${isLow ? 'text-red-500' : 'text-slate-500'}`}>
                      Stock: {p.stock === null ? '∞' : p.stock}
                    </p>
                  </div>
                </div>
              </div>
              <div className="flex gap-1">
                <button onClick={() => startEdit(p)} className="p-3 text-slate-400 dark:text-slate-600 active:text-blue-600 transition-colors">
                  <Edit2 className="w-5 h-5" />
                </button>
                <button onClick={() => { if(confirm("Delete karein?")) setProducts(prev => prev.filter(x => x.id !== p.id)); }} className="p-3 text-slate-400 dark:text-slate-600 active:text-red-600 transition-colors">
                  <Trash2 className="w-5 h-5" />
                </button>
              </div>
            </div>
          );
        })}
        {filteredProducts.length === 0 && (
          <div className="text-center py-20 bg-white dark:bg-slate-900 rounded-[2.5rem] border-2 border-dashed border-slate-100 dark:border-slate-800">
             <Package className="w-16 h-16 text-slate-200 dark:text-slate-800 mx-auto mb-4" />
             <p className="text-slate-400 font-bold uppercase tracking-widest text-[10px]">No items found</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default Inventory;

