  config: AppConfig;
}

const Billing: React.FC<BillingProps> = ({ products, clients, setInvoices, setProducts, setClients, config }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [cart, setCart] = useState<InvoiceItem[]>([]);
  const [custName, setCustName] = useState('');
  const [custMobile, setCustMobile] = useState('');
  const [selectedClientId, setSelectedClientId] = useState<string | null>(null);

  const [discount, setDiscount] = useState(0);
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>(PaymentMethod.CASH);
  const [showCheckout, setShowCheckout] = useState(false);
  const [showQuickAdd, setShowQuickAdd] = useState(false);
  const [showScanner, setShowScanner] = useState(false);
  const [showClientList, setShowClientList] = useState(false);
  const [generatedInvoice, setGeneratedInvoice] = useState<Invoice | null>(null);

  const [quickAddForm, setQuickAddForm] = useState({ name: '', price: '', quantity: '1' });

  const filteredProducts = useMemo(() => {
    if (!searchTerm) return [];
    return products.filter(p => 
      p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      (p.barcode && p.barcode === searchTerm)
    );
  }, [searchTerm, products]);

  const addToCart = (product: Product | { name: string, price: number, quantity?: number, id?: string }) => {
    const qtyToAdd = 'quantity' in product ? (product.quantity || 1) : 1;

    setCart(prev => {
      const existing = prev.find(item => item.name === product.name);
      if (existing) {
        const newQty = existing.quantity + qtyToAdd;
        const newTotal = newQty * existing.price;
        return prev.map(item => item.name === product.name ? { 
          ...item, 
          quantity: newQty, 
          total: newTotal
        } : item);
      }

      const total = product.price * qtyToAdd;

      return [...prev, {
        id: ('id' in product ? product.id : generateId()) || generateId(),
        name: product.name,
        quantity: qtyToAdd,
        price: product.price,
        total: total
      }];
    });
    setSearchTerm('');
  };

  const handleBarcodeScanned = (barcode: string) => {
    setShowScanner(false);
    const product = products.find(p => p.barcode === barcode);
    if (product) {
      addToCart(product);
    } else {
      alert(`Product with barcode ${barcode} not found in inventory.`);
      // Optional: Ask if user wants to add it now?
    }
  };

  const handleQuickAdd = (e: React.FormEvent) => {
    e.preventDefault();
    if (!quickAddForm.name || !quickAddForm.price) return;

    addToCart({
      name: quickAddForm.name,
      price: parseFloat(quickAddForm.price),
      quantity: parseInt(quickAddForm.quantity)
    });

    setQuickAddForm({ name: '', price: '', quantity: '1' });
    setShowQuickAdd(false);
  };

  const handleFinish = () => {
    if (!custName) {
      alert("Kripya Grahak ka naam likhein!");
      return;
    }

    const subtotalVal = cart.reduce((acc, i) => acc + i.total, 0);
    const totalVal = subtotalVal * (1 - discount/100);

    const invoice: Invoice = {
      id: `INV-${Date.now().toString().slice(-6)}`,
      date: new Date().toISOString(),
      clientId: selectedClientId || 'WALK_IN',
      clientName: custName,
      clientMobile: custMobile,
      items: [...cart],
      discount,
      subtotal: subtotalVal,
      grandTotal: totalVal,
      paymentMethod
    };

    setInvoices(prev => [...prev, invoice]);

    setProducts(prev => prev.map(p => {
      const cartItem = cart.find(item => item.name === p.name);
      return (cartItem && p.stock !== null) ? { ...p, stock: p.stock - cartItem.quantity } : p;
    }));

    if (paymentMethod === PaymentMethod.BORROW) {
      setClients(prev => {
        const existingIdx = prev.findIndex(c => c.name === custName);
        if (existingIdx > -1) {
          const updated = [...prev];
          updated[existingIdx].totalBorrowed += invoice.grandTotal;
          return updated;
        } else {
          return [...prev, { id: generateId(), name: custName, mobile: custMobile, totalBorrowed: invoice.grandTotal }];
        }
      });
    }

    setGeneratedInvoice(invoice);
    setShowCheckout(false);
    setCart([]);
  };

  const subtotal = cart.reduce((acc, item) => acc + item.total, 0);
  const grandTotal = subtotal * (1 - discount / 100);

  if (generatedInvoice) {
    return (
      <div className="space-y-4">
        <div className="bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 p-5 rounded-[2rem] border border-emerald-100 dark:border-emerald-800 flex items-center gap-4">
          <CheckCircle2 className="w-8 h-8" />
          <div>
            <p className="font-black uppercase tracking-tight text-sm">Invoice Generated!</p>
            <p className="text-[10px] font-bold opacity-80">Bill successfully saved to history.</p>
          </div>
        </div>
        <InvoiceDetail invoice={generatedInvoice} config={config} />
        <button onClick={() => setGeneratedInvoice(null)} className="w-full bg-slate-900 dark:bg-blue-600 text-white py-5 rounded-2xl font-black uppercase tracking-widest active:scale-95 transition-all">Banayein Naya Bill</button>
      </div>
    );
  }

  return (
    <div className="space-y-6 pb-24 animate-in fade-in duration-500">
      {/* Scanner Component */}
      {showScanner && (
        <BarcodeScanner 
          onScan={handleBarcodeScanned} 
          onClose={() => setShowScanner(false)} 
          title="Billing Scanner"
        />
      )}

      {/* Customer Info Card */}
      <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] shadow-sm border border-slate-100 dark:border-slate-800 space-y-4">
        <div className="flex justify-between items-center mb-2">
          <h3 className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Customer Details</h3>
          <button onClick={() => setShowClientList(true)} className="flex items-center gap-1.5 text-blue-600 font-black text-[10px] bg-blue-50 dark:bg-blue-900/40 px-3 py-1.5 rounded-full uppercase transition-all active:scale-95">
            <Users className="w-3.5 h-3.5" /> Directory
          </button>
        </div>
        <div className="grid grid-cols-1 gap-3">
          <input 
            type="text" placeholder="Grahak ka Naam (Required) *" 
            className="w-full p-4 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl text-slate-900 dark:text-white font-black outline-none"
            value={custName} onChange={e => setCustName(e.target.value)}
          />
          <input 
            type="tel" placeholder="Mobile No. (Optional)" 
            className="w-full p-4 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl text-slate-900 dark:text-white font-black outline-none"
            value={custMobile} onChange={e => setCustMobile(e.target.value.replace(/[^0-9]/g, ''))}
          />
        </div>
      </div>

      {/* Product Search & Scan */}
      <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] shadow-sm border border-slate-100 dark:border-slate-800 space-y-4">
        <div className="flex items-center gap-2">
          <div className="flex-1 relative">
            <Search className="absolute left-4 top-4 w-5 h-5 text-slate-300" />
            <input 
              type="text" placeholder="Search name or scan barcode..." 
              className="w-full pl-12 pr-4 py-4 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl text-slate-900 dark:text-white font-black outline-none"
              value={searchTerm} onChange={e => setSearchTerm(e.target.value)}
            />
          </div>
          <button 
            onClick={() => setShowScanner(true)}
            className="p-4 bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 rounded-2xl transition-all active:scale-95"
          >
            <ScanLine className="w-6 h-6" />
          </button>
          <button onClick={() => setShowQuickAdd(true)} className="p-4 bg-blue-600 text-white rounded-2xl shadow-lg shadow-blue-100 dark:shadow-none transition-all active:scale-95">
            <Plus className="w-6 h-6" />
          </button>
        </div>

        {searchTerm && filteredProducts.length > 0 && (
          <div className="max-h-64 overflow-y-auto pt-2 space-y-2">
            {filteredProducts.map(p => (
              <button key={p.id} onClick={() => addToCart(p)} className="w-full flex justify-between items-center p-4 hover:bg-slate-50 dark:hover:bg-slate-800/50 rounded-2xl transition-colors text-left border border-transparent hover:border-blue-100">
                <div>
                  <p className="font-black text-xs text-slate-900 dark:text-white uppercase tracking-tight">{p.name}</p>
                  <p className="text-[9px] text-slate-400 font-bold uppercase">STOCK: {p.stock ?? '∞'} {p.barcode ? `• ID: ${p.barcode}` : ''}</p>
                </div>
                <p className="font-black text-blue-600 text-sm">{formatCurrency(p.price)}</p>
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Cart Items */}
      <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] p-6 shadow-sm border border-slate-100 dark:border-slate-800">
        <h3 className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-6">Cart Summary ({cart.length})</h3>
        {cart.length === 0 ? (
          <div className="text-center py-10 opacity-30"><Package className="w-16 h-16 mx-auto mb-3" /><p className="text-[10px] font-black uppercase tracking-widest">Cart is empty</p></div>
        ) : (
          <div className="space-y-6">
            {cart.map(item => (
              <div key={item.name} className="flex items-center justify-between">
                <div className="flex-1">
                  <p className="font-black text-xs text-slate-900 dark:text-white uppercase tracking-tight">{item.name}</p>
                  <p className="text-[9px] text-slate-400 font-bold uppercase">{formatCurrency(item.price)}</p>
                </div>
                <div className="flex items-center gap-4">
                  <div className="flex items-center bg-slate-50 dark:bg-slate-800 rounded-xl p-1 border border-slate-100 dark:border-slate-700">
                    <button onClick={() => setCart(prev => prev.map(i => i.name === item.name ? {...i, quantity: Math.max(1, i.quantity - 1), total: Math.max(1, i.quantity - 1)*i.price} : i))} className="p-1.5 text-slate-400"><Minus className="w-4 h-4" /></button>
                    <span className="w-8 text-center font-black text-xs text-slate-900 dark:text-white">{item.quantity}</span>
                    <button onClick={() => setCart(prev => prev.map(i => i.name === item.name ? {...i, quantity: i.quantity + 1, total: (i.quantity+1)*i.price} : i))} className="p-1.5 text-slate-400"><Plus className="w-4 h-4" /></button>
                  </div>
                  <button onClick={() => setCart(prev => prev.filter(i => i.name !== item.name))} className="text-slate-200 hover:text-red-500 transition-colors"><Trash2 className="w-5 h-5" /></button>
                </div>
              </div>
            ))}
            <div className="border-t border-slate-50 dark:border-slate-800 pt-6 space-y-3">
              <div className="flex justify-between text-[10px] font-black text-slate-400 uppercase tracking-widest"><span>Subtotal</span><span>{formatCurrency(subtotal)}</span></div>
              <div className="flex justify-between items-center text-[10px] font-black text-slate-400 uppercase tracking-widest">
                <span>Discount (%)</span>
                <input type="number" className="w-14 text-right p-2 bg-slate-50 dark:bg-slate-800 rounded-lg font-black text-slate-900 dark:text-white" value={discount} onChange={e => setDiscount(Number(e.target.value) || 0)} />
              </div>
              <div className="flex justify-between text-lg font-black text-blue-600 pt-3 border-t border-blue-50 dark:border-blue-900/50"><span>Grand Total</span><span>{formatCurrency(grandTotal)}</span></div>
            </div>
            <button onClick={() => setShowCheckout(true)} className="w-full bg-blue-600 text-white py-5 rounded-2xl font-black uppercase tracking-widest shadow-xl shadow-blue-100 dark:shadow-none active:scale-95 transition-all">Proceed to Payment</button>
          </div>
        )}
      </div>

      {/* Quick Add Modal */}
      {showQuickAdd && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-md z-[100] flex items-end justify-center">
          <div className="bg-white dark:bg-slate-950 w-full max-w-lg rounded-t-[3rem] p-8 animate-slide-up">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-black text-slate-900 dark:text-white uppercase tracking-tight">Quick Add Product</h3>
              <button onClick={() => setShowQuickAdd(false)} className="p-2 bg-slate-100 dark:bg-slate-800 text-slate-500 rounded-full"><X className="w-6 h-6" /></button>
            </div>
            <form onSubmit={handleQuickAdd} className="space-y-4">
              <input type="text" autoFocus required placeholder="Product Name" className="w-full p-4 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl text-slate-900 dark:text-white font-black" value={quickAddForm.name} onChange={e => setQuickAddForm({...quickAddForm, name: e.target.value})} />
              <div className="grid grid-cols-2 gap-4">
                <input type="number" required placeholder="Price (₹)" className="w-full p-4 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl text-slate-900 dark:text-white font-black" value={quickAddForm.price} onChange={e => setQuickAddForm({...quickAddForm, price: e.target.value})} />
                <input type="number" required placeholder="Quantity" className="w-full p-4 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl text-slate-900 dark:text-white font-black" value={quickAddForm.quantity} onChange={e => setQuickAddForm({...quickAddForm, quantity: e.target.value})} />
              </div>
              <button type="submit" className="w-full bg-blue-600 text-white py-5 rounded-2xl font-black uppercase tracking-widest active:scale-95 transition-all">Add to Cart</button>
            </form>
          </div>
        </div>
      )}

      {/* Checkout Modal */}
      {showCheckout && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-md z-[100] flex items-end justify-center">
          <div className="bg-white dark:bg-slate-950 w-full max-w-lg rounded-t-[3rem] p-8 animate-slide-up">
            <div className="flex justify-between items-center mb-8"><h3 className="text-xl font-black text-slate-900 dark:text-white uppercase tracking-tight">Payment Method</h3><button onClick={() => setShowCheckout(false)} className="p-2 bg-slate-100 dark:bg-slate-800 text-slate-500 rounded-full"><X className="w-6 h-6" /></button></div>
            <div className="grid grid-cols-1 gap-4 mb-8">
              <button onClick={() => setPaymentMethod(PaymentMethod.CASH)} className={`flex items-center gap-5 p-5 rounded-[1.5rem] border-2 transition-all ${paymentMethod === PaymentMethod.CASH ? 'bg-blue-50 border-blue-600' : 'bg-slate-50 dark:bg-slate-800 border-transparent'}`}>
                <div className="p-3 bg-white dark:bg-slate-700 rounded-xl shadow-sm"><Banknote className="w-6 h-6 text-emerald-500" /></div>
                <div className="text-left"><p className="font-black text-sm text-slate-900 dark:text-white">Cash Payment</p><p className="text-[10px] text-slate-400 font-bold uppercase">Paid via Rokda</p></div>
              </button>
              <button onClick={() => setPaymentMethod(PaymentMethod.ONLINE)} className={`flex items-center gap-5 p-5 rounded-[1.5rem] border-2 transition-all ${paymentMethod === PaymentMethod.ONLINE ? 'bg-blue-50 border-blue-600' : 'bg-slate-50 dark:bg-slate-800 border-transparent'}`}>
                <div className="p-3 bg-white dark:bg-slate-700 rounded-xl shadow-sm"><CreditCard className="w-6 h-6 text-blue-500" /></div>
                <div className="text-left"><p className="font-black text-sm text-slate-900 dark:text-white">Online / UPI</p><p className="text-[10px] text-slate-400 font-bold uppercase">Paid via QR Code</p></div>
              </button>
              <button onClick={() => setPaymentMethod(PaymentMethod.BORROW)} className={`flex items-center gap-5 p-5 rounded-[1.5rem] border-2 transition-all ${paymentMethod === PaymentMethod.BORROW ? 'bg-blue-50 border-blue-600' : 'bg-slate-50 dark:bg-slate-800 border-transparent'}`}>
                <div className="p-3 bg-white dark:bg-slate-700 rounded-xl shadow-sm"><Clock className="w-6 h-6 text-orange-500" /></div>
                <div className="text-left"><p className="font-black text-sm text-slate-900 dark:text-white">Udhaar / Credit</p><p className="text-[10px] text-slate-400 font-bold uppercase">Add to khata</p></div>
              </button>
            </div>
            <button onClick={handleFinish} className="w-full bg-blue-600 text-white py-5 rounded-2xl font-black uppercase tracking-[0.2em] shadow-xl shadow-blue-100 dark:shadow-none active:scale-95 transition-all">Generate Invoice</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default Billing;

import React, { useRef } from 'react';
import { Printer, Download, Share2 } from 'lucide-react';
import { Invoice, AppConfig, PaymentMethod, InvoiceTheme } from '../types';
import { formatCurrency, numberToWords } from '../utils/helpers';

interface InvoiceDetailProps {
  invoice: Invoice;
  config: AppConfig;
}

const InvoiceDetail: React.FC<InvoiceDetailProps> = ({ invoice, config }) => {
  const invoiceRef = useRef<HTMLDivElement>(null);

  const handlePrint = () => {
    window.print();
  };

  const handleDownload = async () => {
    if (!invoiceRef.current) return;
    const { jsPDF } = (window as any).jspdf;

    const element = invoiceRef.current;

    try {
      const canvas = await (window as any).html2canvas(element, {
        scale: 3,
        useCORS: true,
        backgroundColor: '#ffffff',
        logging: false,
      });
      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF('p', 'mm', 'a4');
      const imgProps = pdf.getImageProperties(imgData);
      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = (imgProps.height * pdfWidth) / imgProps.width;

      pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
      const fileName = `Bill_${invoice.id}_${invoice.clientName.replace(/[^a-z0-9]/gi, '_').toLowerCase()}.pdf`;
      pdf.save(fileName);
    } catch (err) {
      console.error("PDF Export failed", err);
      alert("Failed to generate PDF. Please try printing instead.");
    }
  };

  const handleShare = async () => {
    if (!invoice.clientMobile) {
      alert("Grahak ka mobile number nahi hai!");
      return;
    }
    const message = `Namaste! ${config.shopName} se aapka bill.\nBill No: ${invoice.id}\nAmount: ${formatCurrency(invoice.grandTotal)}\nDhanyawad!`;
    const url = `https://wa.me/91${invoice.clientMobile}?text=${encodeURIComponent(message)}`;
    window.open(url, '_blank');
  };

  const formattedDate = new Date(invoice.date).toLocaleDateString('en-GB', {
    day: '2-digit',
    month: 'short',
    year: 'numeric'
  });

  return (
    <div className="space-y-4">
      <div className="bg-white dark:bg-slate-900 p-2 rounded-2xl flex justify-around no-print shadow-sm border border-slate-100 dark:border-slate-800">
        <button onClick={handlePrint} className="flex flex-col items-center gap-1 text-blue-600 font-bold text-[10px] p-2 active:scale-95 transition-all">
          <Printer className="w-5 h-5" /> Print
        </button>
        <button onClick={handleDownload} className="flex flex-col items-center gap-1 text-blue-600 font-bold text-[10px] p-2 active:scale-95 transition-all">
          <Download className="w-5 h-5" /> PDF
        </button>
        <button onClick={handleShare} className="flex flex-col items-center gap-1 text-green-600 font-bold text-[10px] p-2 active:scale-95 transition-all">
          <Share2 className="w-5 h-5" /> WhatsApp
        </button>
      </div>

      {/* Main Invoice Container */}
      <div 
        ref={invoiceRef}
        className="bg-white p-0 relative overflow-hidden min-h-[1000px] flex flex-col print:shadow-none print:border-none"
        style={{ width: '100%', maxWidth: '800px', margin: '0 auto', fontFamily: 'Inter, sans-serif' }}
      >
        {/* Diagonal Watermark */}
        <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-[0.05] z-0 select-none">
          <span className="text-[120px] font-black uppercase -rotate-45 text-slate-900 tracking-tighter">
            Billmax
          </span>
        </div>

        {/* Header Section */}
        <div className="relative z-10 p-10 flex justify-between items-start">
          <div className="flex gap-6 items-center">
            {config.businessLogo && (
              <div className="w-28 h-28 bg-black flex items-center justify-center p-2 rounded-lg shrink-0">
                <img src={config.businessLogo} alt="Logo" className="max-w-full max-h-full object-contain" />
              </div>
            )}
            <div className="space-y-0.5">
              <h1 className="text-2xl font-black text-slate-900 tracking-tight">{config.shopName}</h1>
              <p className="text-xs font-bold text-slate-600">Mobile +91 {config.shopMobile}</p>
            </div>
          </div>
          <div className="text-right">
            <h2 className="text-xl font-black text-blue-700 tracking-widest">INVOICE</h2>
            <p className="text-[9px] font-bold text-slate-500 uppercase tracking-widest mt-1">ORIGINAL FOR RECIPIENT</p>
          </div>
        </div>

        {/* Client & Invoice Meta Info */}
        <div className="relative z-10 px-10 grid grid-cols-2 gap-10 mb-8">
          <div className="space-y-1">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Bill To:</p>
            <h3 className="text-base font-black text-slate-900 uppercase">{invoice.clientName}</h3>
            <p className="text-xs font-bold text-slate-600">Ph: {invoice.clientMobile || '-'}</p>
          </div>
          <div className="flex flex-col items-end gap-1">
            <div className="flex w-full max-w-[200px] justify-between text-xs">
              <span className="font-bold text-slate-500">Invoice #:</span>
              <span className="font-black text-slate-900">{invoice.id}</span>
            </div>
            <div className="flex w-full max-w-[200px] justify-between text-xs">
              <span className="font-bold text-slate-500">Invoice Date:</span>
              <span className="font-black text-slate-900">{formattedDate}</span>
            </div>
            <div className="flex w-full max-w-[200px] justify-between text-xs">
              <span className="font-bold text-slate-500">Due Date:</span>
              <span className="font-black text-slate-900">{formattedDate}</span>
            </div>
          </div>
        </div>

        {/* Product Table */}
        <div className="relative z-10 px-10 flex-1">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-blue-600 text-white">
                <th className="py-2 px-3 text-[10px] font-black uppercase tracking-widest border border-blue-600">#</th>
                <th className="py-2 px-3 text-[10px] font-black uppercase tracking-widest border border-blue-600">Item</th>
                <th className="py-2 px-3 text-[10px] font-black uppercase tracking-widest border border-blue-600 text-center">HSN/SAC</th>
                <th className="py-2 px-3 text-[10px] font-black uppercase tracking-widest border border-blue-600 text-right">Rate / Item</th>
                <th className="py-2 px-3 text-[10px] font-black uppercase tracking-widest border border-blue-600 text-center">Qty</th>
                <th className="py-2 px-3 text-[10px] font-black uppercase tracking-widest border border-blue-600 text-right">Amount</th>
              </tr>
            </thead>
            <tbody className="text-slate-900">
              {invoice.items.map((item, idx) => (
                <tr key={idx} className="border-b border-slate-100">
                  <td className="py-3 px-3 text-xs font-bold text-slate-500 border-x border-slate-100">{idx + 1}</td>
                  <td className="py-3 px-3 text-xs font-black border-r border-slate-100">{item.name}</td>
                  <td className="py-3 px-3 text-xs font-bold text-slate-400 text-center border-r border-slate-100">-</td>
                  <td className="py-3 px-3 text-xs font-bold text-right border-r border-slate-100">{item.price.toFixed(2)}</td>
                  <td className="py-3 px-3 text-xs font-black text-center border-r border-slate-100">{item.quantity}</td>
                  <td className="py-3 px-3 text-xs font-black text-right border-r border-slate-100">{item.total.toFixed(2)}</td>
                </tr>
              ))}
            </tbody>
          </table>

          {/* Table Footer - Total Items */}
          <div className="flex justify-between items-center py-2 px-3 bg-slate-50 border-x border-b border-slate-100 mb-1">
            <p className="text-[9px] font-bold text-slate-400 uppercase">Total Items / Qty : {invoice.items.length} / {invoice.items.reduce((acc, i) => acc + i.quantity, 0)}</p>
            <div className="flex gap-4">
               <span className="text-xs font-black text-slate-900">Total</span>
               <span className="text-xs font-black text-slate-900">₹{invoice.subtotal.toFixed(2)}</span>
            </div>
          </div>
        </div>

        {/* Totals & Signatory */}
        <div className="relative z-10 px-10 pb-10 space-y-8 mt-4">
          <div className="flex flex-col items-end">
            <div className="w-full max-w-[250px] space-y-1 text-right">
              {invoice.discount > 0 && (
                <div className="flex justify-between text-xs font-bold text-green-600 mb-1">
                  <span>Discount ({invoice.discount}%):</span>
                  <span>-₹{((invoice.subtotal * invoice.discount) / 100).toFixed(2)}</span>
                </div>
              )}
              <p className="text-[9px] font-bold text-slate-500 uppercase">Total amount (in words): {numberToWords(invoice.grandTotal)}</p>
              <div className="flex justify-between items-center py-2 border-t border-slate-100 mt-2">
                <span className="text-xs font-black text-slate-500 uppercase">Amount Payable:</span>
                <span className="text-base font-black text-slate-900">₹ {invoice.grandTotal.toFixed(2)}</span>
              </div>
            </div>
          </div>

          <div className="flex justify-between items-end">
             <div className="space-y-4">
                <div className="space-y-1">
                   <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Payment Mode</p>
                   <p className="text-xs font-black text-slate-900">{invoice.paymentMethod}</p>
                </div>
                {invoice.paymentMethod === PaymentMethod.ONLINE && config.qrCodeImage && (
                  <div className="w-16 h-16 border p-1 rounded-lg">
                    <img src={config.qrCodeImage} alt="QR" className="w-full h-full object-contain" />
                  </div>
                )}
             </div>

             <div className="text-center min-w-[180px]">
                <p className="text-[9px] font-black text-slate-500 uppercase mb-2">For {config.shopName}</p>
                {config.signatureImage ? (
                  <div className="h-16 flex items-center justify-center mb-2">
                    <img src={config.signatureImage} alt="Sign" className="max-h-full grayscale contrast-125" />
                  </div>
                ) : (
                  <div className="h-16"></div>
                )}
                <div className="border-t border-slate-200 pt-2">
                  <p className="text-[10px] font-black text-slate-900 uppercase">Authorized Signatory</p>
                </div>
             </div>
          </div>
        </div>

        {/* Footer Branding */}
        <div className="mt-auto bg-slate-50 p-6 flex flex-col items-center gap-2 border-t border-slate-100">
          <div className="flex items-center gap-4 text-[9px] text-blue-600 font-bold uppercase tracking-widest">
            <span>Billmax | Smart Invoicing & Payments</span>
            <span className="text-slate-300">•</span>
            <span>Visit patwaji.app</span>
          </div>
          <div className="flex items-center gap-1.5 opacity-80">
            <span className="text-[8px] font-bold text-slate-400 uppercase">Powered By</span>
            <span className="text-[12px] font-black text-slate-900 tracking-tighter">billmax</span>
            <img src="https://upload.wikimedia.org/wikipedia/commons/4/41/Flag_of_India.svg" className="w-3 h-2 rounded-sm ml-0.5" alt="India" />
          </div>
          <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">Ab Business karo tension free</p>
        </div>
      </div>
    </div>
  );
};

export default InvoiceDetail;

export enum PaymentMethod {
  CASH = 'CASH',
  ONLINE = 'ONLINE',
  BORROW = 'BORROW'
}

export enum ItemType {
  PRODUCT = 'PRODUCT',
  SERVICE = 'SERVICE'
}

export enum InvoiceTheme {
  MODERN = 'MODERN',
  CLASSIC = 'CLASSIC',
  ELEGANT = 'ELEGANT',
  MINIMAL = 'MINIMAL'
}

export interface Product {
  id: string;
  type: ItemType;
  name: string;
  price: number;
  stock: number | null; // null for unlimited or services
  barcode?: string;
}

export interface Client {
  id: string;
  name: string;
  mobile?: string;
  email?: string;
  totalBorrowed: number;
}

export interface InvoiceItem {
  id: string;
  name: string;
  quantity: number;
  price: number;
  total: number;
  type?: ItemType;
}

export interface Invoice {
  id: string;
  date: string;
  clientId: string | 'WALK_IN';
  clientName: string;
  clientMobile?: string;
  items: InvoiceItem[];
  discount: number; // percentage
  subtotal: number;
  grandTotal: number;
  paymentMethod: PaymentMethod;
}

export interface AppConfig {
  ownerName: string;
  shopName: string;
  shopMobile: string;
  pin: string;
  signatureImage?: string;
  qrCodeImage?: string;
  businessLogo?: string;
  lowStockThreshold: number;
  setupComplete: boolean;
  invoiceTheme?: InvoiceTheme;
  isDarkMode: boolean;
}

export enum Tab {
  DASHBOARD = 'DASHBOARD',
  BILLING = 'BILLING',
  INVENTORY = 'INVENTORY',
  INVOICES = 'INVOICES',
  SETTINGS = 'SETTINGS'
}

import React, { useState, useMemo } from 'react';
import { 
  Users, 
  Wallet, 
  TrendingUp, 
  ArrowUpRight, 
  Package, 
  ChevronRight,
  X,
  AlertCircle,
  QrCode,
  FileText,
  IndianRupee,
  Calendar,
  CreditCard,
  Banknote,
  ChevronDown,
  Filter
} from 'lucide-react';
import { Invoice, Client, Product, AppConfig, Tab, PaymentMethod } from '../types';
import { formatCurrency, fileToBase64 } from '../utils/helpers';

interface DashboardProps {
  invoices: Invoice[];
  clients: Client[];
  products: Product[];
  config: AppConfig;
  onNavigate: (tab: Tab) => void;
  setConfig?: (config: AppConfig) => void;
}

type DateFilterType = 'TODAY' | 'TOMORROW' | 'YEAR' | 'ALL' | 'RANGE';

const Dashboard: React.FC<DashboardProps> = ({ invoices, clients, products, config, onNavigate, setConfig }) => {
  const [modalType, setModalType] = useState<'BORROWERS' | 'LOW_STOCK' | 'CLIENTS' | 'QR_MODAL' | null>(null);
  const [dateFilter, setDateFilter] = useState<DateFilterType>('TODAY');
  const [startDate, setStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [endDate, setEndDate] = useState(new Date().toISOString().split('T')[0]);
  const [showFilters, setShowFilters] = useState(false);

  const filteredInvoices = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    const tomorrowDate = new Date();
    tomorrowDate.setDate(tomorrowDate.getDate() + 1);
    const tomorrow = tomorrowDate.toISOString().split('T')[0];
    const currentYear = new Date().getFullYear().toString();

    return invoices.filter(inv => {
      const invDate = inv.date.split('T')[0];
      if (dateFilter === 'TODAY') return invDate === today;
      if (dateFilter === 'TOMORROW') return invDate === tomorrow;
      if (dateFilter === 'YEAR') return inv.date.startsWith(currentYear);
      if (dateFilter === 'ALL') return true;
      if (dateFilter === 'RANGE') return invDate >= startDate && invDate <= endDate;
      return false;
    });
  }, [invoices, dateFilter, startDate, endDate]);

  const stats = useMemo(() => {
    const total = filteredInvoices.reduce((acc, inv) => acc + inv.grandTotal, 0);
    const cash = filteredInvoices
      .filter(inv => inv.paymentMethod === PaymentMethod.CASH)
      .reduce((acc, inv) => acc + inv.grandTotal, 0);
    const online = filteredInvoices
      .filter(inv => inv.paymentMethod === PaymentMethod.ONLINE)
      .reduce((acc, inv) => acc + inv.grandTotal, 0);
    return { total, cash, online };
  }, [filteredInvoices]);

  const lowStockItems = products.filter(p => p.stock !== null && p.stock <= config.lowStockThreshold);

  const filterLabel = useMemo(() => {
    if (dateFilter === 'TODAY') return 'Today';
    if (dateFilter === 'TOMORROW') return 'Tomorrow';
    if (dateFilter === 'YEAR') return 'This Year';
    if (dateFilter === 'ALL') return 'All Time';
    return `${startDate} to ${endDate}`;
  }, [dateFilter, startDate, endDate]);

  const handleQRUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0] && setConfig) {
      const base64 = await fileToBase64(e.target.files[0]);
      const newConfig = { ...config, qrCodeImage: base64 };
      setConfig(newConfig);
      localStorage.setItem('app_config', JSON.stringify(newConfig));
    }
  };

  return (
    <div className="space-y-6 pb-20 animate-in fade-in duration-700">
      {/* Date Filter Bar */}
      <div className="flex justify-between items-center relative gap-3">
        <div className="relative flex-1">
          <button 
            onClick={() => setShowFilters(!showFilters)}
            className="w-full flex items-center justify-between bg-white dark:bg-slate-900 px-5 py-3 rounded-[1.2rem] shadow-sm border border-slate-100 dark:border-slate-800 text-[10px] font-black uppercase tracking-widest text-blue-600 active:scale-95 transition-all"
          >
            <div className="flex items-center gap-2">
              <Calendar className="w-4 h-4" />
              <span>{filterLabel} Sales</span>
            </div>
            <ChevronDown className={`w-4 h-4 transition-transform ${showFilters ? 'rotate-180' : ''}`} />
          </button>

          {showFilters && (
            <div className="absolute top-14 left-0 w-full bg-white dark:bg-slate-900 rounded-[2rem] shadow-2xl border border-slate-100 dark:border-slate-800 z-50 p-2 space-y-1 animate-in slide-in-from-top-2 duration-200">
              <button onClick={() => { setDateFilter('TODAY'); setShowFilters(false); }} className={`w-full text-left px-4 py-3 text-[10px] font-black uppercase rounded-xl ${dateFilter === 'TODAY' ? 'bg-blue-50 text-blue-600' : 'hover:bg-slate-50'}`}>Today</button>
              <button onClick={() => { setDateFilter('TOMORROW'); setShowFilters(false); }} className={`w-full text-left px-4 py-3 text-[10px] font-black uppercase rounded-xl ${dateFilter === 'TOMORROW' ? 'bg-blue-50 text-blue-600' : 'hover:bg-slate-50'}`}>Tomorrow</button>
              <button onClick={() => { setDateFilter('YEAR'); setShowFilters(false); }} className={`w-full text-left px-4 py-3 text-[10px] font-black uppercase rounded-xl ${dateFilter === 'YEAR' ? 'bg-blue-50 text-blue-600' : 'hover:bg-slate-50'}`}>Year Sales</button>
              <button onClick={() => { setDateFilter('ALL'); setShowFilters(false); }} className={`w-full text-left px-4 py-3 text-[10px] font-black uppercase rounded-xl ${dateFilter === 'ALL' ? 'bg-blue-50 text-blue-600' : 'hover:bg-slate-50'}`}>All Time Sales</button>

              <div className="px-4 py-3 border-t border-slate-50 dark:border-slate-800 space-y-3">
                <p className="text-[8px] font-black text-slate-400 uppercase">Custom Range</p>
                <div className="grid grid-cols-2 gap-2">
                  <input 
                    type="date" 
                    className="w-full bg-slate-50 dark:bg-slate-800 p-2 rounded-xl text-[10px] font-bold outline-none border border-slate-100" 
                    value={startDate}
                    onChange={(e) => { setStartDate(e.target.value); setDateFilter('RANGE'); }}
                  />
                  <input 
                    type="date" 
                    className="w-full bg-slate-50 dark:bg-slate-800 p-2 rounded-xl text-[10px] font-bold outline-none border border-slate-100" 
                    value={endDate}
                    onChange={(e) => { setEndDate(e.target.value); setDateFilter('RANGE'); }}
                  />
                </div>
                {dateFilter === 'RANGE' && (
                  <button onClick={() => setShowFilters(false)} className="w-full py-2 bg-blue-600 text-white rounded-lg text-[9px] font-black uppercase tracking-widest">Apply Filter</button>
                )}
              </div>
            </div>
          )}
        </div>

        {config.businessLogo && (
          <div className="w-12 h-12 rounded-[1.2rem] overflow-hidden border-2 border-white dark:border-slate-800 shadow-lg bg-white shrink-0">
            <img src={config.businessLogo} alt="Logo" className="w-full h-full object-contain" />
          </div>
        )}
      </div>

      {/* Main Revenue Display */}
      <div className={`p-8 rounded-[3rem] text-white shadow-2xl relative overflow-hidden transition-all duration-700 bg-gradient-to-br from-indigo-600 via-blue-600 to-indigo-800 shadow-indigo-600/20`}>
        <div className="relative z-10">
          <p className="text-white/60 text-[10px] font-black uppercase tracking-[0.3em] mb-3 flex items-center gap-2">
            <TrendingUp className="w-3 h-3" />
            Total Sales
          </p>
          <h3 className="text-5xl font-black tracking-tighter mb-6">
            {formatCurrency(stats.total)}
          </h3>
          <div className="flex flex-wrap gap-2">
            <span className="bg-white/10 backdrop-blur-xl px-4 py-2 rounded-full text-[9px] font-black uppercase tracking-widest flex items-center gap-2 border border-white/10">
              <ArrowUpRight className="w-3.5 h-3.5 text-emerald-400" /> {filteredInvoices.length} Invoices
            </span>
          </div>
        </div>
        <div className="absolute -right-16 -bottom-16 w-64 h-64 bg-white/5 rounded-full blur-3xl" />
      </div>

      {/* Payment Modes Breakdown */}
      <div className="grid grid-cols-2 gap-4">
        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.2rem] border border-slate-100 dark:border-slate-800 shadow-sm">
          <div className="flex items-center gap-3 mb-3">
            <div className="p-2.5 bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 rounded-xl"><Banknote className="w-5 h-5" /></div>
            <p className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Cash Collection</p>
          </div>
          <p className="text-xl font-black text-slate-900 dark:text-white leading-none">{formatCurrency(stats.cash)}</p>
        </div>
        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.2rem] border border-slate-100 dark:border-slate-800 shadow-sm">
          <div className="flex items-center gap-3 mb-3">
            <div className="p-2.5 bg-blue-50 dark:bg-blue-900/20 text-blue-600 rounded-xl"><CreditCard className="w-5 h-5" /></div>
            <p className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Online Payment</p>
          </div>
          <p className="text-xl font-black text-slate-900 dark:text-white leading-none">{formatCurrency(stats.online)}</p>
        </div>
      </div>

      {/* Primary Metrics */}
      <div className="grid grid-cols-2 gap-4">
        <StatCard 
          icon={<Users className="w-6 h-6" />} 
          bg="bg-purple-50 dark:bg-purple-900/20" 
          label="Total Clients" 
          value={clients.length.toString()} 
          color="text-purple-600"
          onClick={() => setModalType('CLIENTS')}
        />
        <StatCard 
          icon={<Wallet className="w-6 h-6" />} 
          bg="bg-orange-50 dark:bg-orange-900/20" 
          label="Outstanding Credit" 
          value={formatCurrency(clients.reduce((acc, c) => acc + c.totalBorrowed, 0))} 
          color="text-orange-600"
          onClick={() => setModalType('BORROWERS')}
        />
      </div>

      {/* Functional Actions */}
      <div className="grid grid-cols-2 gap-3">
        <ActionButton 
          icon={<AlertCircle className="w-5 h-5" />} 
          label="Low Stock Items" 
          count={lowStockItems.length}
          color="text-red-600"
          bg="bg-red-50 dark:bg-red-900/20"
          onClick={() => setModalType('LOW_STOCK')}
        />
        <ActionButton 
          icon={<QrCode className="w-5 h-5" />} 
          label="My QR Code" 
          color="text-blue-600"
          bg="bg-blue-50 dark:bg-blue-900/20"
          onClick={() => setModalType('QR_MODAL')}
        />
      </div>

      {/* Transaction Feed */}
      <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] p-8 shadow-sm border border-slate-100 dark:border-slate-800">
        <div className="flex justify-between items-center mb-8">
          <h4 className="font-black text-slate-900 dark:text-white text-sm tracking-tighter uppercase">Recent Activity</h4>
          <button onClick={() => onNavigate(Tab.INVOICES)} className="text-[10px] font-black text-blue-600 uppercase tracking-widest bg-blue-50 dark:bg-blue-900/20 px-4 py-1.5 rounded-full transition-all active:scale-95">Archive</button>
        </div>
        <div className="space-y-6">
          {filteredInvoices.slice(-5).reverse().map(inv => (
            <div key={inv.id} className="flex justify-between items-center group cursor-pointer active:scale-[0.98] transition-all" onClick={() => onNavigate(Tab.INVOICES)}>
              <div className="flex gap-5 items-center">
                <div className="w-12 h-12 bg-slate-50 dark:bg-slate-800 rounded-2xl flex items-center justify-center text-slate-400 group-hover:bg-blue-50 group-hover:text-blue-600 transition-all shadow-sm">
                  <FileText className="w-6 h-6" />
                </div>
                <div>
                  <p className="font-black text-xs text-slate-900 dark:text-slate-100 uppercase tracking-tight">{inv.clientName}</p>
                  <p className="text-[9px] text-slate-400 font-bold uppercase mt-0.5">{new Date(inv.date).toLocaleDateString('en-IN', { day: '2-digit', month: 'short' })} • #{inv.id}</p>
                </div>
              </div>
              <div className="text-right">
                <p className="font-black text-sm text-blue-600">{formatCurrency(inv.grandTotal)}</p>
                <p className="text-[8px] text-slate-300 font-black uppercase mt-0.5 tracking-widest">{inv.paymentMethod}</p>
              </div>
            </div>
          ))}
          {filteredInvoices.length === 0 && (
            <div className="text-center py-10 opacity-20">
               <FileText className="w-12 h-12 mx-auto mb-4" />
               <p className="text-[10px] font-black uppercase tracking-widest">No Recent Sales Found</p>
            </div>
          )}
        </div>
      </div>

      {/* Dynamic Modals */}
      {modalType && (
        <div className="fixed inset-0 bg-slate-900/40 dark:bg-black/60 backdrop-blur-xl z-[100] flex items-end justify-center px-4">
          <div className="bg-white dark:bg-slate-950 w-full max-w-lg rounded-t-[3.5rem] p-10 animate-slide-up shadow-2xl border-t border-white/10">
            <div className="flex justify-between items-center mb-10">
              <h3 className="text-2xl font-black text-slate-900 dark:text-white uppercase tracking-tight">{modalType.replace('_', ' ')}</h3>
              <button onClick={() => setModalType(null)} className="p-3 bg-slate-100 dark:bg-slate-800 text-slate-500 rounded-full active:scale-90 transition-transform"><X className="w-6 h-6" /></button>
            </div>

            <div className="max-h-[50vh] overflow-y-auto space-y-4 pb-12 custom-scrollbar">
              {modalType === 'QR_MODAL' && (
                <div className="flex flex-col items-center gap-8 py-4">
                  {config.qrCodeImage ? (
                    <div className="w-64 h-64 p-3 bg-white rounded-[2.5rem] border-4 border-slate-50 shadow-2xl flex items-center justify-center">
                      <img src={config.qrCodeImage} alt="QR" className="w-full h-full object-contain" />
                    </div>
                  ) : (
                    <div className="text-center space-y-6">
                      <QrCode className="w-24 h-24 text-slate-100 dark:text-slate-800 mx-auto" />
                      <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Update QR in Settings</p>
                    </div>
                  )}
                  <div className="flex gap-4 w-full">
                    <label className="flex-1 bg-blue-600 text-white py-5 rounded-[1.8rem] font-black text-xs uppercase tracking-[0.2em] text-center cursor-pointer active:scale-95 transition-all shadow-xl shadow-blue-600/20">
                      Update Photo <input type="file" className="hidden" accept="image/*" onChange={handleQRUpload} />
                    </label>
                  </div>
                </div>
              )}
              {modalType === 'BORROWERS' && clients.filter(c => c.totalBorrowed > 0).map(c => (
                <div key={c.id} className="p-6 bg-slate-50 dark:bg-slate-900/50 rounded-3xl flex justify-between items-center border border-slate-100 dark:border-slate-800 group active:bg-slate-100 dark:active:bg-slate-800 transition-colors">
                  <div className="flex gap-4 items-center">
                    <div className="w-12 h-12 bg-white dark:bg-slate-800 rounded-2xl flex items-center justify-center shadow-sm text-orange-500"><IndianRupee className="w-6 h-6" /></div>
                    <div>
                      <p className="font-black text-slate-900 dark:text-white text-sm tracking-tight">{c.name}</p>
                      <p className="text-[10px] text-slate-400 font-bold tracking-widest uppercase mt-0.5">{c.mobile || 'No Mobile'}</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="font-black text-red-600 text-base">{formatCurrency(c.totalBorrowed)}</p>
                  </div>
                </div>
              ))}
              {modalType === 'CLIENTS' && clients.map(c => (
                <div key={c.id} className="p-6 bg-slate-50 dark:bg-slate-900/50 rounded-3xl flex justify-between items-center border border-slate-100 dark:border-slate-800">
                  <div className="flex gap-4 items-center">
                    <div className="w-12 h-12 bg-white dark:bg-slate-800 rounded-2xl flex items-center justify-center shadow-sm text-purple-600"><Users className="w-6 h-6" /></div>
                    <div>
                      <p className="font-black text-slate-900 dark:text-white text-sm tracking-tight">{c.name}</p>
                      <p className="text-[10px] text-slate-400 font-bold uppercase mt-0.5 tracking-widest">{c.mobile || 'Walk-in'}</p>
                    </div>
                  </div>
                  <ChevronRight className="w-5 h-5 text-slate-300" />
                </div>
              ))}
              {modalType === 'LOW_STOCK' && lowStockItems.map(p => (
                <div key={p.id} className="p-6 bg-red-50/50 dark:bg-red-900/10 rounded-3xl flex justify-between items-center border border-red-100 dark:border-red-900/20">
                  <div className="flex gap-4 items-center">
                    <div className="w-12 h-12 bg-white dark:bg-slate-900 rounded-2xl flex items-center justify-center shadow-sm text-red-600"><Package className="w-6 h-6" /></div>
                    <div>
                      <p className="font-black text-slate-900 dark:text-white text-sm tracking-tight">{p.name}</p>
                      <p className="text-[10px] text-red-400 font-black uppercase mt-0.5 tracking-widest">Only {p.stock} left</p>
                    </div>
                  </div>
                  <button onClick={() => onNavigate(Tab.INVENTORY)} className="bg-red-600 text-white px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest shadow-lg shadow-red-600/20">Refill</button>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

