import React, { useState } from 'react';
import { Package, Search, Plus, Edit2, Trash2, Save, X, AlertTriangle, ScanLine, Box, Briefcase } from 'lucide-react';
import { Product, AppConfig, ItemType } from '../types';
import { generateId, formatCurrency } from '../utils/helpers';
import BarcodeScanner from '../components/BarcodeScanner';

interface InventoryProps {
  products: Product[];
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  config: AppConfig;
}

const Inventory: React.FC<InventoryProps> = ({ products, setProducts, config }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [showAdd, setShowAdd] = useState(false);
  const [showScanner, setShowScanner] = useState(false);
  const [formData, setFormData] = useState<Partial<Product>>({ 
    type: ItemType.PRODUCT, 
    name: '', 
    price: 0, 
    stock: null, 
    barcode: '' 
  });

  const filteredProducts = products.filter(p => 
    p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    (p.barcode && p.barcode.includes(searchTerm))
  );

  const handleSave = () => {
    if (!formData.name || (formData.price || 0) <= 0) {
      alert("Kripya Naam aur Sahi Price likhein!");
      return;
    }

    if (editingId) {
      setProducts(prev => prev.map(p => p.id === editingId ? { ...p, ...formData } as Product : p));
      setEditingId(null);
    } else {
      setProducts(prev => [...prev, { ...formData, id: generateId() } as Product]);
      setShowAdd(false);
    }
    setFormData({ type: ItemType.PRODUCT, name: '', price: 0, stock: null, barcode: '' });
  };

  const startEdit = (product: Product) => {
    setEditingId(product.id);
    setFormData(product);
  };

  const handleBarcodeScanned = (barcode: string) => {
    setShowScanner(false);
    const existing = products.find(p => p.barcode === barcode);
    if (existing) {
      startEdit(existing);
    } else {
      setFormData({ type: ItemType.PRODUCT, name: '', price: 0, stock: null, barcode });
      setShowAdd(true);
    }
  };

  return (
    <div className="space-y-6 pb-24">
      {/* Search & Action Bar */}
      <div className="bg-white dark:bg-slate-900 p-4 rounded-[2rem] shadow-sm border border-slate-100 dark:border-slate-800 flex items-center gap-3">
        <Search className="w-5 h-5 text-slate-400" />
        <input 
          type="text"
          placeholder="Product ya Service khojein..."
          className="flex-1 bg-transparent border-none outline-none text-slate-800 dark:text-white font-bold text-sm"
          value={searchTerm}
          onChange={e => setSearchTerm(e.target.value)}
        />
        <div className="flex gap-2">
          <button 
            onClick={() => setShowScanner(true)}
            className="bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 p-2.5 rounded-xl active:scale-95 transition-all"
          >
            <ScanLine className="w-5 h-5" />
          </button>
          <button 
            onClick={() => setShowAdd(true)}
            className="bg-blue-600 text-white p-2.5 rounded-xl active:scale-95 transition-all shadow-lg shadow-blue-500/20"
          >
            <Plus className="w-5 h-5" />
          </button>
        </div>
      </div>

      {/* Scanner Modal */}
      {showScanner && (
        <BarcodeScanner 
          onScan={handleBarcodeScanned} 
          onClose={() => setShowScanner(false)} 
          title="Inventory Scanner"
        />
      )}

      {/* Add/Edit Form */}
      {(showAdd || editingId) && (
        <div className="bg-white dark:bg-slate-900 p-8 rounded-[3rem] shadow-2xl border border-blue-50 dark:border-blue-900/50 animate-in zoom-in duration-300">
          <div className="flex justify-between items-center mb-8">
            <h3 className="font-black text-slate-900 dark:text-white tracking-tight uppercase text-lg">{editingId ? 'Edit Entry' : 'Add New Entry'}</h3>
            <button onClick={() => { setShowAdd(false); setEditingId(null); }} className="p-2.5 bg-slate-100 dark:bg-slate-800 rounded-full text-slate-400"><X className="w-5 h-5" /></button>
          </div>

          {/* Type Toggle */}
          <div className="flex bg-slate-50 dark:bg-slate-800 p-1.5 rounded-2xl mb-8">
            <button 
              onClick={() => setFormData({...formData, type: ItemType.PRODUCT})}
              className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${formData.type === ItemType.PRODUCT ? 'bg-white dark:bg-slate-700 text-blue-600 shadow-sm' : 'text-slate-400'}`}
            >
              <Box className="w-3.5 h-3.5" /> Product
            </button>
            <button 
              onClick={() => setFormData({...formData, type: ItemType.SERVICE, barcode: '', stock: null})}
              className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${formData.type === ItemType.SERVICE ? 'bg-white dark:bg-slate-700 text-blue-600 shadow-sm' : 'text-slate-400'}`}
            >
              <Briefcase className="w-3.5 h-3.5" /> Service
            </button>
          </div>

          <div className="space-y-6">
            {formData.type === ItemType.PRODUCT && (
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase ml-1">Barcode / Item ID</label>
                <div className="relative mt-1">
                  <input 
                    type="text"
                    placeholder="Auto-filled via scan"
                    className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl p-4 outline-none font-bold text-slate-900 dark:text-white"
                    value={formData.barcode || ''}
                    onChange={e => setFormData({...formData, barcode: e.target.value})}
                  />
                  <button 
                    onClick={() => setShowScanner(true)}
                    className="absolute right-4 top-4 text-blue-600 active:scale-90 transition-transform"
                  >
                    <ScanLine className="w-5 h-5" />
                  </button>
                </div>
              </div>
            )}

            <div>
              <label className="text-[10px] font-black text-slate-400 uppercase ml-1">{formData.type === ItemType.PRODUCT ? 'Product Name' : 'Service Name'}</label>
              <input 
                type="text"
                className="w-full mt-1 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl p-4 outline-none font-bold text-slate-900 dark:text-white"
                value={formData.name}
                onChange={e => setFormData({...formData, name: e.target.value})}
              />
            </div>

            <div className={`grid gap-4 ${formData.type === ItemType.PRODUCT ? 'grid-cols-2' : 'grid-cols-1'}`}>
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase ml-1">Rate / Price (₹)</label>
                <input 
                  type="number"
                  className="w-full mt-1 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl p-4 outline-none font-bold text-slate-900 dark:text-white"
                  value={formData.price}
                  onChange={e => setFormData({...formData, price: parseFloat(e.target.value) || 0})}
                />
              </div>
              {formData.type === ItemType.PRODUCT && (
                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase ml-1">Available Stock</label>
                  <input 
                    type="number"
                    placeholder="∞ Unlimited"
                    className="w-full mt-1 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl p-4 outline-none font-bold text-slate-900 dark:text-white"
                    value={formData.stock === null ? '' : formData.stock}
                    onChange={e => setFormData({...formData, stock: e.target.value === '' ? null : parseInt(e.target.value)})}
                  />
                </div>
              )}
            </div>

            <button 
              onClick={handleSave}
              className="w-full bg-blue-600 text-white py-5 rounded-2xl font-black flex items-center justify-center gap-3 shadow-xl shadow-blue-500/20 active:scale-95 transition-all mt-4 uppercase tracking-[0.1em] text-sm"
            >
              <Save className="w-5 h-5" /> {editingId ? 'Update Detail' : 'Save Item'}
            </button>
          </div>
        </div>
      )}

      {/* List */}
      <div className="space-y-3">
        {filteredProducts.map(p => {
          const isLow = p.type === ItemType.PRODUCT && p.stock !== null && p.stock <= config.lowStockThreshold;
          return (
            <div key={p.id} className="bg-white dark:bg-slate-900 p-5 rounded-[2.2rem] border border-slate-100 dark:border-slate-800 flex items-center justify-between shadow-sm group">
              <div className="flex items-center gap-4">
                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center ${p.type === ItemType.SERVICE ? 'bg-purple-50 text-purple-600' : isLow ? 'bg-red-50 text-red-600' : 'bg-blue-50 text-blue-600'}`}>
                  {p.type === ItemType.SERVICE ? <Briefcase className="w-6 h-6" /> : isLow ? <AlertTriangle className="w-6 h-6" /> : <Box className="w-6 h-6" />}
                </div>
                <div>
                  <div className="flex items-center gap-2">
                    <h4 className="font-black text-slate-900 dark:text-white text-sm tracking-tight">{p.name}</h4>
                    <span className={`text-[8px] px-1.5 py-0.5 rounded-full font-black uppercase tracking-widest ${p.type === ItemType.SERVICE ? 'bg-purple-100 text-purple-700' : 'bg-blue-100 text-blue-700'}`}>
                      {p.type}
                    </span>
                  </div>
                  <div className="flex items-center gap-2 mt-1">
                    <p className="text-[10px] text-slate-400 font-bold">{formatCurrency(p.price)}</p>
                    {p.type === ItemType.PRODUCT && (
                      <>
                        <span className="text-[10px] text-slate-300">•</span>
                        <p className={`text-[10px] font-black uppercase ${isLow ? 'text-red-500' : 'text-slate-500'}`}>
                          Stock: {p.stock === null ? '∞' : p.stock}
                        </p>
                      </>
                    )}
                  </div>
                </div>
              </div>
              <div className="flex gap-1">
                <button onClick={() => startEdit(p)} className="p-3 text-slate-300 hover:text-blue-600 transition-colors">
                  <Edit2 className="w-5 h-5" />
                </button>
                <button onClick={() => { if(confirm("Delete karein?")) setProducts(prev => prev.filter(x => x.id !== p.id)); }} className="p-3 text-slate-300 hover:text-red-600 transition-colors">
                  <Trash2 className="w-5 h-5" />
                </button>
              </div>
            </div>
          );
        })}
        {filteredProducts.length === 0 && (
          <div className="text-center py-20 bg-white dark:bg-slate-900 rounded-[2.5rem] border-2 border-dashed border-slate-100 dark:border-slate-800">
             <Package className="w-16 h-16 text-slate-200 dark:text-slate-800 mx-auto mb-4" />
             <p className="text-slate-400 font-bold uppercase tracking-widest text-[10px]">Koi result nahi mila</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default Inventory;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Search, 
  Trash2, 
  Plus, 
  Minus, 
  CheckCircle2,
  X,
  CreditCard,
  Banknote,
  Clock,
  Package,
  Users,
  ScanLine,
  ChevronRight,
  ShoppingCart,
  Check,
  Briefcase,
  Box
} from 'lucide-react';
import { Product, Client, Invoice, InvoiceItem, PaymentMethod, AppConfig, ItemType } from '../types';
import { generateId, formatCurrency } from '../utils/helpers';
import InvoiceDetail from '../components/InvoiceDetail';
import BarcodeScanner from '../components/BarcodeScanner';

interface BillingProps {
  products: Product[];
  clients: Client[];
  setInvoices: React.Dispatch<React.SetStateAction<Invoice[]>>;
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  setClients: React.Dispatch<React.SetStateAction<Client[]>>;
  config: AppConfig;
}

const Billing: React.FC<BillingProps> = ({ products, clients, setInvoices, setProducts, setClients, config }) => {
  const [cart, setCart] = useState<InvoiceItem[]>([]);
  const [custName, setCustName] = useState('');
  const [custMobile, setCustMobile] = useState('');
  const [selectedClientId, setSelectedClientId] = useState<string | null>(null);

  const [discount, setDiscount] = useState(0);
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>(PaymentMethod.CASH);
  const [showCheckout, setShowCheckout] = useState(false);
  const [showQuickAdd, setShowQuickAdd] = useState(false);
  const [showScanner, setShowScanner] = useState(false);
  const [showClientList, setShowClientList] = useState(false);
  const [showProductSelector, setShowProductSelector] = useState(false);
  const [generatedInvoice, setGeneratedInvoice] = useState<Invoice | null>(null);
  const [editingQtyId, setEditingQtyId] = useState<string | null>(null);

  const [quickAddForm, setQuickAddForm] = useState({ name: '', price: '', quantity: '1' });
  const [tempSelection, setTempSelection] = useState<Record<string, number>>({});
  const [selectorSearch, setSelectorSearch] = useState('');

  const filteredSelectorProducts = useMemo(() => {
    return products.filter(p => 
      p.name.toLowerCase().includes(selectorSearch.toLowerCase()) ||
      (p.barcode && p.barcode.includes(selectorSearch))
    );
  }, [selectorSearch, products]);

  const toggleSelectorItem = (p: Product) => {
    setTempSelection(prev => {
      const next = { ...prev };
      if (next[p.id]) {
        delete next[p.id];
      } else {
        next[p.id] = 1;
      }
      return next;
    });
  };

  const handleContinueSelection = () => {
    const newItems: InvoiceItem[] = [];
    (Object.entries(tempSelection) as [string, number][]).forEach(([pid, qty]) => {
      const product = products.find(p => p.id === pid);
      if (product) {
        newItems.push({
          id: product.id,
          name: product.name,
          quantity: qty,
          price: product.price,
          total: product.price * qty,
          type: product.type
        });
      }
    });

    setCart(prev => {
      const updated = [...prev];
      newItems.forEach(newItem => {
        const existingIdx = updated.findIndex(item => item.id === newItem.id);
        if (existingIdx > -1) {
          updated[existingIdx].quantity += newItem.quantity;
          updated[existingIdx].total = updated[existingIdx].quantity * updated[existingIdx].price;
        } else {
          updated.push(newItem);
        }
      });
      return updated;
    });

    setTempSelection({});
    setSelectorSearch('');
    setShowProductSelector(false);
  };

  const addToCart = (product: Product | { name: string, price: number, quantity?: number, id?: string, type?: ItemType }) => {
    const qtyToAdd = 'quantity' in product ? (product.quantity || 1) : 1;
    const prodId = ('id' in product ? product.id : generateId()) || generateId();
    const type = 'type' in product ? product.type : ItemType.PRODUCT;

    setCart(prev => {
      const existingIdx = prev.findIndex(item => item.name === product.name);
      if (existingIdx > -1) {
        const updated = [...prev];
        updated[existingIdx].quantity += qtyToAdd;
        updated[existingIdx].total = updated[existingIdx].quantity * updated[existingIdx].price;
        return updated;
      }

      return [...prev, {
        id: prodId,
        name: product.name,
        quantity: qtyToAdd,
        price: product.price,
        total: product.price * qtyToAdd,
        type: type
      }];
    });
  };

  const handleBarcodeScanned = (barcode: string) => {
    setShowScanner(false);
    const product = products.find(p => p.barcode === barcode);
    if (product) {
      addToCart(product);
    } else {
      alert(`Product with barcode ${barcode} not found.`);
    }
  };

  const handleQuickAdd = (e: React.FormEvent) => {
    e.preventDefault();
    const price = parseFloat(quickAddForm.price);
    const quantity = parseInt(quickAddForm.quantity);

    if (!quickAddForm.name || isNaN(price)) {
      alert("Kripya sahi detail bharein!");
      return;
    }

    addToCart({
      name: quickAddForm.name,
      price: price,
      quantity: quantity || 1,
      type: ItemType.SERVICE // Quick add items default to services
    });

    setQuickAddForm({ name: '', price: '', quantity: '1' });
    setShowQuickAdd(false);
  };

  const handleQtyChange = (itemId: string, newQty: number) => {
    if (newQty < 1) return;
    setCart(prev => prev.map(item => 
      item.id === itemId ? { ...item, quantity: newQty, total: newQty * item.price } : item
    ));
  };

  const handleFinish = () => {
    if (!custName) {
      alert("Kripya Grahak ka naam likhein!");
      return;
    }
    if (cart.length === 0) {
      alert("Cart empty hai!");
      return;
    }

    const subtotalVal = cart.reduce((acc, i) => acc + i.total, 0);
    const totalVal = subtotalVal * (1 - discount/100);

    const invoice: Invoice = {
      id: `INV-${Date.now().toString().slice(-6)}`,
      date: new Date().toISOString(),
      clientId: selectedClientId || 'WALK_IN',
      clientName: custName,
      clientMobile: custMobile,
      items: [...cart],
      discount,
      subtotal: subtotalVal,
      grandTotal: totalVal,
      paymentMethod
    };

    setInvoices(prev => [...prev, invoice]);

    setProducts(prev => prev.map(p => {
      const cartItem = cart.find(item => item.id === p.id);
      // Only deduct stock for PRODUCT types, not SERVICE
      return (cartItem && p.type === ItemType.PRODUCT && p.stock !== null) ? { ...p, stock: p.stock - cartItem.quantity } : p;
    }));

    if (paymentMethod === PaymentMethod.BORROW) {
      setClients(prev => {
        const existingIdx = prev.findIndex(c => c.name === custName);
        if (existingIdx > -1) {
          const updated = [...prev];
          updated[existingIdx].totalBorrowed += invoice.grandTotal;
          return updated;
        } else {
          return [...prev, { id: generateId(), name: custName, mobile: custMobile, totalBorrowed: invoice.grandTotal }];
        }
      });
    }

    setGeneratedInvoice(invoice);
    setShowCheckout(false);
    setCart([]);
  };

  const subtotal = cart.reduce((acc, item) => acc + item.total, 0);
  const grandTotal = subtotal * (1 - discount / 100);

  if (generatedInvoice) {
    return (
      <div className="space-y-4">
        <div className="bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 p-5 rounded-[2rem] border border-emerald-100 dark:border-emerald-800 flex items-center gap-4">
          <CheckCircle2 className="w-8 h-8" />
          <div>
            <p className="font-black uppercase tracking-tight text-sm">Bill Tayyar Hai!</p>
            <p className="text-[10px] font-bold opacity-80">Invoice saved to history.</p>
          </div>
        </div>
        <InvoiceDetail invoice={generatedInvoice} config={config} />
        <button onClick={() => setGeneratedInvoice(null)} className="w-full bg-slate-900 dark:bg-blue-600 text-white py-5 rounded-2xl font-black uppercase tracking-widest active:scale-95 transition-all">Banayein Naya Bill</button>
      </div>
    );
  }

  return (
    <div className="space-y-6 pb-24 animate-in fade-in duration-500">
      {showScanner && (
        <BarcodeScanner onScan={handleBarcodeScanned} onClose={() => setShowScanner(false)} title="Billing Scanner" />
      )}

      {/* Customer Info */}
      <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] shadow-sm border border-slate-100 dark:border-slate-800 space-y-4">
        <div className="flex justify-between items-center mb-2">
          <h3 className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Grahak Details</h3>
          <button onClick={() => setShowClientList(true)} className="flex items-center gap-1.5 text-blue-600 font-black text-[10px] bg-blue-50 dark:bg-blue-900/40 px-3 py-1.5 rounded-full uppercase transition-all active:scale-95">
            <Users className="w-3.5 h-3.5" /> Directory
          </button>
        </div>
        <div className="grid grid-cols-1 gap-3">
          <input 
            type="text" placeholder="Grahak ka Naam *" 
            className="w-full p-4 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl text-slate-900 dark:text-white font-black outline-none"
            value={custName} onChange={e => setCustName(e.target.value)}
          />
          <input 
            type="tel" placeholder="Mobile No. (Optional)" 
            className="w-full p-4 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl text-slate-900 dark:text-white font-black outline-none"
            value={custMobile} onChange={e => setCustMobile(e.target.value.replace(/[^0-9]/g, ''))}
          />
        </div>
      </div>

      {/* Select Items */}
      <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] shadow-sm border border-slate-100 dark:border-slate-800 space-y-4">
        <div className="grid grid-cols-2 gap-3">
          <button 
            onClick={() => setShowProductSelector(true)}
            className="flex flex-col items-center justify-center gap-3 p-6 bg-blue-50 dark:bg-blue-900/20 rounded-[2rem] border-2 border-dashed border-blue-200 dark:border-blue-800 transition-all active:scale-95 group"
          >
            <div className="p-3 bg-blue-600 text-white rounded-2xl group-hover:rotate-12 transition-transform shadow-lg shadow-blue-500/20">
              <ShoppingCart className="w-6 h-6" />
            </div>
            <span className="text-[10px] font-black uppercase text-blue-700 dark:text-blue-400 tracking-widest">Saman Chunein</span>
          </button>

          <button 
            onClick={() => setShowScanner(true)}
            className="flex flex-col items-center justify-center gap-3 p-6 bg-slate-50 dark:bg-slate-800/50 rounded-[2rem] border-2 border-dashed border-slate-200 dark:border-slate-700 transition-all active:scale-95 group"
          >
            <div className="p-3 bg-slate-800 dark:bg-slate-700 text-white rounded-2xl group-hover:-rotate-12 transition-transform shadow-lg shadow-slate-500/20">
              <ScanLine className="w-6 h-6" />
            </div>
            <span className="text-[10px] font-black uppercase text-slate-600 dark:text-slate-400 tracking-widest">Barcode Scan</span>
          </button>
        </div>

        <button onClick={() => setShowQuickAdd(true)} className="w-full p-4 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl text-[10px] font-black uppercase text-slate-400 tracking-[0.2em] flex items-center justify-center gap-2 transition-all active:bg-slate-100">
          <Plus className="w-4 h-4" /> Alag Se Service Add Karein
        </button>
      </div>

      {/* Cart Items */}
      <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] p-6 shadow-sm border border-slate-100 dark:border-slate-800">
        <h3 className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-6">Cart Items ({cart.length})</h3>
        {cart.length === 0 ? (
          <div className="text-center py-10 opacity-30"><Package className="w-16 h-16 mx-auto mb-3" /><p className="text-[10px] font-black uppercase tracking-widest">Cart Khali Hai</p></div>
        ) : (
          <div className="space-y-6">
            {cart.map(item => (
              <div key={item.id} className="flex items-center justify-between">
                <div className="flex-1">
                  <div className="flex items-center gap-2">
                    <p className="font-black text-xs text-slate-900 dark:text-white uppercase tracking-tight">{item.name}</p>
                    <span className={`text-[7px] px-1 rounded-sm font-black uppercase ${item.type === ItemType.SERVICE ? 'bg-purple-100 text-purple-600' : 'bg-blue-100 text-blue-600'}`}>{item.type || 'ITEM'}</span>
                  </div>
                  <p className="text-[9px] text-slate-400 font-bold uppercase">{formatCurrency(item.price)}</p>
                </div>
                <div className="flex items-center gap-4">
                  <div className="flex items-center bg-slate-50 dark:bg-slate-800 rounded-xl p-1 border border-slate-100 dark:border-slate-700">
                    <button onClick={() => handleQtyChange(item.id, item.quantity - 1)} className="p-1.5 text-slate-400"><Minus className="w-4 h-4" /></button>
                    {editingQtyId === item.id ? (
                      <input 
                        type="number" autoFocus
                        className="w-12 text-center font-black text-xs bg-white dark:bg-slate-700 rounded-lg py-1 outline-none text-blue-600"
                        value={item.quantity}
                        onChange={(e) => handleQtyChange(item.id, parseInt(e.target.value) || 0)}
                        onBlur={() => setEditingQtyId(null)}
                      />
                    ) : (
                      <button onClick={() => setEditingQtyId(item.id)} className="w-12 text-center font-black text-xs text-slate-900 dark:text-white">{item.quantity}</button>
                    )}
                    <button onClick={() => handleQtyChange(item.id, item.quantity + 1)} className="p-1.5 text-slate-400"><Plus className="w-4 h-4" /></button>
                  </div>
                  <button onClick={() => setCart(prev => prev.filter(i => i.id !== item.id))} className="text-slate-200 hover:text-red-500 transition-colors"><Trash2 className="w-5 h-5" /></button>
                </div>
              </div>
            ))}
            <div className="border-t border-slate-50 dark:border-slate-800 pt-6 space-y-3">
              <div className="flex justify-between text-[10px] font-black text-slate-400 uppercase tracking-widest"><span>Subtotal</span><span>{formatCurrency(subtotal)}</span></div>
              <div className="flex justify-between items-center text-[10px] font-black text-slate-400 uppercase tracking-widest">
                <span>Discount (%)</span>
                <input type="number" className="w-14 text-right p-2 bg-slate-50 dark:bg-slate-800 rounded-lg font-black text-slate-900 dark:text-white" value={discount} onChange={e => setDiscount(Number(e.target.value) || 0)} />
              </div>
              <div className="flex justify-between text-lg font-black text-blue-600 pt-3 border-t border-blue-50 dark:border-blue-900/50"><span>Grand Total</span><span>{formatCurrency(grandTotal)}</span></div>
            </div>
            <button onClick={() => setShowCheckout(true)} className="w-full bg-blue-600 text-white py-5 rounded-2xl font-black uppercase tracking-widest shadow-xl shadow-blue-500/20 active:scale-95 transition-all">Payment Mode Chunein</button>
          </div>
        )}
      </div>

      {/* Product Selector Screen */}
      {showProductSelector && (
        <div className="fixed inset-0 bg-white dark:bg-slate-950 z-[150] flex flex-col animate-in slide-in-from-bottom-8 duration-300">
          <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center">
            <div>
              <h2 className="text-xl font-black text-slate-900 dark:text-white uppercase tracking-tight">List Chunien</h2>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{Object.keys(tempSelection).length} Items selected</p>
            </div>
            <button onClick={() => { setShowProductSelector(false); setTempSelection({}); }} className="p-3 bg-slate-100 dark:bg-slate-800 rounded-full text-slate-500 active:scale-90 transition-transform">
              <X className="w-6 h-6" />
            </button>
          </div>

          <div className="p-4">
            <div className="relative">
              <Search className="absolute left-4 top-4 w-5 h-5 text-slate-300" />
              <input 
                type="text" placeholder="Search..." 
                className="w-full pl-12 pr-4 py-4 bg-slate-50 dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-2xl text-slate-900 dark:text-white font-black outline-none"
                value={selectorSearch} onChange={e => setSelectorSearch(e.target.value)}
              />
            </div>
          </div>

          <div className="flex-1 overflow-y-auto px-4 pb-32 space-y-3 custom-scrollbar">
            {filteredSelectorProducts.map(p => {
              const isSelected = !!tempSelection[p.id];
              return (
                <div key={p.id} onClick={() => toggleSelectorItem(p)} className={`flex items-center justify-between p-5 rounded-[2rem] border-2 transition-all active:scale-[0.98] ${isSelected ? 'bg-blue-50 dark:bg-blue-900/20 border-blue-500' : 'bg-white dark:bg-slate-900 border-slate-100 dark:border-slate-800'}`}>
                  <div className="flex items-center gap-4">
                    <div className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-colors ${isSelected ? 'bg-blue-600 text-white' : 'bg-slate-50 dark:bg-slate-800 text-slate-400'}`}>
                      {p.type === ItemType.SERVICE ? <Briefcase className="w-6 h-6" /> : isSelected ? <Check className="w-6 h-6" /> : <Box className="w-6 h-6" />}
                    </div>
                    <div>
                      <p className="font-black text-sm text-slate-900 dark:text-white uppercase tracking-tight">{p.name}</p>
                      <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">
                        {formatCurrency(p.price)} {p.type === ItemType.PRODUCT && `• Stock: ${p.stock ?? '∞'}`}
                      </p>
                    </div>
                  </div>
                  {isSelected && (
                    <div className="flex items-center gap-2 bg-white dark:bg-slate-800 p-1 rounded-xl shadow-sm" onClick={e => e.stopPropagation()}>
                      <button onClick={() => setTempSelection(prev => ({...prev, [p.id]: Math.max(1, prev[p.id] - 1)}))} className="p-1.5 text-slate-400"><Minus className="w-4 h-4" /></button>
                      <span className="w-8 text-center font-black text-xs dark:text-white">{tempSelection[p.id]}</span>
                      <button onClick={() => setTempSelection(prev => ({...prev, [p.id]: prev[p.id] + 1}))} className="p-1.5 text-slate-400"><Plus className="w-4 h-4" /></button>
                    </div>
                  )}
                </div>
              );
            })}
          </div>

          <div className="fixed bottom-0 left-0 right-0 p-6 bg-white/80 dark:bg-slate-950/80 backdrop-blur-xl border-t border-slate-100 dark:border-slate-800">
            <button disabled={Object.keys(tempSelection).length === 0} onClick={handleContinueSelection} className={`w-full py-5 rounded-2xl font-black uppercase tracking-widest transition-all flex items-center justify-center gap-3 ${Object.keys(tempSelection).length > 0 ? 'bg-blue-600 text-white shadow-xl shadow-blue-500/30 active:scale-95' : 'bg-slate-200 text-slate-400'}`}>
              Cart Me Daalein <ChevronRight className="w-5 h-5" />
            </button>
          </div>
        </div>
      )}

      {/* Quick Add Modal */}
      {showQuickAdd && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-md z-[100] flex items-end justify-center">
          <div className="bg-white dark:bg-slate-950 w-full max-w-lg rounded-t-[3rem] p-8 animate-slide-up">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-black text-slate-900 dark:text-white uppercase tracking-tight">Custom Service Add</h3>
              <button onClick={() => setShowQuickAdd(false)} className="p-2 bg-slate-100 dark:bg-slate-800 text-slate-500 rounded-full"><X className="w-6 h-6" /></button>
            </div>
            <form onSubmit={handleQuickAdd} className="space-y-4">
              <input type="text" autoFocus required placeholder="Service ka Naam" className="w-full p-4 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl text-slate-900 dark:text-white font-black" value={quickAddForm.name} onChange={e => setQuickAddForm({...quickAddForm, name: e.target.value})} />
              <div className="grid grid-cols-2 gap-4">
                <input type="number" required placeholder="Price (₹)" className="w-full p-4 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl text-slate-900 dark:text-white font-black" value={quickAddForm.price} onChange={e => setQuickAddForm({...quickAddForm, price: e.target.value})} />
                <input type="number" required placeholder="Quantity" className="w-full p-4 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl text-slate-900 dark:text-white font-black" value={quickAddForm.quantity} onChange={e => setQuickAddForm({...quickAddForm, quantity: e.target.value})} />
              </div>
              <button type="submit" className="w-full bg-blue-600 text-white py-5 rounded-2xl font-black uppercase tracking-widest active:scale-95 transition-all">Add Karein</button>
            </form>
          </div>
        </div>
      )}

      {/* Checkout Modal */}
      {showCheckout && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-md z-[100] flex items-end justify-center">
          <div className="bg-white dark:bg-slate-950 w-full max-w-lg rounded-t-[3rem] p-8 animate-slide-up">
            <div className="flex justify-between items-center mb-8"><h3 className="text-xl font-black text-slate-900 dark:text-white uppercase tracking-tight">Payment Method</h3><button onClick={() => setShowCheckout(false)} className="p-2 bg-slate-100 dark:bg-slate-800 text-slate-500 rounded-full"><X className="w-6 h-6" /></button></div>
            <div className="grid grid-cols-1 gap-4 mb-8">
              <button onClick={() => setPaymentMethod(PaymentMethod.CASH)} className={`flex items-center gap-5 p-5 rounded-[1.5rem] border-2 transition-all ${paymentMethod === PaymentMethod.CASH ? 'bg-blue-50 border-blue-600' : 'bg-slate-50 dark:bg-slate-800 border-transparent'}`}>
                <div className="p-3 bg-white dark:bg-slate-700 rounded-xl shadow-sm"><Banknote className="w-6 h-6 text-emerald-500" /></div>
                <div className="text-left"><p className="font-black text-sm text-slate-900 dark:text-white">Cash (Rokda)</p></div>
              </button>
              <button onClick={() => setPaymentMethod(PaymentMethod.ONLINE)} className={`flex items-center gap-5 p-5 rounded-[1.5rem] border-2 transition-all ${paymentMethod === PaymentMethod.ONLINE ? 'bg-blue-50 border-blue-600' : 'bg-slate-50 dark:bg-slate-800 border-transparent'}`}>
                <div className="p-3 bg-white dark:bg-slate-700 rounded-xl shadow-sm"><CreditCard className="w-6 h-6 text-blue-500" /></div>
                <div className="text-left"><p className="font-black text-sm text-slate-900 dark:text-white">Online Payment</p></div>
              </button>
              <button onClick={() => setPaymentMethod(PaymentMethod.BORROW)} className={`flex items-center gap-5 p-5 rounded-[1.5rem] border-2 transition-all ${paymentMethod === PaymentMethod.BORROW ? 'bg-blue-50 border-blue-600' : 'bg-slate-50 dark:bg-slate-800 border-transparent'}`}>
                <div className="p-3 bg-white dark:bg-slate-700 rounded-xl shadow-sm"><Clock className="w-6 h-6 text-orange-500" /></div>
                <div className="text-left"><p className="font-black text-sm text-slate-900 dark:text-white">Udhaar (Khata)</p></div>
              </button>
            </div>
            <button onClick={handleFinish} className="w-full bg-blue-600 text-white py-5 rounded-2xl font-black uppercase tracking-[0.2em] shadow-xl shadow-blue-500/20 active:scale-95 transition-all">Bill Banayein</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default Billing;

import React, { useState, useMemo } from 'react';
import { 
  Plus, 
  Minus, 
  CheckCircle2,
  X,
  CreditCard,
  Banknote,
  Clock,
  Package,
  Users,
  ScanLine,
  ShoppingCart,
  Briefcase,
  Box,
  Trash2,
  Search,
  Save
} from 'lucide-react';
import { Product, Client, Invoice, InvoiceItem, PaymentMethod, AppConfig, ItemType } from '../types';
import { generateId, formatCurrency } from '../utils/helpers';
import InvoiceDetail from '../components/InvoiceDetail';
import BarcodeScanner from '../components/BarcodeScanner';

interface BillingProps {
  products: Product[];
  clients: Client[];
  setInvoices: React.Dispatch<React.SetStateAction<Invoice[]>>;
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  setClients: React.Dispatch<React.SetStateAction<Client[]>>;
  config: AppConfig;
}

const Billing: React.FC<BillingProps> = ({ products, clients, setInvoices, setProducts, setClients, config }) => {
  const [cart, setCart] = useState<InvoiceItem[]>([]);
  const [custName, setCustName] = useState('');
  const [custMobile, setCustMobile] = useState('');
  const [selectedClientId, setSelectedClientId] = useState<string | null>(null);

  const [discount, setDiscount] = useState(0);
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>(PaymentMethod.CASH);
  const [showCheckout, setShowCheckout] = useState(false);
  const [showScanner, setShowScanner] = useState(false);
  const [showClientList, setShowClientList] = useState(false);
  const [generatedInvoice, setGeneratedInvoice] = useState<Invoice | null>(null);

  // New Form states for Product/Service
  const [activeForm, setActiveForm] = useState<ItemType | null>(null);
  const [formData, setFormData] = useState({
    name: '',
    price: '',
    quantity: '1',
    barcode: '',
    id: ''
  });
  const [searchQuery, setSearchQuery] = useState('');

  const filteredInventory = useMemo(() => {
    if (!searchQuery) return [];
    return products.filter(p => 
      p.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
      (p.barcode && p.barcode.includes(searchQuery))
    );
  }, [searchQuery, products]);

  const handleSelectFromInventory = (p: Product) => {
    setFormData({
      ...formData,
      name: p.name,
      price: p.price.toString(),
      barcode: p.barcode || '',
      id: p.id
    });
    setSearchQuery('');
  };

  const handleAddToCart = () => {
    if (!formData.name || !formData.price) {
      alert("Sahi details bharein!");
      return;
    }

    const priceNum = parseFloat(formData.price);
    const qtyNum = parseInt(formData.quantity);

    const newItem: InvoiceItem = {
      id: formData.id || generateId(),
      name: formData.name,
      price: priceNum,
      quantity: qtyNum,
      total: priceNum * qtyNum,
      type: activeForm || ItemType.PRODUCT
    };

    setCart(prev => [...prev, newItem]);
    setActiveForm(null);
    setFormData({ name: '', price: '', quantity: '1', barcode: '', id: '' });
  };

  const handleBarcodeScanned = (barcode: string) => {
    setShowScanner(false);
    const product = products.find(p => p.barcode === barcode);
    if (product) {
      setFormData({
        name: product.name,
        price: product.price.toString(),
        quantity: '1',
        barcode: product.barcode || '',
        id: product.id
      });
      setActiveForm(ItemType.PRODUCT);
    } else {
      alert(`Barcode ${barcode} wala product nahi mila.`);
    }
  };

  const handleFinish = () => {
    if (!custName) {
      alert("Grahak ka naam likhein!");
      return;
    }
    if (cart.length === 0) {
      alert("Cart khali hai!");
      return;
    }

    const subtotalVal = cart.reduce((acc, i) => acc + i.total, 0);
    const totalVal = subtotalVal * (1 - discount/100);

    const invoice: Invoice = {
      id: `INV-${Date.now().toString().slice(-6)}`,
      date: new Date().toISOString(),
      clientId: selectedClientId || 'WALK_IN',
      clientName: custName,
      clientMobile: custMobile,
      items: [...cart],
      discount,
      subtotal: subtotalVal,
      grandTotal: totalVal,
      paymentMethod
    };

    setInvoices(prev => [...prev, invoice]);

    // Deduct stock for products
    setProducts(prev => prev.map(p => {
      const cartItem = cart.find(item => item.id === p.id && item.type === ItemType.PRODUCT);
      return (cartItem && p.stock !== null) ? { ...p, stock: p.stock - cartItem.quantity } : p;
    }));

    if (paymentMethod === PaymentMethod.BORROW) {
      setClients(prev => {
        const existingIdx = prev.findIndex(c => c.name === custName);
        if (existingIdx > -1) {
          const updated = [...prev];
          updated[existingIdx].totalBorrowed += invoice.grandTotal;
          return updated;
        } else {
          return [...prev, { id: generateId(), name: custName, mobile: custMobile, totalBorrowed: invoice.grandTotal }];
        }
      });
    }

    setGeneratedInvoice(invoice);
    setShowCheckout(false);
    setCart([]);
    setCustName('');
    setCustMobile('');
  };

  const subtotal = cart.reduce((acc, item) => acc + item.total, 0);
  const grandTotal = subtotal * (1 - discount / 100);

  if (generatedInvoice) {
    return (
      <div className="space-y-4">
        <div className="bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 p-5 rounded-[2rem] border border-emerald-100 dark:border-emerald-800 flex items-center gap-4">
          <CheckCircle2 className="w-8 h-8" />
          <div>
            <p className="font-black uppercase tracking-tight text-sm">Bill Ban Gaya!</p>
            <p className="text-[10px] font-bold opacity-80">Invoice successfully generated.</p>
          </div>
        </div>
        <InvoiceDetail invoice={generatedInvoice} config={config} />
        <button onClick={() => setGeneratedInvoice(null)} className="w-full bg-slate-900 dark:bg-blue-600 text-white py-5 rounded-2xl font-black uppercase tracking-widest active:scale-95 transition-all">Naya Bill Banayein</button>
      </div>
    );
  }

  return (
    <div className="space-y-6 pb-24 animate-in fade-in duration-500">
      {showScanner && (
        <BarcodeScanner onScan={handleBarcodeScanned} onClose={() => setShowScanner(false)} title="Billing Scanner" />
      )}

      {/* Header Info */}
      <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] shadow-sm border border-slate-100 dark:border-slate-800 space-y-4">
        <div className="flex justify-between items-center">
          <h3 className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Customer Information</h3>
          <button onClick={() => setShowClientList(true)} className="flex items-center gap-1.5 text-blue-600 font-black text-[10px] bg-blue-50 dark:bg-blue-900/40 px-3 py-1.5 rounded-full transition-all active:scale-95">
            <Users className="w-3.5 h-3.5" /> Client List
          </button>
        </div>
        <div className="grid grid-cols-1 gap-3">
          <input 
            type="text" placeholder="Grahak ka Naam (Required) *" 
            className="w-full p-4 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl text-slate-900 dark:text-white font-black outline-none focus:ring-2 focus:ring-blue-500"
            value={custName} onChange={e => setCustName(e.target.value)}
          />
          <input 
            type="tel" placeholder="Mobile Number (Optional)" 
            className="w-full p-4 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl text-slate-900 dark:text-white font-black outline-none focus:ring-2 focus:ring-blue-500"
            value={custMobile} onChange={e => setCustMobile(e.target.value.replace(/[^0-9]/g, ''))}
          />
        </div>
      </div>

      {/* Action Buttons */}
      <div className="grid grid-cols-2 gap-4">
        <button 
          onClick={() => { setActiveForm(ItemType.PRODUCT); setFormData({name: '', price: '', quantity: '1', barcode: '', id: ''}); }}
          className="flex flex-col items-center justify-center gap-3 p-8 bg-blue-600 text-white rounded-[2.5rem] shadow-xl shadow-blue-500/20 active:scale-95 transition-all group"
        >
          <div className="p-3 bg-white/20 rounded-2xl group-hover:scale-110 transition-transform">
            <Box className="w-8 h-8" />
          </div>
          <span className="text-xs font-black uppercase tracking-widest">+ Product</span>
        </button>

        <button 
          onClick={() => { setActiveForm(ItemType.SERVICE); setFormData({name: '', price: '', quantity: '1', barcode: '', id: ''}); }}
          className="flex flex-col items-center justify-center gap-3 p-8 bg-slate-900 text-white rounded-[2.5rem] shadow-xl shadow-slate-900/20 active:scale-95 transition-all group"
        >
          <div className="p-3 bg-white/10 rounded-2xl group-hover:scale-110 transition-transform">
            <Briefcase className="w-8 h-8" />
          </div>
          <span className="text-xs font-black uppercase tracking-widest">+ Service</span>
        </button>
      </div>

      {/* Cart Display */}
      <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] p-6 shadow-sm border border-slate-100 dark:border-slate-800">
        <div className="flex justify-between items-center mb-6">
          <h3 className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Shopping Cart</h3>
          <button onClick={() => setShowScanner(true)} className="p-3 bg-blue-50 dark:bg-blue-900/40 text-blue-600 rounded-2xl active:scale-90 transition-all">
            <ScanLine className="w-5 h-5" />
          </button>
        </div>

        {cart.length === 0 ? (
          <div className="text-center py-12 opacity-30">
            <ShoppingCart className="w-16 h-16 mx-auto mb-3" />
            <p className="text-[10px] font-black uppercase tracking-widest">Cart is empty</p>
          </div>
        ) : (
          <div className="space-y-6">
            {cart.map((item, idx) => (
              <div key={idx} className="flex items-center justify-between group">
                <div className="flex-1">
                  <div className="flex items-center gap-2">
                    <span className={`w-2 h-2 rounded-full ${item.type === ItemType.SERVICE ? 'bg-purple-500' : 'bg-blue-500'}`} />
                    <p className="font-black text-xs text-slate-900 dark:text-white uppercase tracking-tight">{item.name}</p>
                  </div>
                  <p className="text-[9px] text-slate-400 font-bold uppercase mt-1">
                    {formatCurrency(item.price)} × {item.quantity} = {formatCurrency(item.total)}
                  </p>
                </div>
                <button onClick={() => setCart(prev => prev.filter((_, i) => i !== idx))} className="p-2 text-slate-200 hover:text-red-500 transition-colors">
                  <Trash2 className="w-5 h-5" />
                </button>
              </div>
            ))}

            <div className="pt-6 border-t border-slate-50 dark:border-slate-800 space-y-3">
              <div className="flex justify-between text-[10px] font-black text-slate-400 uppercase tracking-widest">
                <span>Subtotal</span>
                <span>{formatCurrency(subtotal)}</span>
              </div>
              <div className="flex justify-between items-center text-[10px] font-black text-slate-400 uppercase tracking-widest">
