              </div>
              <button onClick={() => setActiveForm(null)} className="p-3 bg-slate-100 dark:bg-slate-800 rounded-full text-slate-500 active:scale-90"><X className="w-6 h-6" /></button>
            </div>

            <div className="space-y-6">
              {activeForm === ItemType.PRODUCT && (
                <div className="relative">
                  <div className="absolute left-4 top-4.5 text-slate-300"><Search className="w-5 h-5" /></div>
