                    type="text" placeholder="Inventory se khojein..." 
                    className="w-full pl-12 pr-4 py-4.5 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl text-slate-900 dark:text-white font-black outline-none focus:ring-2 focus:ring-blue-500"
                    value={searchQuery} onChange={e => setSearchQuery(e.target.value)}
                  />
                  {searchQuery && filteredInventory.length > 0 && (
                    <div className="absolute top-16 left-0 right-0 bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-3xl shadow-2xl z-20 max-h-60 overflow-y-auto custom-scrollbar p-2">
                      {filteredInventory.map(p => (
                        <button 
                          key={p.id} 
                          onClick={() => handleSelectFromInventory(p)}
                          className="w-full text-left px-5 py-4 hover:bg-blue-50 dark:hover:bg-blue-900/40 rounded-2xl border-b border-slate-50 dark:border-slate-800 last:border-0 transition-colors"
                        >
                          <p className="font-black text-xs text-slate-900 dark:text-white uppercase tracking-tight">{p.name}</p>
                          <p className="text-[10px] text-slate-400 font-bold mt-1">{formatCurrency(p.price)} • Stock: {p.stock ?? '∞'}</p>
                        </button>
                      ))}
                    </div>
                  )}
                </div>
              )}

              <div className="space-y-6">
                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">{activeForm} Name</label>
                  <input 
                    type="text" 
                    className="w-full mt-2 p-4.5 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl text-slate-900 dark:text-white font-black outline-none focus:ring-2 focus:ring-blue-500" 
                    value={formData.name} 
                    onChange={e => setFormData({...formData, name: e.target.value})} 
                  />
                </div>
                <div className="grid grid-cols-2 gap-5">
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Price (₹)</label>
                    <input 
                      type="number" 
                      className="w-full mt-2 p-4.5 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl text-slate-900 dark:text-white font-black outline-none focus:ring-2 focus:ring-blue-500" 
                      value={formData.price} 
                      onChange={e => setFormData({...formData, price: e.target.value})} 
                    />
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Quantity</label>
                    <input 
                      type="number" 
                      className="w-full mt-2 p-4.5 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl text-slate-900 dark:text-white font-black outline-none focus:ring-2 focus:ring-blue-500" 
                      value={formData.quantity} 
                      onChange={e => setFormData({...formData, quantity: e.target.value})} 
                    />
                  </div>
                </div>
              </div>

              <button 
                onClick={handleAddToCart}
                className={`w-full py-5 rounded-[2rem] font-black uppercase tracking-[0.2em] shadow-2xl active:scale-95 transition-all mt-6 ${activeForm === ItemType.PRODUCT ? 'bg-blue-600 shadow-blue-500/30' : 'bg-slate-900 shadow-slate-900/30'} text-white`}
              >
                Cart Mein Dalein
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Payment Confirmation Modal */}
      {showCheckout && (
        <div className="fixed inset-0 bg-slate-950/40 backdrop-blur-md z-[120] flex items-end justify-center px-4">
          <div className="bg-white dark:bg-slate-950 w-full max-w-lg rounded-t-[3.5rem] p-10 animate-slide-up shadow-2xl">
            <div className="flex justify-between items-center mb-10">
              <h3 className="text-2xl font-black text-slate-900 dark:text-white uppercase tracking-tight">Select Payment</h3>
              <button onClick={() => setShowCheckout(false)} className="p-3 bg-slate-100 dark:bg-slate-800 text-slate-500 rounded-full active:scale-90"><X className="w-6 h-6" /></button>
            </div>

            <div className="space-y-4 mb-10">
              <PaymentButton active={paymentMethod === PaymentMethod.CASH} onClick={() => setPaymentMethod(PaymentMethod.CASH)} icon={<Banknote />} label="Cash Payment" desc="Payment received in cash" />
              <PaymentButton active={paymentMethod === PaymentMethod.ONLINE} onClick={() => setPaymentMethod(PaymentMethod.ONLINE)} icon={<CreditCard />} label="Online / UPI" desc="Payment via QR or Bank" />
              <PaymentButton active={paymentMethod === PaymentMethod.BORROW} onClick={() => setPaymentMethod(PaymentMethod.BORROW)} icon={<Clock />} label="Udhaar / Khata" desc="Add to client's pending balance" />
            </div>

            <button 
              onClick={handleFinish}
              className="w-full bg-blue-600 text-white py-6 rounded-[2.5rem] font-black uppercase tracking-[0.3em] shadow-2xl shadow-blue-600/30 active:scale-95 transition-all"
            >
              Generate Invoice
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

const PaymentButton = ({ active, onClick, icon, label, desc }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-5 p-6 rounded-[2rem] border-2 transition-all ${active ? 'bg-blue-50 dark:bg-blue-900/20 border-blue-600 shadow-lg shadow-blue-600/10' : 'bg-slate-50 dark:bg-slate-800/50 border-transparent opacity-60'}`}>
    <div className={`p-4 rounded-2xl ${active ? 'bg-blue-600 text-white' : 'bg-white dark:bg-slate-700 text-slate-400'}`}>
      {React.cloneElement(icon, { className: 'w-7 h-7' })}
    </div>
    <div className="text-left">
      <p className={`font-black text-sm ${active ? 'text-blue-700 dark:text-blue-400' : 'text-slate-900 dark:text-white'}`}>{label}</p>
      <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tight mt-1">{desc}</p>
    </div>
  </button>
);

export default Billing;

import React, { useRef, useMemo } from 'react';
import { Printer, Download, Share2 } from 'lucide-react';
import { Invoice, AppConfig, PaymentMethod, ItemType } from '../types';
import { formatCurrency, numberToWords } from '../utils/helpers';

interface InvoiceDetailProps {
  invoice: Invoice;
  config: AppConfig;
}

const InvoiceDetail: React.FC<InvoiceDetailProps> = ({ invoice, config }) => {
  const invoiceRef = useRef<HTMLDivElement>(null);

  const invoiceType = useMemo(() => {
    const hasProduct = invoice.items.some(i => i.type === ItemType.PRODUCT);
    const hasService = invoice.items.some(i => i.type === ItemType.SERVICE);
    if (hasProduct && hasService) return "Mixed Invoice";
    if (hasProduct) return "Product Invoice";
    if (hasService) return "Service Invoice";
    return "Tax Invoice";
  }, [invoice.items]);

  const handlePrint = () => {
    window.print();
  };

  const handleDownload = async () => {
    if (!invoiceRef.current) return;
    const { jsPDF } = (window as any).jspdf;

    const element = invoiceRef.current;

    try {
      const canvas = await (window as any).html2canvas(element, {
        scale: 3,
        useCORS: true,
        backgroundColor: '#ffffff',
        logging: false,
      });
      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF('p', 'mm', 'a4');
      const imgProps = pdf.getImageProperties(imgData);
      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = (imgProps.height * pdfWidth) / imgProps.width;

      pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
      const fileName = `Bill_${invoice.id}_${invoice.clientName.replace(/[^a-z0-9]/gi, '_').toLowerCase()}.pdf`;
      pdf.save(fileName);
    } catch (err) {
      console.error("PDF Export failed", err);
      alert("Failed to generate PDF. Please try printing instead.");
    }
  };

  const handleShare = async () => {
    if (!invoice.clientMobile) {
      alert("Grahak ka mobile number nahi hai!");
      return;
    }
    const message = `Namaste! ${config.shopName} se aapka bill.\nBill No: ${invoice.id}\nAmount: ${formatCurrency(invoice.grandTotal)}\nDhanyawad!`;
    const url = `https://wa.me/91${invoice.clientMobile}?text=${encodeURIComponent(message)}`;
    window.open(url, '_blank');
  };

  const formattedDate = new Date(invoice.date).toLocaleDateString('en-GB', {
    day: '2-digit',
    month: 'short',
    year: 'numeric'
  });

  return (
    <div className="space-y-4">
      <div className="bg-white dark:bg-slate-900 p-3 rounded-[1.5rem] flex justify-around no-print shadow-sm border border-slate-100 dark:border-slate-800">
        <button onClick={handlePrint} className="flex flex-col items-center gap-1.5 text-blue-600 font-bold text-[10px] p-2 active:scale-95 transition-all">
          <div className="p-2.5 bg-blue-50 dark:bg-blue-900/30 rounded-xl"><Printer className="w-5 h-5" /></div> Print
        </button>
        <button onClick={handleDownload} className="flex flex-col items-center gap-1.5 text-blue-600 font-bold text-[10px] p-2 active:scale-95 transition-all">
          <div className="p-2.5 bg-blue-50 dark:bg-blue-900/30 rounded-xl"><Download className="w-5 h-5" /></div> PDF
        </button>
        <button onClick={handleShare} className="flex flex-col items-center gap-1.5 text-green-600 font-bold text-[10px] p-2 active:scale-95 transition-all">
          <div className="p-2.5 bg-green-50 dark:bg-green-900/30 rounded-xl"><Share2 className="w-5 h-5" /></div> WhatsApp
        </button>
      </div>

      {/* Main Invoice Container */}
      <div 
        ref={invoiceRef}
        className="bg-white p-0 relative overflow-hidden min-h-[1000px] flex flex-col print:shadow-none print:border-none shadow-xl border border-slate-50"
        style={{ width: '100%', maxWidth: '800px', margin: '0 auto', fontFamily: 'Inter, sans-serif' }}
      >
        {/* Diagonal Watermark */}
        <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-[0.05] z-0 select-none">
          <span className="text-[120px] font-black uppercase -rotate-45 text-slate-900 tracking-tighter">
            Billmax
          </span>
        </div>

        {/* Header Section */}
        <div className="relative z-10 p-10 flex justify-between items-start border-b border-slate-50">
          <div className="flex gap-6 items-center">
            {config.businessLogo && (
              <div className="w-28 h-28 bg-black flex items-center justify-center p-2 rounded-2xl shrink-0 shadow-xl">
                <img src={config.businessLogo} alt="Logo" className="max-w-full max-h-full object-contain" />
              </div>
            )}
            <div className="space-y-0.5">
              <h1 className="text-2xl font-black text-slate-900 tracking-tight">{config.shopName}</h1>
              <p className="text-xs font-bold text-slate-500 uppercase tracking-widest">Mobile +91 {config.shopMobile}</p>
            </div>
          </div>
          <div className="text-right">
            <h2 className="text-xl font-black text-blue-700 tracking-widest">{invoiceType.toUpperCase()}</h2>
            <p className="text-[9px] font-bold text-slate-400 uppercase tracking-[0.3em] mt-2">ORIGINAL FOR RECIPIENT</p>
