    </div>
    <div className="text-left">
      <p className={`font-black text-sm ${active ? 'text-blue-700 dark:text-blue-400' : 'text-slate-900 dark:text-white'}`}>{label}</p>
      <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tight mt-1">{desc}</p>
    </div>
  </button>
);

export default Billing;

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Receipt, 
  Package, 
  History, 
  Settings as SettingsIcon,
  Lock,
  PlusCircle,
  Moon,
  Sun
} from 'lucide-react';
import { AppConfig, Tab, Product, Client, Invoice } from './types';
import Dashboard from './views/Dashboard';
import Billing from './views/Billing';
import Inventory from './views/Inventory';
import Invoices from './views/Invoices';
import Settings from './views/Settings';
import Setup from './components/Setup';
import PinLock from './components/PinLock';

const App: React.FC = () => {
  const [config, setConfig] = useState<AppConfig | null>(null);
  const [isLocked, setIsLocked] = useState(true);
  const [activeTab, setActiveTab] = useState<Tab>(Tab.DASHBOARD);

  // Data State
  const [products, setProducts] = useState<Product[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [invoices, setInvoices] = useState<Invoice[]>([]);

  // Load Initial Data
  useEffect(() => {
    const savedConfig = localStorage.getItem('app_config');
    const savedProducts = localStorage.getItem('products');
    const savedClients = localStorage.getItem('clients');
    const savedInvoices = localStorage.getItem('invoices');

    if (savedConfig) {
      const parsedConfig = JSON.parse(savedConfig);
      setConfig(parsedConfig);
      if (parsedConfig.isDarkMode) {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
    }
    if (savedProducts) setProducts(JSON.parse(savedProducts));
    if (savedClients) setClients(JSON.parse(savedClients));
    if (savedInvoices) setInvoices(JSON.parse(savedInvoices));
  }, []);

  // Sync Data
  useEffect(() => {
    if (config) {
      localStorage.setItem('app_config', JSON.stringify(config));
      if (config.isDarkMode) {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
    }
  }, [config]);

  useEffect(() => {
    localStorage.setItem('products', JSON.stringify(products));
  }, [products]);

  useEffect(() => {
    localStorage.setItem('clients', JSON.stringify(clients));
  }, [clients]);

  useEffect(() => {
    localStorage.setItem('invoices', JSON.stringify(invoices));
  }, [invoices]);

  const handleSetupComplete = (newConfig: AppConfig) => {
    setConfig(newConfig);
    setIsLocked(false);
  };

  const handleUnlock = () => {
    setIsLocked(false);
  };

  if (!config || !config.setupComplete) {
    return <Setup onComplete={handleSetupComplete} />;
  }

  if (isLocked) {
    return <PinLock correctPin={config.pin} onUnlock={handleUnlock} shopName={config.shopName} />;
  }

  const renderView = () => {
    switch (activeTab) {
      case Tab.DASHBOARD:
        return (
          <Dashboard 
            invoices={invoices} 
            clients={clients} 
            products={products} 
            config={config} 
            onNavigate={setActiveTab}
            setConfig={setConfig}
          />
        );
      case Tab.BILLING:
        return (
          <Billing 
            products={products} 
            clients={clients} 
            setInvoices={setInvoices}
            setProducts={setProducts}
            setClients={setClients}
            config={config}
          />
        );
      case Tab.INVENTORY:
        return (
          <Inventory 
            products={products} 
            setProducts={setProducts} 
            config={config}
          />
        );
      case Tab.INVOICES:
        return (
          <Invoices 
            invoices={invoices} 
            config={config}
          />
        );
      case Tab.SETTINGS:
        return (
          <Settings 
            config={config} 
            setConfig={setConfig} 
          />
        );
      default:
        return null;
    }
  };

  return (
    <div className={`min-h-screen pb-24 flex flex-col transition-colors duration-300 ${config.isDarkMode ? 'bg-slate-950' : 'bg-slate-50'}`}>
      {/* Header - No Gradient */}
      <header className={`sticky top-0 z-40 border-b p-4 bg-blue-700 border-blue-800 text-white`}>
        <div className="flex justify-between items-center max-w-lg mx-auto w-full px-2">
          <div className="flex items-center gap-3">
            <div>
              <h1 className="text-lg font-black tracking-tight">{config.shopName}</h1>
              <p className="text-blue-200 text-[10px] font-black uppercase tracking-widest">{config.ownerName}</p>
            </div>
          </div>
          <div className="flex gap-3">
            <button 
              onClick={() => setConfig({ ...config, isDarkMode: !config.isDarkMode })}
              className="p-2.5 bg-white/10 rounded-2xl hover:bg-white/20 transition-all active:scale-90"
            >
              {config.isDarkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
            </button>
            <button 
              onClick={() => setIsLocked(true)}
              className="p-2.5 bg-white/10 rounded-2xl hover:bg-white/20 transition-all active:scale-90"
            >
              <Lock className="w-5 h-5" />
            </button>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 max-w-lg mx-auto w-full px-4 pt-4">
        {renderView()}
      </main>

      {/* FAB for Billing - No Glow */}
      {(activeTab === Tab.DASHBOARD || activeTab === Tab.INVENTORY || activeTab === Tab.INVOICES) && (
        <button 
          onClick={() => setActiveTab(Tab.BILLING)}
          className={`fixed bottom-24 right-6 w-16 h-16 rounded-[1.5rem] shadow-lg flex items-center justify-center transition-all active:scale-95 z-50 border-4 bg-blue-600 border-white text-white`}
        >
          <PlusCircle className="w-9 h-9" />
        </button>
      )}

      {/* Bottom Navigation */}
      <nav className="fixed bottom-0 left-0 right-0 bg-white dark:bg-slate-900 border-t border-slate-200 dark:border-slate-800 px-2 py-1 safe-bottom z-40 shadow-xl">
        <div className="max-w-lg mx-auto flex justify-between items-center h-16">
          <NavItem 
            active={activeTab === Tab.DASHBOARD} 
            onClick={() => setActiveTab(Tab.DASHBOARD)} 
            icon={<LayoutDashboard className="w-6 h-6" />} 
            label="Home" 
          />
          <NavItem 
            active={activeTab === Tab.BILLING} 
            onClick={() => setActiveTab(Tab.BILLING)} 
            icon={<Receipt className="w-6 h-6" />} 
            label="Bill" 
          />
          <NavItem 
            active={activeTab === Tab.INVENTORY} 
            onClick={() => setActiveTab(Tab.INVENTORY)} 
            icon={<Package className="w-6 h-6" />} 
            label="Stock" 
          />
          <NavItem 
            active={activeTab === Tab.INVOICES} 
            onClick={() => setActiveTab(Tab.INVOICES)} 
            icon={<History className="w-6 h-6" />} 
            label="History" 
          />
          <NavItem 
            active={activeTab === Tab.SETTINGS} 
            onClick={() => setActiveTab(Tab.SETTINGS)} 
            icon={<SettingsIcon className="w-6 h-6" />} 
            label="Profile" 
          />
        </div>
      </nav>
    </div>
  );
};

const NavItem: React.FC<{ active: boolean, onClick: () => void, icon: React.ReactNode, label: string }> = ({ active, onClick, icon, label }) => (
  <button 
    onClick={onClick}
    className={`flex flex-col items-center justify-center flex-1 transition-all ${
      active 
        ? 'text-blue-600' 
        : 'text-slate-400 dark:text-slate-600'
    }`}
  >
    <div className={`p-2 rounded-2xl transition-all ${
      active 
        ? 'bg-blue-50 dark:bg-blue-900/40' 
        : ''
    }`}>
      {icon}
    </div>
    <span className={`text-[9px] mt-1 font-black uppercase tracking-widest ${active ? 'opacity-100' : 'opacity-60'}`}>{label}</span>
  </button>
);

export default App;

import React, { useState, useMemo } from 'react';
import { 
  Users, 
  Wallet, 
  TrendingUp, 
  ArrowUpRight, 
  Package, 
  ChevronRight,
  X,
  AlertCircle,
  QrCode,
  FileText,
  IndianRupee,
  Calendar,
  CreditCard,
  Banknote,
  ChevronDown,
  Filter
} from 'lucide-react';
import { Invoice, Client, Product, AppConfig, Tab, PaymentMethod } from '../types';
import { formatCurrency, fileToBase64 } from '../utils/helpers';

interface DashboardProps {
  invoices: Invoice[];
  clients: Client[];
  products: Product[];
  config: AppConfig;
  onNavigate: (tab: Tab) => void;
  setConfig?: (config: AppConfig) => void;
}

type DateFilterType = 'TODAY' | 'TOMORROW' | 'YEAR' | 'ALL' | 'RANGE';

const Dashboard: React.FC<DashboardProps> = ({ invoices, clients, products, config, onNavigate, setConfig }) => {
  const [modalType, setModalType] = useState<'BORROWERS' | 'LOW_STOCK' | 'CLIENTS' | 'QR_MODAL' | null>(null);
  const [dateFilter, setDateFilter] = useState<DateFilterType>('TODAY');
  const [startDate, setStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [endDate, setEndDate] = useState(new Date().toISOString().split('T')[0]);
  const [showFilters, setShowFilters] = useState(false);

  const filteredInvoices = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    const tomorrowDate = new Date();
    tomorrowDate.setDate(tomorrowDate.getDate() + 1);
    const tomorrow = tomorrowDate.toISOString().split('T')[0];
    const currentYear = new Date().getFullYear().toString();

    return invoices.filter(inv => {
      const invDate = inv.date.split('T')[0];
      if (dateFilter === 'TODAY') return invDate === today;
      if (dateFilter === 'TOMORROW') return invDate === tomorrow;
      if (dateFilter === 'YEAR') return inv.date.startsWith(currentYear);
      if (dateFilter === 'ALL') return true;
      if (dateFilter === 'RANGE') return invDate >= startDate && invDate <= endDate;
      return false;
    });
  }, [invoices, dateFilter, startDate, endDate]);

  const stats = useMemo(() => {
    const total = filteredInvoices.reduce((acc, inv) => acc + inv.grandTotal, 0);
    const cash = filteredInvoices
      .filter(inv => inv.paymentMethod === PaymentMethod.CASH)
      .reduce((acc, inv) => acc + inv.grandTotal, 0);
    const online = filteredInvoices
      .filter(inv => inv.paymentMethod === PaymentMethod.ONLINE)
      .reduce((acc, inv) => acc + inv.grandTotal, 0);
    return { total, cash, online };
  }, [filteredInvoices]);

  const lowStockItems = products.filter(p => p.stock !== null && p.stock <= config.lowStockThreshold);

  const filterLabel = useMemo(() => {
    if (dateFilter === 'TODAY') return 'Today';
    if (dateFilter === 'TOMORROW') return 'Tomorrow';
    if (dateFilter === 'YEAR') return 'This Year';
    if (dateFilter === 'ALL') return 'All Time';
    return `${startDate} to ${endDate}`;
  }, [dateFilter, startDate, endDate]);

  const handleQRUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0] && setConfig) {
      const base64 = await fileToBase64(e.target.files[0]);
      const newConfig = { ...config, qrCodeImage: base64 };
      setConfig(newConfig);
      localStorage.setItem('app_config', JSON.stringify(newConfig));
    }
  };

  return (
    <div className="space-y-6 pb-20 animate-in fade-in duration-500">
      {/* Date Filter Bar */}
      <div className="flex justify-between items-center relative gap-3">
        <div className="relative flex-1">
          <button 
            onClick={() => setShowFilters(!showFilters)}
            className="w-full flex items-center justify-between bg-white dark:bg-slate-900 px-5 py-3 rounded-[1.2rem] shadow-sm border border-slate-100 dark:border-slate-800 text-[10px] font-black uppercase tracking-widest text-blue-600 active:scale-95 transition-all"
          >
            <div className="flex items-center gap-2">
              <Calendar className="w-4 h-4" />
              <span>{filterLabel} Sales</span>
            </div>
            <ChevronDown className={`w-4 h-4 transition-transform ${showFilters ? 'rotate-180' : ''}`} />
          </button>

          {showFilters && (
            <div className="absolute top-14 left-0 w-full bg-white dark:bg-slate-900 rounded-[2rem] shadow-xl border border-slate-100 dark:border-slate-800 z-50 p-2 space-y-1">
              <button onClick={() => { setDateFilter('TODAY'); setShowFilters(false); }} className={`w-full text-left px-4 py-3 text-[10px] font-black uppercase rounded-xl ${dateFilter === 'TODAY' ? 'bg-blue-50 text-blue-600' : 'hover:bg-slate-50'}`}>Today</button>
              <button onClick={() => { setDateFilter('TOMORROW'); setShowFilters(false); }} className={`w-full text-left px-4 py-3 text-[10px] font-black uppercase rounded-xl ${dateFilter === 'TOMORROW' ? 'bg-blue-50 text-blue-600' : 'hover:bg-slate-50'}`}>Tomorrow</button>
              <button onClick={() => { setDateFilter('YEAR'); setShowFilters(false); }} className={`w-full text-left px-4 py-3 text-[10px] font-black uppercase rounded-xl ${dateFilter === 'YEAR' ? 'bg-blue-50 text-blue-600' : 'hover:bg-slate-50'}`}>Year Sales</button>
              <button onClick={() => { setDateFilter('ALL'); setShowFilters(false); }} className={`w-full text-left px-4 py-3 text-[10px] font-black uppercase rounded-xl ${dateFilter === 'ALL' ? 'bg-blue-50 text-blue-600' : 'hover:bg-slate-50'}`}>All Time Sales</button>

              <div className="px-4 py-3 border-t border-slate-50 dark:border-slate-800 space-y-3">
                <p className="text-[8px] font-black text-slate-400 uppercase">Custom Range</p>
                <div className="grid grid-cols-2 gap-2">
                  <input 
                    type="date" 
                    className="w-full bg-slate-50 dark:bg-slate-800 p-2 rounded-xl text-[10px] font-bold outline-none border border-slate-100" 
                    value={startDate}
                    onChange={(e) => { setStartDate(e.target.value); setDateFilter('RANGE'); }}
                  />
                  <input 
                    type="date" 
                    className="w-full bg-slate-50 dark:bg-slate-800 p-2 rounded-xl text-[10px] font-bold outline-none border border-slate-100" 
                    value={endDate}
                    onChange={(e) => { setEndDate(e.target.value); setDateFilter('RANGE'); }}
                  />
                </div>
                {dateFilter === 'RANGE' && (
                  <button onClick={() => setShowFilters(false)} className="w-full py-2 bg-blue-600 text-white rounded-lg text-[9px] font-black uppercase tracking-widest">Apply Filter</button>
                )}
              </div>
            </div>
          )}
        </div>

        {config.businessLogo && (
          <div className="w-12 h-12 rounded-[1.2rem] overflow-hidden border border-slate-200 dark:border-slate-800 shadow-sm bg-white shrink-0">
            <img src={config.businessLogo} alt="Logo" className="w-full h-full object-contain" />
          </div>
        )}
      </div>

      {/* Main Revenue Display - Solid Color, No Gradient */}
      <div className={`p-8 rounded-[3rem] text-white shadow-lg bg-blue-600 relative overflow-hidden transition-all duration-500`}>
        <div className="relative z-10">
          <p className="text-white/70 text-[10px] font-black uppercase tracking-[0.3em] mb-3 flex items-center gap-2">
            <TrendingUp className="w-3 h-3" />
            Total Sales
          </p>
          <h3 className="text-5xl font-black tracking-tighter mb-6 leading-none">
            {formatCurrency(stats.total)}
          </h3>
          <div className="flex flex-wrap gap-2">
            <span className="bg-white/10 px-4 py-2 rounded-full text-[9px] font-black uppercase tracking-widest flex items-center gap-2 border border-white/10">
              <ArrowUpRight className="w-3.5 h-3.5 text-emerald-400" /> {filteredInvoices.length} Invoices
            </span>
          </div>
        </div>
      </div>

      {/* Payment Modes Breakdown */}
      <div className="grid grid-cols-2 gap-4">
        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.2rem] border border-slate-100 dark:border-slate-800 shadow-sm">
          <div className="flex items-center gap-3 mb-3">
            <div className="p-2.5 bg-emerald-50 dark:bg-emerald-900/40 text-emerald-600 rounded-xl"><Banknote className="w-5 h-5" /></div>
            <p className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Cash Collection</p>
          </div>
          <p className="text-xl font-black text-slate-900 dark:text-white leading-none">{formatCurrency(stats.cash)}</p>
        </div>
        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.2rem] border border-slate-100 dark:border-slate-800 shadow-sm">
          <div className="flex items-center gap-3 mb-3">
            <div className="p-2.5 bg-blue-50 dark:bg-blue-900/40 text-blue-600 rounded-xl"><CreditCard className="w-5 h-5" /></div>
            <p className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Online Payment</p>
          </div>
          <p className="text-xl font-black text-slate-900 dark:text-white leading-none">{formatCurrency(stats.online)}</p>
        </div>
      </div>

      {/* Primary Metrics */}
      <div className="grid grid-cols-2 gap-4">
        <StatCard 
          icon={<Users className="w-6 h-6" />} 
          bg="bg-purple-50 dark:bg-purple-900/40" 
          label="Total Clients" 
          value={clients.length.toString()} 
          color="text-purple-600"
          onClick={() => setModalType('CLIENTS')}
        />
        <StatCard 
          icon={<Wallet className="w-6 h-6" />} 
          bg="bg-orange-50 dark:bg-orange-900/40" 
          label="Outstanding Credit" 
          value={formatCurrency(clients.reduce((acc, c) => acc + c.totalBorrowed, 0))} 
          color="text-orange-600"
          onClick={() => setModalType('BORROWERS')}
        />
      </div>

      {/* Functional Actions */}
      <div className="grid grid-cols-2 gap-3">
        <ActionButton 
          icon={<AlertCircle className="w-5 h-5" />} 
          label="Low Stock Items" 
          count={lowStockItems.length}
          color="text-red-600"
          bg="bg-red-50 dark:bg-red-900/40"
          onClick={() => setModalType('LOW_STOCK')}
        />
        <ActionButton 
          icon={<QrCode className="w-5 h-5" />} 
          label="My QR Code" 
          color="text-blue-600"
          bg="bg-blue-50 dark:bg-blue-900/40"
          onClick={() => setModalType('QR_MODAL')}
        />
      </div>

      {/* Transaction Feed */}
      <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] p-8 shadow-sm border border-slate-100 dark:border-slate-800">
        <div className="flex justify-between items-center mb-8">
          <h4 className="font-black text-slate-900 dark:text-white text-sm tracking-tighter uppercase">Recent Activity</h4>
          <button onClick={() => onNavigate(Tab.INVOICES)} className="text-[10px] font-black text-blue-600 uppercase tracking-widest bg-blue-50 dark:bg-blue-900/40 px-4 py-1.5 rounded-full transition-all active:scale-95">Archive</button>
        </div>
        <div className="space-y-6">
          {filteredInvoices.slice(-5).reverse().map(inv => (
            <div key={inv.id} className="flex justify-between items-center group cursor-pointer active:bg-slate-50 dark:active:bg-slate-800 p-1 rounded-xl transition-all" onClick={() => onNavigate(Tab.INVOICES)}>
              <div className="flex gap-5 items-center">
                <div className="w-12 h-12 bg-slate-100 dark:bg-slate-800 rounded-2xl flex items-center justify-center text-slate-400 group-hover:text-blue-600 transition-all shadow-sm">
                  <FileText className="w-6 h-6" />
                </div>
                <div>
                  <p className="font-black text-xs text-slate-900 dark:text-slate-100 uppercase tracking-tight">{inv.clientName}</p>
                  <p className="text-[9px] text-slate-400 font-bold uppercase mt-0.5">{new Date(inv.date).toLocaleDateString('en-IN', { day: '2-digit', month: 'short' })} • #{inv.id}</p>
                </div>
              </div>
              <div className="text-right">
                <p className="font-black text-sm text-blue-600">{formatCurrency(inv.grandTotal)}</p>
                <p className="text-[8px] text-slate-300 font-black uppercase mt-0.5 tracking-widest">{inv.paymentMethod}</p>
              </div>
            </div>
          ))}
          {filteredInvoices.length === 0 && (
            <div className="text-center py-10 opacity-20">
               <FileText className="w-12 h-12 mx-auto mb-4" />
               <p className="text-[10px] font-black uppercase tracking-widest">No Recent Sales Found</p>
            </div>
          )}
        </div>
      </div>

      {/* Dynamic Modals */}
      {modalType && (
        <div className="fixed inset-0 bg-slate-900/60 dark:bg-black/60 backdrop-blur-sm z-[100] flex items-end justify-center px-4">
          <div className="bg-white dark:bg-slate-950 w-full max-w-lg rounded-t-[3.5rem] p-10 animate-slide-up shadow-xl">
            <div className="flex justify-between items-center mb-10">
              <h3 className="text-2xl font-black text-slate-900 dark:text-white uppercase tracking-tight">{modalType.replace('_', ' ')}</h3>
              <button onClick={() => setModalType(null)} className="p-3 bg-slate-100 dark:bg-slate-800 text-slate-500 rounded-full active:scale-90 transition-transform"><X className="w-6 h-6" /></button>
            </div>

            <div className="max-h-[50vh] overflow-y-auto space-y-4 pb-12 custom-scrollbar">
              {modalType === 'QR_MODAL' && (
                <div className="flex flex-col items-center gap-8 py-4">
                  {config.qrCodeImage ? (
                    <div className="w-64 h-64 p-3 bg-white rounded-[2.5rem] border border-slate-100 shadow-lg flex items-center justify-center">
                      <img src={config.qrCodeImage} alt="QR" className="w-full h-full object-contain" />
                    </div>
                  ) : (
                    <div className="text-center space-y-6">
                      <QrCode className="w-24 h-24 text-slate-200 dark:text-slate-800 mx-auto" />
                      <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Update QR in Settings</p>
                    </div>
                  )}
                  <div className="flex gap-4 w-full">
                    <label className="flex-1 bg-blue-600 text-white py-5 rounded-[1.8rem] font-black text-xs uppercase tracking-[0.2em] text-center cursor-pointer active:scale-95 transition-all">
                      Update Photo <input type="file" className="hidden" accept="image/*" onChange={handleQRUpload} />
                    </label>
                  </div>
                </div>
              )}
              {modalType === 'BORROWERS' && clients.filter(c => c.totalBorrowed > 0).map(c => (
                <div key={c.id} className="p-6 bg-slate-50 dark:bg-slate-900/50 rounded-3xl flex justify-between items-center border border-slate-100 dark:border-slate-800">
                  <div className="flex gap-4 items-center">
                    <div className="w-12 h-12 bg-white dark:bg-slate-800 rounded-2xl flex items-center justify-center shadow-sm text-orange-500"><IndianRupee className="w-6 h-6" /></div>
                    <div>
                      <p className="font-black text-slate-900 dark:text-white text-sm tracking-tight">{c.name}</p>
                      <p className="text-[10px] text-slate-400 font-bold tracking-widest uppercase mt-0.5">{c.mobile || 'No Mobile'}</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="font-black text-red-600 text-base">{formatCurrency(c.totalBorrowed)}</p>
                  </div>
                </div>
              ))}
              {modalType === 'CLIENTS' && clients.map(c => (
                <div key={c.id} className="p-6 bg-slate-50 dark:bg-slate-900/50 rounded-3xl flex justify-between items-center border border-slate-100 dark:border-slate-800">
                  <div className="flex gap-4 items-center">
                    <div className="w-12 h-12 bg-white dark:bg-slate-800 rounded-2xl flex items-center justify-center shadow-sm text-purple-600"><Users className="w-6 h-6" /></div>
                    <div>
                      <p className="font-black text-slate-900 dark:text-white text-sm tracking-tight">{c.name}</p>
                      <p className="text-[10px] text-slate-400 font-bold uppercase mt-0.5 tracking-widest">{c.mobile || 'Walk-in'}</p>
                    </div>
                  </div>
                  <ChevronRight className="w-5 h-5 text-slate-300" />
                </div>
              ))}
              {modalType === 'LOW_STOCK' && lowStockItems.map(p => (
                <div key={p.id} className="p-6 bg-red-50 dark:bg-red-900/20 rounded-3xl flex justify-between items-center border border-red-100 dark:border-red-900/40">
                  <div className="flex gap-4 items-center">
                    <div className="w-12 h-12 bg-white dark:bg-slate-900 rounded-2xl flex items-center justify-center shadow-sm text-red-600"><Package className="w-6 h-6" /></div>
                    <div>
                      <p className="font-black text-slate-900 dark:text-white text-sm tracking-tight">{p.name}</p>
                      <p className="text-[10px] text-red-500 font-black uppercase mt-0.5 tracking-widest">Only {p.stock} left</p>
                    </div>
                  </div>
                  <button onClick={() => onNavigate(Tab.INVENTORY)} className="bg-red-600 text-white px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest">Refill</button>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const StatCard: React.FC<{ icon: React.ReactNode, bg: string, label: string, value: string, color: string, onClick: () => void }> = ({ icon, bg, label, value, color, onClick }) => (
  <button onClick={onClick} className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 shadow-sm text-left flex flex-col gap-4 active:scale-[0.97] transition-all">
    <div className={`w-12 h-12 ${bg} ${color} rounded-2xl flex items-center justify-center shadow-sm`}>{icon}</div>
    <div>
      <p className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-1.5">{label}</p>
      <p className="text-xl font-black text-slate-900 dark:text-white leading-tight tracking-tight">{value}</p>
    </div>
  </button>
);

const ActionButton: React.FC<{ icon: React.ReactNode, label: string, color: string, bg: string, onClick: () => void, count?: number }> = ({ icon, label, color, bg, onClick, count }) => (
  <button onClick={onClick} className="bg-white dark:bg-slate-900 p-6 rounded-[2.2rem] border border-slate-100 dark:border-slate-800 shadow-sm flex items-center justify-between active:scale-[0.97] transition-all">
    <div className="flex items-center gap-4">
      <div className={`p-3 ${bg} ${color} rounded-2xl`}>{icon}</div>
      <p className="text-xs font-black text-slate-900 dark:text-white uppercase tracking-tighter">{label}</p>
    </div>
    {count !== undefined && count > 0 && (
      <span className="bg-red-600 text-white text-[10px] font-black w-6 h-6 rounded-full flex items-center justify-center">
        {count}
      </span>
    )}
  </button>
);

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { 
  Plus, 
  Minus, 
  CheckCircle2,
  X,
  CreditCard,
  Banknote,
  Clock,
  Package,
  Users,
  ScanLine,
  ShoppingCart,
  Briefcase,
  Box,
  Trash2,
  Search,
  Save,
  ArrowRight,
  ChevronRight,
  ListFilter
} from 'lucide-react';
import { Product, Client, Invoice, InvoiceItem, PaymentMethod, AppConfig, ItemType } from '../types';
import { generateId, formatCurrency } from '../utils/helpers';
import InvoiceDetail from '../components/InvoiceDetail';
import BarcodeScanner from '../components/BarcodeScanner';

interface BillingProps {
  products: Product[];
  clients: Client[];
  setInvoices: React.Dispatch<React.SetStateAction<Invoice[]>>;
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  setClients: React.Dispatch<React.SetStateAction<Client[]>>;
  config: AppConfig;
}

const Billing: React.FC<BillingProps> = ({ products, clients, setInvoices, setProducts, setClients, config }) => {
  const [cart, setCart] = useState<InvoiceItem[]>([]);
  const [custName, setCustName] = useState('');
  const [custMobile, setCustMobile] = useState('');
  const [selectedClientId, setSelectedClientId] = useState<string | null>(null);

  const [discount, setDiscount] = useState(0);
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>(PaymentMethod.CASH);
  const [showCheckout, setShowCheckout] = useState(false);
  const [showScanner, setShowScanner] = useState(false);
  const [showClientList, setShowClientList] = useState(false);
  const [showFullListSelector, setShowFullListSelector] = useState(false);
  const [generatedInvoice, setGeneratedInvoice] = useState<Invoice | null>(null);

  // Form states
  const [activeForm, setActiveForm] = useState<ItemType | null>(null);
  const [formData, setFormData] = useState({
    name: '',
    price: '',
    quantity: '1',
    barcode: '',
    id: ''
  });
  const [searchQuery, setSearchQuery] = useState('');

  const filteredInventory = useMemo(() => {
    return products.filter(p => 
      p.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
      (p.barcode && p.barcode.includes(searchQuery))
    );
  }, [searchQuery, products]);

  const handleSelectFromInventory = (p: Product) => {
    setFormData({
      ...formData,
      name: p.name,
      price: p.price.toString(),
      barcode: p.barcode || '',
      id: p.id
    });
    setActiveForm(p.type);
    setSearchQuery('');
    setShowFullListSelector(false);
  };

  const handleAddToCart = () => {
    const priceNum = parseFloat(formData.price) || 0;
    const qtyNum = parseInt(formData.quantity) || 1;

    if (!formData.name) {
      alert("Kripya naam bharein!");
      return;
    }

    const newItem: InvoiceItem = {
      id: formData.id || generateId(),
      name: formData.name,
      price: priceNum,
      quantity: qtyNum,
      total: priceNum * qtyNum,
      type: activeForm || ItemType.PRODUCT
    };

    setCart(prev => [...prev, newItem]);
    setActiveForm(null);
    setFormData({ name: '', price: '', quantity: '1', barcode: '', id: '' });
  };

  const handleBarcodeScanned = (barcode: string) => {
    setShowScanner(false);
    const product = products.find(p => p.barcode === barcode);
    if (product) {
      setFormData({
        name: product.name,
        price: product.price.toString(),
        quantity: '1',
        barcode: product.barcode || '',
        id: product.id
      });
      setActiveForm(ItemType.PRODUCT);
    } else {
      alert(`Barcode ${barcode} wala product nahi mila.`);
    }
  };

  const handleFinish = () => {
    if (!custName) {
      alert("Kripya Grahak ka naam likhein!");
      return;
    }
    if (cart.length === 0) {
      alert("Aapka cart khali hai!");
      return;
    }

    const subtotalVal = cart.reduce((acc, i) => acc + i.total, 0);
    const totalVal = subtotalVal * (1 - discount/100);

    const invoice: Invoice = {
      id: `INV-${Date.now().toString().slice(-6)}`,
      date: new Date().toISOString(),
      clientId: selectedClientId || 'WALK_IN',
      clientName: custName,
      clientMobile: custMobile,
      items: [...cart],
      discount,
      subtotal: subtotalVal,
      grandTotal: totalVal,
      paymentMethod
    };

    setInvoices(prev => [...prev, invoice]);

    setProducts(prev => prev.map(p => {
      const cartItem = cart.find(item => item.id === p.id && item.type === ItemType.PRODUCT);
      return (cartItem && p.stock !== null) ? { ...p, stock: p.stock - cartItem.quantity } : p;
    }));

    if (paymentMethod === PaymentMethod.BORROW) {
      setClients(prev => {
        const existingIdx = prev.findIndex(c => c.name === custName);
        if (existingIdx > -1) {
          const updated = [...prev];
          updated[existingIdx].totalBorrowed += invoice.grandTotal;
          return updated;
        } else {
          return [...prev, { id: generateId(), name: custName, mobile: custMobile, totalBorrowed: invoice.grandTotal }];
        }
      });
    }

    setGeneratedInvoice(invoice);
    setShowCheckout(false);
    setCart([]);
  };

  const subtotal = cart.reduce((acc, item) => acc + item.total, 0);
  const grandTotal = subtotal * (1 - discount / 100);

  if (generatedInvoice) {
    return (
      <div className="space-y-4">
        <div className="bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 p-5 rounded-[2rem] border border-emerald-100 dark:border-emerald-800 flex items-center gap-4">
          <CheckCircle2 className="w-8 h-8" />
          <div>
            <p className="font-black uppercase tracking-tight text-sm">Bill Safalta se Bana!</p>
            <p className="text-[10px] font-bold opacity-80">Invoice saved to system.</p>
          </div>
        </div>
        <InvoiceDetail invoice={generatedInvoice} config={config} />
        <button onClick={() => setGeneratedInvoice(null)} className="w-full bg-slate-900 dark:bg-blue-600 text-white py-5 rounded-2xl font-black uppercase tracking-widest active:scale-95 transition-all">Naya Bill Banayein</button>
      </div>
    );
  }

  return (
    <div className="space-y-6 pb-24 animate-in fade-in duration-500">
      {showScanner && (
        <BarcodeScanner onScan={handleBarcodeScanned} onClose={() => setShowScanner(false)} title="Billing Scanner" />
      )}

      {/* Customer Input */}
      <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] shadow-sm border border-slate-100 dark:border-slate-800 space-y-4">
        <div className="flex justify-between items-center mb-2">
          <h3 className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Customer Information</h3>
          <button onClick={() => setShowClientList(true)} className="flex items-center gap-1.5 text-blue-600 font-black text-[10px] bg-blue-50 dark:bg-blue-900/40 px-3 py-1.5 rounded-full uppercase transition-all active:scale-95">
            <Users className="w-3.5 h-3.5" /> Directory
          </button>
        </div>
        <div className="grid grid-cols-1 gap-3">
          <input 
            type="text" placeholder="Grahak ka Naam *" 
            className="w-full p-4 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl text-slate-900 dark:text-white font-black outline-none focus:ring-2 focus:ring-blue-500"
            value={custName} onChange={e => setCustName(e.target.value)}
          />
          <input 
            type="tel" placeholder="Mobile Number" 
            className="w-full p-4 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700 rounded-2xl text-slate-900 dark:text-white font-black outline-none focus:ring-2 focus:ring-blue-500"
            value={custMobile} onChange={e => setCustMobile(e.target.value.replace(/[^0-9]/g, ''))}
          />
        </div>
      </div>

      {/* Selector Button & Icons - No Gradient or Glow */}
      <div className="space-y-4">
        <button 
          onClick={() => setShowFullListSelector(true)}
          className="w-full flex items-center justify-between p-6 bg-blue-600 text-white rounded-[2rem] shadow-md active:scale-[0.98] transition-all border-b-4 border-blue-800"
        >
          <div className="flex items-center gap-4">
            <div className="p-3 bg-white/10 rounded-xl">
              <ShoppingCart className="w-6 h-6" />
            </div>
            <div className="text-left">
              <span className="block text-sm font-black uppercase tracking-widest">Select Product/Service</span>
              <span className="block text-[10px] opacity-70 font-bold uppercase">Browse inventory list</span>
            </div>
          </div>
          <ChevronRight className="w-6 h-6 opacity-50" />
        </button>

        <div className="grid grid-cols-2 gap-4">
          <button 
            onClick={() => { setActiveForm(ItemType.PRODUCT); setFormData({name: '', price: '', quantity: '1', barcode: '', id: ''}); }}
            className="flex items-center gap-3 p-4 bg-white dark:bg-slate-900 text-slate-900 dark:text-white rounded-[1.8rem] shadow-sm border border-slate-200 dark:border-slate-800 active:scale-95 transition-all"
          >
            <div className="p-2 bg-blue-50 dark:bg-blue-900/30 text-blue-600 rounded-xl">
              <Box className="w-4 h-4" />
            </div>
            <span className="text-[10px] font-black uppercase tracking-widest">Add Prod.</span>
          </button>

          <button 
            onClick={() => { setActiveForm(ItemType.SERVICE); setFormData({name: '', price: '', quantity: '1', barcode: '', id: ''}); }}
            className="flex items-center gap-3 p-4 bg-white dark:bg-slate-900 text-slate-900 dark:text-white rounded-[1.8rem] shadow-sm border border-slate-200 dark:border-slate-800 active:scale-95 transition-all"
          >
            <div className="p-2 bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 rounded-xl">
              <Briefcase className="w-4 h-4" />
            </div>
            <span className="text-[10px] font-black uppercase tracking-widest">Add Serv.</span>
          </button>
        </div>
      </div>

      {/* Cart Items */}
      <div className="bg-white dark:bg-slate-900 rounded-[3rem] p-8 shadow-sm border border-slate-100 dark:border-slate-800">
        <div className="flex justify-between items-center mb-8">
          <h3 className="text-sm font-black text-slate-900 dark:text-white uppercase tracking-tight">Shopping Cart</h3>
          <button onClick={() => setShowScanner(true)} className="p-3 bg-slate-100 dark:bg-slate-800 text-slate-500 rounded-2xl active:scale-90 transition-all">
            <ScanLine className="w-5 h-5" />
          </button>
        </div>

        {cart.length === 0 ? (
          <div className="text-center py-16 opacity-30">
            <ShoppingCart className="w-16 h-16 mx-auto mb-4" />
            <p className="text-[10px] font-black uppercase tracking-widest">No items in cart</p>
          </div>
        ) : (
          <div className="space-y-8">
            {cart.map((item, idx) => (
              <div key={idx} className="flex items-center justify-between group">
                <div className="flex-1">
                  <div className="flex items-center gap-3">
                    <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${item.type === ItemType.SERVICE ? 'bg-purple-100 text-purple-600' : 'bg-blue-100 text-blue-600'}`}>
                      {item.type === ItemType.SERVICE ? <Briefcase className="w-4 h-4" /> : <Box className="w-4 h-4" />}
                    </div>
                    <div>
                      <p className="font-black text-xs text-slate-900 dark:text-white uppercase tracking-tight">{item.name}</p>
                      <p className="text-[9px] text-slate-400 font-bold uppercase mt-1">
                        {formatCurrency(item.price)} × {item.quantity}
                      </p>
                    </div>
                  </div>
                </div>
                <div className="flex items-center gap-4">
                  <p className="font-black text-sm text-slate-900 dark:text-white">{formatCurrency(item.total)}</p>
                  <button onClick={() => setCart(prev => prev.filter((_, i) => i !== idx))} className="p-2 text-slate-200 hover:text-red-500 transition-colors">
                    <Trash2 className="w-5 h-5" />
                  </button>
                </div>
              </div>
            ))}

            <div className="pt-8 border-t border-slate-100 dark:border-slate-800 space-y-4">
              <div className="flex justify-between text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">
                <span>Subtotal</span>
                <span>{formatCurrency(subtotal)}</span>
              </div>
              <div className="flex justify-between items-center text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">
                <span>Discount (%)</span>
                <input 
                  type="number" 
                  className="w-16 text-right p-2.5 bg-slate-50 dark:bg-slate-800 rounded-xl font-black text-slate-900 dark:text-white border border-slate-200 dark:border-slate-700 outline-none" 
                  value={discount} 
                  onChange={e => setDiscount(Number(e.target.value) || 0)} 
                />
              </div>
              <div className="flex justify-between items-end text-3xl font-black text-blue-600 pt-6 border-t border-blue-50 dark:border-blue-900/50">
                <div className="flex flex-col">
                  <span className="text-[10px] uppercase tracking-widest text-slate-400 mb-1">Total Amount</span>
                  <span>{formatCurrency(grandTotal)}</span>
                </div>
                <button 
                  onClick={() => setShowCheckout(true)}
                  className="bg-blue-600 text-white p-4 rounded-2xl shadow-md active:scale-95 transition-all"
                >
                  <ArrowRight className="w-6 h-6" />
                </button>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Inventory Selector screen */}
      {showFullListSelector && (
        <div className="fixed inset-0 bg-slate-50 dark:bg-slate-950 z-[200] flex flex-col animate-in fade-in duration-300">
          <div className="p-6 border-b border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 flex justify-between items-center">
            <div>
              <h2 className="text-xl font-black text-slate-900 dark:text-white uppercase tracking-tight">Browse Inventory</h2>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Select an item to add to bill</p>
            </div>
            <button onClick={() => setShowFullListSelector(false)} className="p-3 bg-slate-100 dark:bg-slate-800 rounded-full text-slate-500 active:scale-90 transition-transform">
              <X className="w-6 h-6" />
            </button>
          </div>

          <div className="p-4 bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800">
            <div className="relative">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-300" />
              <input 
                type="text" 
                placeholder="Product ya Service khojein..." 
                className="w-full pl-12 pr-4 py-4 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl text-slate-900 dark:text-white font-black outline-none focus:ring-2 focus:ring-blue-500"
                value={searchQuery}
                onChange={e => setSearchQuery(e.target.value)}
                autoFocus
              />
            </div>
          </div>

          <div className="flex-1 overflow-y-auto p-4 space-y-3 custom-scrollbar">
            {filteredInventory.map(p => (
              <button 
                key={p.id} 
                onClick={() => handleSelectFromInventory(p)}
                className="w-full flex items-center justify-between p-5 bg-white dark:bg-slate-900 rounded-[2rem] border border-slate-200 dark:border-slate-800 active:scale-[0.98] transition-all hover:border-blue-600 group"
              >
                <div className="flex items-center gap-4">
                  <div className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-colors ${p.type === ItemType.SERVICE ? 'bg-purple-100 text-purple-600' : 'bg-blue-50 text-blue-600'} group-hover:bg-blue-600 group-hover:text-white`}>
                    {p.type === ItemType.SERVICE ? <Briefcase className="w-5 h-5" /> : <Box className="w-5 h-5" />}
                  </div>
                  <div className="text-left">
                    <p className="font-black text-sm text-slate-900 dark:text-white uppercase tracking-tight">{p.name}</p>
                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">
                      {formatCurrency(p.price)} {p.type === ItemType.PRODUCT && `• Stock: ${p.stock ?? '∞'}`}
                    </p>
                  </div>
                </div>
                <div className="w-10 h-10 flex items-center justify-center bg-slate-50 dark:bg-slate-800 rounded-full text-slate-300 group-hover:text-blue-600">
                  <Plus className="w-5 h-5" />
                </div>
              </button>
            ))}

            {filteredInventory.length === 0 && (
              <div className="text-center py-20 opacity-20">
                <ShoppingCart className="w-16 h-16 mx-auto mb-4" />
                <p className="text-[10px] font-black uppercase tracking-widest">Inventory empty or no results</p>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Item Form Modal - Flat, No Glow */}
      {activeForm && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[210] flex items-end justify-center px-4">
          <div className="bg-white dark:bg-slate-900 w-full max-w-lg rounded-t-[3.5rem] p-10 animate-slide-up shadow-xl border-t border-slate-200 dark:border-slate-800">
            <div className="flex justify-between items-center mb-10">
              <div className="flex items-center gap-4">
                <div className={`p-4 rounded-2xl ${activeForm === ItemType.PRODUCT ? 'bg-blue-600 text-white' : 'bg-slate-900 text-white'}`}>
                  {activeForm === ItemType.PRODUCT ? <Box className="w-6 h-6" /> : <Briefcase className="w-6 h-6" />}
                </div>
                <div>
                  <h3 className="text-2xl font-black text-slate-900 dark:text-white uppercase tracking-tight">Add {activeForm}</h3>
                  <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">Enter details for cart</p>
                </div>
              </div>
              <button onClick={() => setActiveForm(null)} className="p-3 bg-slate-100 dark:bg-slate-800 rounded-full text-slate-500"><X className="w-6 h-6" /></button>
