      )}

      {/* Payment Confirmation Modal */}
      {showCheckout && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[220] flex items-end justify-center px-4">
          <div className="bg-white dark:bg-slate-950 w-full max-w-lg rounded-t-[3.5rem] p-10 animate-slide-up shadow-xl border-t border-slate-200 dark:border-slate-800">
            <div className="flex justify-between items-center mb-10">
              <h3 className="text-2xl font-black text-slate-900 dark:text-white uppercase tracking-tight">Select Payment</h3>
              <button onClick={() => setShowCheckout(false)} className="p-3 bg-slate-100 dark:bg-slate-800 text-slate-500 rounded-full active:scale-90 transition-transform"><X className="w-6 h-6" /></button>
            </div>

            <div className="space-y-4 mb-10">
              <PaymentButton active={paymentMethod === PaymentMethod.CASH} onClick={() => setPaymentMethod(PaymentMethod.CASH)} icon={<Banknote />} label="Cash Payment" desc="Payment received in cash" />
              <PaymentButton active={paymentMethod === PaymentMethod.ONLINE} onClick={() => setPaymentMethod(PaymentMethod.ONLINE)} icon={<CreditCard />} label="Online / UPI" desc="Payment via QR or Bank" />
              <PaymentButton active={paymentMethod === PaymentMethod.BORROW} onClick={() => setPaymentMethod(PaymentMethod.BORROW)} icon={<Clock />} label="Udhaar / Khata" desc="Add to client's pending balance" />
            </div>

            <button 
              onClick={handleFinish}
              className="w-full bg-blue-600 text-white py-6 rounded-[2.5rem] font-black uppercase tracking-[0.3em] shadow-md active:scale-95 transition-all"
            >
              Generate Invoice
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

