interface SetupProps {
  onComplete: (config: AppConfig) => void;
}

const Setup: React.FC<SetupProps> = ({ onComplete }) => {
  const [formData, setFormData] = useState({
    ownerName: '',
    shopName: '',
    shopMobile: '',
    pin: '',
    confirmPin: '',
    lowStockThreshold: 5,
    isDarkMode: false
  });
