import React, { useState, useEffect } from 'react';
import { Delete, Lock, ShieldAlert } from 'lucide-react';

interface PinLockProps {
  correctPin: string;
  onUnlock: () => void;
  shopName: string;
}

const PinLock: React.FC<PinLockProps> = ({ correctPin, onUnlock, shopName }) => {
  const [pin, setPin] = useState('');
  const [error, setError] = useState(false);

  const handlePress = (num: string) => {
    if (pin.length < 4) {
      const newPin = pin + num;
      setPin(newPin);
      if (newPin.length === 4) {
        if (newPin === correctPin) {
          onUnlock();
        } else {
          setError(true);
          setTimeout(() => {
            setPin('');
            setError(false);
          }, 600);
        }
      }
    }
  };

  const handleBackspace = () => {
    setPin(pin.slice(0, -1));
  };

  return (
    <div className="min-h-screen bg-blue-700 flex flex-col items-center justify-center p-8 transition-colors duration-300">
      <div className="text-white text-center mb-12">
        <div className="w-20 h-20 bg-white/10 rounded-full flex items-center justify-center mx-auto mb-6 border border-white/10">
          <Lock className="w-8 h-8 text-white" />
        </div>
        <h1 className="text-2xl font-black mb-1 uppercase tracking-tight">{shopName}</h1>
        <p className="text-blue-200 text-xs font-bold uppercase tracking-widest">Enter PIN to Unlock</p>
      </div>

      {/* Dots */}
      <div className={`flex gap-6 mb-16 transition-transform ${error ? 'animate-bounce' : ''}`}>
        {[0, 1, 2, 3].map(i => (
          <div 
            key={i} 
            className={`w-4 h-4 rounded-full border-2 border-white/50 transition-all ${pin.length > i ? 'bg-white scale-125' : 'bg-transparent'}`}
          />
        ))}
      </div>

      {/* Keypad */}
      <div className="grid grid-cols-3 gap-6 w-full max-w-xs">
        {['1', '2', '3', '4', '5', '6', '7', '8', '9'].map(num => (
          <button 
            key={num} 
            onClick={() => handlePress(num)}
            className="w-full aspect-square bg-white/10 hover:bg-white/20 active:bg-white/30 text-white text-2xl font-black rounded-full transition-colors flex items-center justify-center"
          >
            {num}
          </button>
        ))}
        <div />
        <button 
          onClick={() => handlePress('0')}
          className="w-full aspect-square bg-white/10 hover:bg-white/20 active:bg-white/30 text-white text-2xl font-black rounded-full transition-colors flex items-center justify-center"
        >
          0
        </button>
        <button 
          onClick={handleBackspace}
          className="w-full aspect-square flex items-center justify-center text-white/50 active:text-white"
        >
          <Delete className="w-8 h-8" />
        </button>
      </div>

      <button 
        onClick={() => {
          if (confirm("Reset App? All data will be lost.")) {
            localStorage.clear();
            window.location.reload();
          }
        }}
        className="mt-12 text-blue-300 text-[10px] font-black uppercase tracking-[0.2em] hover:text-white"
      >
        Forgot PIN? Reset App
      </button>
    </div>
  );
};

export default PinLock;

