          <button 
            onClick={() => setIsSuccess(false)} 
            className="w-full bg-blue-600 text-white py-5 rounded-2xl font-black uppercase tracking-widest shadow-md active:scale-95 transition-all"
          >
            Naya Bill Banayein
          </button>
          <p className="text-[10px] text-slate-400 font-black uppercase tracking-[0.2em]">Check History for details</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 pb-24 animate-in fade-in duration-500">
      {showScanner && (
        <BarcodeScanner onScan={handleBarcodeScanned} onClose={() => setShowScanner(false)} title="Billing Scanner" />
      )}

