import React, { useState, useEffect } from 'react';
import { 
  LayoutGrid, 
  ReceiptIndianRupee, 
  PackageSearch, 
  Clock7, 
  UserCircle2,
  LockKeyhole,
  Moon,
  Sun,
  Plus
} from 'lucide-react';
import { AppConfig, Tab, Product, Client, Invoice } from './types';
import Dashboard from './views/Dashboard';
import Billing from './views/Billing';
import Inventory from './views/Inventory';
import Invoices from './views/Invoices';
import Settings from './views/Settings';
import Setup from './components/Setup';
import PinLock from './components/PinLock';

const App: React.FC = () => {
  const [config, setConfig] = useState<AppConfig | null>(null);
  const [isLocked, setIsLocked] = useState(true);
  const [activeTab, setActiveTab] = useState<Tab>(Tab.DASHBOARD);

  const [products, setProducts] = useState<Product[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [invoices, setInvoices] = useState<Invoice[]>([]);

  useEffect(() => {
    const savedConfig = localStorage.getItem('app_config');
    const savedProducts = localStorage.getItem('products');
    const savedClients = localStorage.getItem('clients');
    const savedInvoices = localStorage.getItem('invoices');

    if (savedConfig) {
      const parsedConfig = JSON.parse(savedConfig);
      setConfig(parsedConfig);
      if (parsedConfig.isDarkMode) {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
    }
    if (savedProducts) setProducts(JSON.parse(savedProducts));
    if (savedClients) setClients(JSON.parse(savedClients));
    if (savedInvoices) setInvoices(JSON.parse(savedInvoices));
  }, []);

  useEffect(() => {
    if (config) {
      localStorage.setItem('app_config', JSON.stringify(config));
      if (config.isDarkMode) {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
    }
  }, [config]);

  useEffect(() => localStorage.setItem('products', JSON.stringify(products)), [products]);
  useEffect(() => localStorage.setItem('clients', JSON.stringify(clients)), [clients]);
  useEffect(() => localStorage.setItem('invoices', JSON.stringify(invoices)), [invoices]);

  const handleSetupComplete = (newConfig: AppConfig) => {
    setConfig(newConfig);
    setIsLocked(false);
  };

  const handleUnlock = () => setIsLocked(false);

  if (!config || !config.setupComplete) return <Setup onComplete={handleSetupComplete} />;
  if (isLocked) return <PinLock correctPin={config.pin} onUnlock={handleUnlock} shopName={config.shopName} />;

  const renderView = () => {
    switch (activeTab) {
      case Tab.DASHBOARD: return <Dashboard invoices={invoices} clients={clients} products={products} config={config} onNavigate={setActiveTab} setConfig={setConfig} />;
      case Tab.BILLING: return <Billing products={products} clients={clients} setInvoices={setInvoices} setProducts={setProducts} setClients={setClients} config={config} />;
      case Tab.INVENTORY: return <Inventory products={products} setProducts={setProducts} config={config} />;
      case Tab.INVOICES: return <Invoices invoices={invoices} config={config} />;
      case Tab.SETTINGS: return <Settings config={config} setConfig={setConfig} />;
      default: return null;
    }
  };

  return (
    <div className={`min-h-screen pb-32 flex flex-col transition-colors duration-500 ${config.isDarkMode ? 'bg-slate-950' : 'bg-[#FAFAFB]'}`}>
      <header className={`sticky top-0 z-50 glass border-b dark:border-slate-800 p-4`}>
        <div className="flex justify-between items-center max-w-lg mx-auto w-full">
          <div>
            <h1 className="text-xl font-extrabold tracking-tight text-slate-900 dark:text-white leading-tight">{config.shopName}</h1>
            <div className="flex items-center gap-2 mt-0.5">
              <div className="w-1.5 h-1.5 rounded-full bg-emerald-500"></div>
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Active Workspace</p>
            </div>
          </div>
          <div className="flex gap-2.5">
            <button onClick={() => setConfig({ ...config, isDarkMode: !config.isDarkMode })} className="p-2.5 bg-slate-100 dark:bg-slate-800 rounded-2xl transition-all active:scale-90 border border-transparent dark:border-slate-700">
              {config.isDarkMode ? <Sun className="w-4.5 h-4.5 text-orange-400" /> : <Moon className="w-4.5 h-4.5 text-slate-600" />}
            </button>
            <button onClick={() => setIsLocked(true)} className="p-2.5 bg-slate-100 dark:bg-slate-800 rounded-2xl transition-all active:scale-90 border border-transparent dark:border-slate-700">
              <LockKeyhole className="w-4.5 h-4.5 text-slate-400" />
            </button>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-lg mx-auto w-full px-5 pt-6 animate-in-view">
        {renderView()}
      </main>

      {activeTab !== Tab.BILLING && (
        <button 
          onClick={() => setActiveTab(Tab.BILLING)}
          className="fixed bottom-28 right-6 w-14 h-14 bg-brand-500 text-white rounded-2xl shadow-xl shadow-brand-500/20 flex items-center justify-center transition-all active:scale-95 z-[60] border-2 border-white/20"
        >
          <Plus className="w-8 h-8" />
        </button>
      )}

      <nav className="fixed bottom-0 left-0 right-0 px-4 pb-4 safe-bottom z-50 pointer-events-none">
        <div className="max-w-md mx-auto pointer-events-auto bg-white/90 dark:bg-slate-900/90 backdrop-blur-xl border border-slate-200 dark:border-slate-800 rounded-[2.5rem] shadow-2xl flex justify-between items-center h-18 px-3">
          <NavItem active={activeTab === Tab.DASHBOARD} onClick={() => setActiveTab(Tab.DASHBOARD)} icon={<LayoutGrid className="w-5 h-5" />} label="Home" />
          <NavItem active={activeTab === Tab.BILLING} onClick={() => setActiveTab(Tab.BILLING)} icon={<ReceiptIndianRupee className="w-5 h-5" />} label="Bill" />
          <NavItem active={activeTab === Tab.INVENTORY} onClick={() => setActiveTab(Tab.INVENTORY)} icon={<PackageSearch className="w-5 h-5" />} label="Stock" />
          <NavItem active={activeTab === Tab.INVOICES} onClick={() => setActiveTab(Tab.INVOICES)} icon={<Clock7 className="w-5 h-5" />} label="History" />
          <NavItem active={activeTab === Tab.SETTINGS} onClick={() => setActiveTab(Tab.SETTINGS)} icon={<UserCircle2 className="w-5 h-5" />} label="Me" />
        </div>
      </nav>
    </div>
  );
};

const NavItem = ({ active, onClick, icon, label }: any) => (
  <button onClick={onClick} className={`flex flex-col items-center justify-center flex-1 transition-all py-2 gap-1 ${active ? 'text-brand-500' : 'text-slate-400'}`}>
    <div className={`transition-all duration-300 ${active ? 'scale-110' : 'scale-100 opacity-60'}`}>{icon}</div>
    <span className={`text-[9px] font-extrabold uppercase tracking-widest transition-opacity ${active ? 'opacity-100' : 'opacity-0 h-0 overflow-hidden'}`}>{label}</span>
  </button>
);

export default App;

import React, { useMemo } from 'react';
import { 
  TrendingUp, 
  Wallet2, 
  Users2, 
  AlertCircle,
  FileText,
  ChevronRight,
  IndianRupee,
  ArrowUpRight,
  Plus
} from 'lucide-react';
import { Invoice, Client, Product, AppConfig, Tab, PaymentMethod } from '../types';
import { formatCurrency } from '../utils/helpers';

interface DashboardProps {
  invoices: Invoice[];
  clients: Client[];
  products: Product[];
  config: AppConfig;
  onNavigate: (tab: Tab) => void;
  setConfig?: (config: AppConfig) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ invoices, clients, products, config, onNavigate }) => {
  const stats = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    const todaysInvoices = invoices.filter(inv => inv.date.startsWith(today));
    const total = todaysInvoices.reduce((acc, inv) => acc + inv.grandTotal, 0);
    const borrowTotal = clients.reduce((acc, c) => acc + c.totalBorrowed, 0);
    return { total, borrowTotal, count: todaysInvoices.length };
  }, [invoices, clients]);

  const greeting = useMemo(() => {
    const hour = new Date().getHours();
    if (hour < 12) return "Good morning";
    if (hour < 17) return "Good afternoon";
    return "Good evening";
  }, []);

  const lowStock = products.filter(p => p.stock !== null && p.stock <= config.lowStockThreshold);

  return (
    <div className="space-y-8 animate-in-view">
      {/* Editorial Header */}
      <div>
        <h2 className="text-3xl font-extrabold text-slate-900 dark:text-white tracking-tight leading-none">{greeting}, {config.ownerName.split(' ')[0]}!</h2>
        <p className="text-slate-500 dark:text-slate-400 font-medium text-sm mt-2">Here's what's happening today at <span className="text-slate-900 dark:text-white font-bold">{config.shopName}</span>.</p>
      </div>

      {/* Hero Stats */}
      <div className="bg-slate-900 dark:bg-brand-600 rounded-[2.5rem] p-8 text-white relative overflow-hidden shadow-2xl">
        <div className="absolute top-[-20%] right-[-10%] w-64 h-64 bg-white/5 rounded-full blur-3xl pointer-events-none"></div>
        <div className="relative z-10">
          <div className="flex items-center gap-2 mb-4">
            <div className="p-1.5 bg-brand-500/20 rounded-lg"><TrendingUp className="w-3.5 h-3.5 text-brand-400" /></div>
            <p className="text-[10px] font-black uppercase tracking-[0.3em] text-white/50">Today's Revenue</p>
          </div>
          <h3 className="text-5xl font-black tracking-tighter mb-4">{formatCurrency(stats.total)}</h3>
          <div className="flex items-center gap-3">
            <span className="text-[10px] font-black uppercase tracking-widest px-3 py-1.5 bg-white/10 rounded-full border border-white/10">{stats.count} Total Invoices</span>
            <button onClick={() => onNavigate(Tab.BILLING)} className="ml-auto w-10 h-10 bg-white text-slate-900 rounded-xl flex items-center justify-center transition-all active:scale-90">
              <Plus className="w-5 h-5" />
            </button>
          </div>
        </div>
      </div>

      {/* Grid Stats */}
      <div className="grid grid-cols-2 gap-4">
        <CompactStatCard 
          icon={<Wallet2 className="w-5 h-5" />} 
          label="Total Credit" 
          value={formatCurrency(stats.borrowTotal)} 
          sub="Pending Khata"
          color="text-orange-500"
          bg="bg-orange-50 dark:bg-orange-500/10"
        />
        <CompactStatCard 
          icon={<Users2 className="w-5 h-5" />} 
          label="Clients" 
          value={clients.length.toString()} 
          sub="Loyal Customers"
          color="text-brand-500"
          bg="bg-brand-50 dark:bg-brand-500/10"
        />
      </div>

      {/* Low Stock Toast */}
      {lowStock.length > 0 && (
        <button 
          onClick={() => onNavigate(Tab.INVENTORY)}
          className="w-full flex items-center gap-4 p-5 bg-white dark:bg-slate-900 rounded-[1.8rem] border border-red-100 dark:border-red-900/30 text-left active:scale-[0.98] transition-all shadow-sm"
        >
          <div className="p-3 bg-red-50 dark:bg-red-900/20 text-red-600 rounded-xl"><AlertCircle className="w-5 h-5" /></div>
          <div>
            <p className="text-[10px] font-black text-red-600 dark:text-red-400 uppercase tracking-widest">Stock Alert</p>
            <p className="text-sm font-bold text-slate-800 dark:text-slate-200">{lowStock.length} items are running low.</p>
          </div>
          <ChevronRight className="ml-auto w-5 h-5 text-slate-300" />
        </button>
      )}

      {/* Recent Feed */}
      <div className="space-y-5">
        <div className="flex justify-between items-center px-1">
          <h4 className="text-xs font-black text-slate-400 uppercase tracking-[0.2em]">Latest Transactions</h4>
          <button onClick={() => onNavigate(Tab.INVOICES)} className="text-[10px] font-bold text-brand-500">See All</button>
        </div>
        <div className="space-y-3">
          {invoices.slice(-3).reverse().map(inv => (
            <div key={inv.id} className="flex items-center justify-between p-5 bg-white dark:bg-slate-900 rounded-[2rem] border border-slate-100 dark:border-slate-800 shadow-sm active:scale-[0.99] transition-all">
              <div className="flex items-center gap-4">
                <div className="w-11 h-11 bg-slate-50 dark:bg-slate-800 rounded-xl flex items-center justify-center text-slate-400"><FileText className="w-5 h-5" /></div>
                <div>
                  <p className="font-extrabold text-sm text-slate-900 dark:text-white uppercase tracking-tight">{inv.clientName}</p>
                  <p className="text-[9px] text-slate-400 font-bold uppercase mt-0.5 tracking-widest">{inv.id} • {new Date(inv.date).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p>
                </div>
              </div>
              <div className="text-right">
                <p className="font-black text-slate-900 dark:text-white">{formatCurrency(inv.grandTotal)}</p>
                <div className="flex items-center justify-end gap-1.5 mt-0.5">
                   <div className="w-1 h-1 rounded-full bg-emerald-500"></div>
                   <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest">{inv.paymentMethod}</p>
                </div>
              </div>
            </div>
          ))}
          {invoices.length === 0 && (
            <div className="py-12 text-center opacity-30">
              <IndianRupee className="w-12 h-12 mx-auto mb-3" />
              <p className="text-[10px] font-black uppercase tracking-widest">No transactions yet</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

const CompactStatCard = ({ icon, label, value, sub, color, bg }: any) => (
  <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.2rem] border border-slate-100 dark:border-slate-800 shadow-sm">
    <div className={`w-10 h-10 ${bg} ${color} rounded-xl flex items-center justify-center mb-4 transition-transform`}>{icon}</div>
    <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">{label}</p>
    <p className="text-xl font-black text-slate-900 dark:text-white tracking-tight">{value}</p>
    <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest mt-1">{sub}</p>
  </div>
);

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { 
  X,
  CreditCard,
  Banknote,
  Clock,
  Users2,
  ScanLine,
  ShoppingCart,
  Briefcase,
  Box,
  Trash2,
  Search,
  ArrowRight,
  ChevronRight,
  CheckCircle,
  ArrowLeft,
  Store,
  Plus
} from 'lucide-react';
import { Product, Client, Invoice, InvoiceItem, PaymentMethod, AppConfig, ItemType } from '../types';
import { generateId, formatCurrency } from '../utils/helpers';
import BarcodeScanner from '../components/BarcodeScanner';

interface BillingProps {
  products: Product[];
  clients: Client[];
  setInvoices: React.Dispatch<React.SetStateAction<Invoice[]>>;
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
  setClients: React.Dispatch<React.SetStateAction<Client[]>>;
  config: AppConfig;
}

const Billing: React.FC<BillingProps> = ({ products, clients, setInvoices, setProducts, setClients, config }) => {
  const [cart, setCart] = useState<InvoiceItem[]>([]);
  const [custName, setCustName] = useState('');
  const [custMobile, setCustMobile] = useState('');

  const [discount, setDiscount] = useState(0);
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>(PaymentMethod.CASH);
  const [showCheckout, setShowCheckout] = useState(false);
  const [showScanner, setShowScanner] = useState(false);
  const [showFullListSelector, setShowFullListSelector] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);

  const [activeForm, setActiveForm] = useState<ItemType | null>(null);
  const [formData, setFormData] = useState({ name: '', price: '', quantity: '1', barcode: '', id: '' });
  const [searchQuery, setSearchQuery] = useState('');

  const filteredInventory = useMemo(() => 
    products.filter(p => p.name.toLowerCase().includes(searchQuery.toLowerCase()) || (p.barcode && p.barcode.includes(searchQuery))), 
    [searchQuery, products]
  );

  const handleSelectFromInventory = (p: Product) => {
    setFormData({ name: p.name, price: p.price.toString(), barcode: p.barcode || '', id: p.id });
    setActiveForm(p.type);
    setSearchQuery('');
    setShowFullListSelector(false);
  };

  const handleAddToCart = () => {
    if (!formData.name) return;
    const priceNum = parseFloat(formData.price) || 0;
    const qtyNum = parseInt(formData.quantity) || 1;

    setCart(prev => [...prev, {
      id: formData.id || generateId(),
      name: formData.name,
      price: priceNum,
      quantity: qtyNum,
      total: priceNum * qtyNum,
      type: activeForm || ItemType.PRODUCT
    }]);
    setFormData({ name: '', price: '', quantity: '1', barcode: '', id: '' });
  };

  const handleFinish = () => {
    if (!custName || cart.length === 0) return;
    const subtotal = cart.reduce((acc, i) => acc + i.total, 0);
    const invoice: Invoice = {
      id: `TX-${Date.now().toString().slice(-6)}`,
      date: new Date().toISOString(),
      clientId: 'WALK_IN',
      clientName: custName,
      clientMobile: custMobile,
      items: [...cart],
      discount,
      subtotal,
      grandTotal: subtotal * (1 - discount/100),
      paymentMethod
    };

    setInvoices(prev => [...prev, invoice]);
    setProducts(prev => prev.map(p => {
      const item = cart.find(i => i.id === p.id);
      return item && p.stock !== null ? { ...p, stock: p.stock - item.quantity } : p;
    }));

    if (paymentMethod === PaymentMethod.BORROW) {
      setClients(prev => {
        const idx = prev.findIndex(c => c.name === custName);
        if (idx > -1) {
          const updated = [...prev];
          updated[idx].totalBorrowed += invoice.grandTotal;
          return updated;
        }
        return [...prev, { id: generateId(), name: custName, mobile: custMobile, totalBorrowed: invoice.grandTotal }];
      });
    }

    setIsSuccess(true);
    setShowCheckout(false);
    setCart([]);
    setCustName('');
    setCustMobile('');
  };

  if (isSuccess) return (
    <div className="flex flex-col items-center justify-center min-h-[70vh] text-center p-10 animate-in-view">
      <div className="w-24 h-24 bg-brand-500 text-white rounded-[2rem] flex items-center justify-center mb-10 shadow-2xl shadow-brand-500/30">
        <CheckCircle className="w-12 h-12" />
      </div>
      <h2 className="text-4xl font-black text-slate-900 dark:text-white tracking-tighter mb-4">INVOICE READY</h2>
      <p className="text-slate-500 dark:text-slate-400 font-bold text-sm max-w-[240px] leading-relaxed mb-12">Transaction processed successfully and saved to history.</p>
      <button onClick={() => setIsSuccess(false)} className="w-full max-w-xs bg-slate-900 dark:bg-brand-500 text-white py-5 rounded-2xl font-black uppercase tracking-[0.2em] transition-all active:scale-95">New Transaction</button>
    </div>
  );

  return (
    <div className="space-y-8 animate-in-view">
      {showScanner && <BarcodeScanner onScan={(b) => {
        const p = products.find(x => x.barcode === b);
        if (p) handleSelectFromInventory(p);
        setShowScanner(false);
      }} onClose={() => setShowScanner(false)} />}

      {/* Customer Header */}
      <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 shadow-sm space-y-6">
        <div className="flex items-center gap-3">
          <div className="p-2.5 bg-slate-100 dark:bg-slate-800 text-slate-400 rounded-xl"><Users2 className="w-5 h-5" /></div>
          <h3 className="text-[11px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Customer Details</h3>
        </div>
        <div className="space-y-4">
          <input type="text" placeholder="Full Name" className="w-full text-lg font-extrabold bg-transparent outline-none text-slate-900 dark:text-white border-b-2 border-slate-100 dark:border-slate-800 focus:border-brand-500 pb-2 transition-all" value={custName} onChange={e => setCustName(e.target.value)} />
          <input type="tel" placeholder="Mobile (Optional)" className="w-full text-sm font-bold bg-transparent outline-none text-slate-500 dark:text-slate-400 border-b border-slate-100 dark:border-slate-800 focus:border-brand-500 pb-2 transition-all" value={custMobile} onChange={e => setCustMobile(e.target.value.replace(/[^0-9]/g, ''))} />
        </div>
      </div>

      {/* Selector Actions */}
      <div className="grid grid-cols-1 gap-4">
        <button onClick={() => setShowFullListSelector(true)} className="flex items-center justify-between p-6 bg-brand-500 text-white rounded-[2rem] active:scale-[0.98] transition-all shadow-xl shadow-brand-500/20">
          <div className="flex items-center gap-4">
            <div className="p-3 bg-white/10 rounded-2xl"><Search className="w-6 h-6" /></div>
            <div className="text-left">
              <p className="text-sm font-black uppercase tracking-widest">Inventory List</p>
              <p className="text-[10px] opacity-70 font-bold uppercase tracking-tight">Search your products</p>
            </div>
          </div>
          <ChevronRight className="w-6 h-6 opacity-40" />
        </button>

        <div className="grid grid-cols-2 gap-4">
          <QuickActionBtn icon={<Box />} label="Add Product" onClick={() => setActiveForm(ItemType.PRODUCT)} />
          <QuickActionBtn icon={<Briefcase />} label="Add Service" onClick={() => setActiveForm(ItemType.SERVICE)} />
        </div>
      </div>

      {/* Shopping Cart Container */}
      <div className="bg-white dark:bg-slate-900 rounded-[3rem] p-8 border border-slate-100 dark:border-slate-800 shadow-sm min-h-[200px]">
        <div className="flex justify-between items-center mb-8">
          <div className="flex items-center gap-2">
            <ShoppingCart className="w-5 h-5 text-slate-900 dark:text-white" />
            <h4 className="font-extrabold text-slate-900 dark:text-white text-sm uppercase tracking-tight">Active Cart</h4>
          </div>
          <button onClick={() => setShowScanner(true)} className="p-3 bg-slate-50 dark:bg-slate-800 text-slate-500 rounded-2xl active:scale-90 transition-all"><ScanLine className="w-5 h-5" /></button>
        </div>

        {cart.length === 0 ? (
          <div className="py-12 text-center opacity-20">
            <Store className="w-16 h-16 mx-auto mb-4" />
            <p className="text-[11px] font-black uppercase tracking-widest">Your cart is empty</p>
          </div>
        ) : (
          <div className="space-y-8">
            {cart.map((item, idx) => (
              <div key={idx} className="flex items-center justify-between group">
                <div className="flex items-center gap-4">
                  <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${item.type === ItemType.SERVICE ? 'bg-purple-50 text-purple-600' : 'bg-brand-50 text-brand-600'}`}>
                    {item.type === ItemType.SERVICE ? <Briefcase className="w-5 h-5" /> : <Box className="w-5 h-5" />}
                  </div>
                  <div>
                    <p className="font-black text-xs text-slate-900 dark:text-white uppercase tracking-tight leading-tight">{item.name}</p>
                    <p className="text-[10px] text-slate-400 font-bold uppercase mt-1 tracking-widest">{formatCurrency(item.price)} × {item.quantity}</p>
                  </div>
                </div>
                <div className="flex items-center gap-5">
                  <p className="font-black text-sm text-slate-900 dark:text-white">{formatCurrency(item.total)}</p>
                  <button onClick={() => setCart(prev => prev.filter((_, i) => i !== idx))} className="text-slate-300 hover:text-red-500 transition-colors"><Trash2 className="w-4.5 h-4.5" /></button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Inventory Modal */}
      {showFullListSelector && (
        <div className="fixed inset-0 bg-slate-50 dark:bg-slate-950 z-[100] flex flex-col animate-in-view">
          <div className="p-6 border-b border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 flex items-center gap-4">
            <button onClick={() => setShowFullListSelector(false)} className="p-2.5 bg-slate-100 dark:bg-slate-800 rounded-full text-slate-500 active:scale-90 transition-transform"><ArrowLeft className="w-6 h-6" /></button>
            <h2 className="text-xl font-extrabold text-slate-900 dark:text-white tracking-tight">Select Item</h2>
          </div>
          <div className="p-4">
            <div className="relative">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
              <input type="text" placeholder="Search product..." className="w-full pl-10 pr-4 py-3.5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl text-slate-900 dark:text-white font-bold outline-none text-sm" value={searchQuery} onChange={e => setSearchQuery(e.target.value)} autoFocus />
            </div>
          </div>
          <div className="flex-1 overflow-y-auto p-4 space-y-3 no-scrollbar">
            {filteredInventory.map(p => (
              <button key={p.id} onClick={() => handleSelectFromInventory(p)} className="w-full flex items-center justify-between p-5 bg-white dark:bg-slate-900 rounded-[2rem] border border-slate-100 dark:border-slate-800 active:scale-[0.98] transition-all">
                <div className="flex items-center gap-4">
                  <div className={`w-11 h-11 rounded-xl flex items-center justify-center ${p.type === ItemType.SERVICE ? 'bg-purple-50 text-purple-600' : 'bg-brand-50 text-brand-600'}`}>
                    {p.type === ItemType.SERVICE ? <Briefcase className="w-5 h-5" /> : <Box className="w-5 h-5" />}
                  </div>
                  <div className="text-left">
                    <p className="font-extrabold text-sm text-slate-900 dark:text-white tracking-tight">{p.name}</p>
                    <p className="text-[10px] text-slate-400 font-bold uppercase mt-0.5 tracking-widest">{formatCurrency(p.price)}</p>
                  </div>
                </div>
                <div className="w-8 h-8 flex items-center justify-center bg-slate-100 dark:bg-slate-800 rounded-full text-slate-400"><Plus className="w-4 h-4" /></div>
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Add Item Full Section */}
      {activeForm && (
        <div className="fixed inset-0 bg-slate-50 dark:bg-slate-950 z-[110] flex flex-col animate-in-view">
          <div className="p-6 border-b border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 flex items-center gap-4">
            <button onClick={() => setActiveForm(null)} className="p-2.5 bg-slate-100 dark:bg-slate-800 rounded-full text-slate-500 active:scale-90"><ArrowLeft className="w-6 h-6" /></button>
            <h3 className="text-xl font-extrabold text-slate-900 dark:text-white uppercase tracking-tight">Add {activeForm}</h3>
          </div>
          <div className="flex-1 overflow-y-auto flex flex-col no-scrollbar">
            <div className="p-8 space-y-8 bg-white dark:bg-slate-900 border-b border-slate-100 dark:border-slate-800">
              <div className="space-y-6">
                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Name / Label</label>
                  <input type="text" className="w-full mt-2 p-5 bg-slate-50 dark:bg-slate-800 border-none rounded-3xl text-slate-900 dark:text-white font-extrabold text-lg outline-none ring-2 ring-transparent focus:ring-brand-500" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} autoFocus />
                </div>
                <div className="grid grid-cols-2 gap-6">
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Rate (₹)</label>
                    <input type="number" className="w-full mt-2 p-5 bg-slate-50 dark:bg-slate-800 border-none rounded-3xl text-slate-900 dark:text-white font-extrabold text-lg outline-none ring-2 ring-transparent focus:ring-brand-500" value={formData.price} onChange={e => setFormData({...formData, price: e.target.value})} />
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Quantity</label>
                    <input type="number" className="w-full mt-2 p-5 bg-slate-50 dark:bg-slate-800 border-none rounded-3xl text-slate-900 dark:text-white font-extrabold text-lg outline-none ring-2 ring-transparent focus:ring-brand-500" value={formData.quantity} onChange={e => setFormData({...formData, quantity: e.target.value})} />
                  </div>
                </div>
              </div>
              <button onClick={handleAddToCart} className="w-full py-6 bg-brand-500 text-white rounded-[2rem] font-black uppercase tracking-widest shadow-xl shadow-brand-500/20 active:scale-95 transition-all">Add to Cart</button>
            </div>

            {/* Live Cart Preview */}
            <div className="flex-1 p-8 bg-slate-50/50 dark:bg-slate-950/50">
               <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-6 flex items-center gap-2">Current Bill Items ({cart.length})</h4>
               <div className="space-y-3">
                 {cart.map((item, idx) => (
                   <div key={idx} className="flex items-center justify-between p-4 bg-white dark:bg-slate-900 rounded-2xl border border-slate-100 dark:border-slate-800 shadow-sm">
                      <div className="flex items-center gap-3">
                        <div className={`p-2 rounded-lg ${item.type === ItemType.SERVICE ? 'bg-purple-50 text-purple-600' : 'bg-brand-50 text-brand-600'}`}>
                          {item.type === ItemType.SERVICE ? <Briefcase className="w-3.5 h-3.5" /> : <Box className="w-3.5 h-3.5" />}
                        </div>
                        <p className="text-xs font-extrabold text-slate-900 dark:text-white uppercase tracking-tight">{item.name}</p>
                      </div>
                      <button onClick={() => setCart(prev => prev.filter((_, i) => i !== idx))} className="text-red-400"><Trash2 className="w-4 h-4" /></button>
                   </div>
                 )).reverse()}
               </div>
            </div>
          </div>
          <div className="p-6 bg-white dark:bg-slate-900 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between shadow-2xl">
            <div>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Bill Running Total</p>
              <p className="text-2xl font-black text-brand-500">{formatCurrency(cart.reduce((acc, i) => acc + i.total, 0))}</p>
            </div>
            <button onClick={() => setActiveForm(null)} className="px-8 py-4 bg-slate-900 dark:bg-brand-500 text-white rounded-2xl font-black text-[11px] uppercase tracking-widest active:scale-95">Finish Adding</button>
          </div>
        </div>
      )}

      {/* Checkout Modal */}
      {showCheckout && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[120] flex items-end justify-center px-4 pb-4">
          <div className="bg-white dark:bg-slate-950 w-full max-w-lg rounded-[3.5rem] p-10 animate-in-view shadow-2xl overflow-hidden relative">
            <div className="flex justify-between items-center mb-10">
              <h3 className="text-2xl font-black text-slate-900 dark:text-white uppercase tracking-tight">Payment Method</h3>
              <button onClick={() => setShowCheckout(false)} className="p-3 bg-slate-100 dark:bg-slate-800 text-slate-500 rounded-full active:scale-90"><X className="w-6 h-6" /></button>
            </div>
            <div className="space-y-4 mb-10">
              <PayMethodBtn active={paymentMethod === PaymentMethod.CASH} icon={<Banknote />} label="Cash Payment" desc="Physical currency received" onClick={() => setPaymentMethod(PaymentMethod.CASH)} />
              <PayMethodBtn active={paymentMethod === PaymentMethod.ONLINE} icon={<CreditCard />} label="Online / UPI" desc="Digital bank transfer" onClick={() => setPaymentMethod(PaymentMethod.ONLINE)} />
              <PayMethodBtn active={paymentMethod === PaymentMethod.BORROW} icon={<Clock />} label="Borrow / Udhaar" desc="Add to client's khata" onClick={() => setPaymentMethod(PaymentMethod.BORROW)} />
            </div>
            <button onClick={handleFinish} className="w-full bg-brand-500 text-white py-6 rounded-[2.5rem] font-black uppercase tracking-[0.2em] shadow-xl shadow-brand-500/20 active:scale-95 transition-all">Confirm & Finalize</button>
          </div>
        </div>
      )}

      {/* Sticky Bottom Total Bar */}
      {cart.length > 0 && (
        <div className="fixed bottom-24 left-0 right-0 px-4 pointer-events-none z-[40] animate-in-view">
           <div className="max-w-md mx-auto bg-slate-900 text-white rounded-[2.5rem] p-6 shadow-2xl flex items-center justify-between pointer-events-auto border border-white/5">
              <div>
                <p className="text-[10px] font-black text-white/40 uppercase tracking-widest">Grand Total</p>
                <p className="text-3xl font-black">{formatCurrency(grandTotal)}</p>
              </div>
              <button onClick={() => setShowCheckout(true)} className="bg-brand-500 text-white p-5 rounded-3xl shadow-lg active:scale-95 transition-all"><ArrowRight className="w-7 h-7" /></button>
           </div>
        </div>
      )}
    </div>
  );
};

const QuickActionBtn = ({ icon, label, onClick }: any) => (
  <button onClick={onClick} className="flex items-center gap-4 p-5 bg-white dark:bg-slate-900 rounded-[1.8rem] border border-slate-100 dark:border-slate-800 shadow-sm active:scale-95 transition-all">
    <div className="p-3 bg-slate-50 dark:bg-slate-800 text-slate-500 dark:text-slate-400 rounded-xl transition-colors">{icon}</div>
    <span className="text-[10px] font-black uppercase tracking-widest text-slate-900 dark:text-white">{label}</span>
  </button>
);

const PayMethodBtn = ({ active, icon, label, desc, onClick }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-5 p-6 rounded-[2rem] border-2 transition-all ${active ? 'bg-brand-50 dark:bg-brand-500/10 border-brand-500' : 'bg-slate-50 dark:bg-slate-900 border-transparent opacity-50'}`}>
    <div className={`p-4 rounded-2xl ${active ? 'bg-brand-500 text-white' : 'bg-white dark:bg-slate-800 text-slate-400'}`}>{React.cloneElement(icon, { className: 'w-6 h-6' })}</div>
    <div className="text-left">
      <p className={`font-black text-sm ${active ? 'text-brand-600 dark:text-brand-400' : 'text-slate-900 dark:text-white'}`}>{label}</p>
      <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tight mt-1">{desc}</p>
    </div>
  </button>
);

export default Billing;

import React, { useState, useMemo } from 'react';
import { 
  X,
  CreditCard,
  Banknote,
  Clock,
  Users2,
  ScanLine,
  ShoppingCart,
  Briefcase,
  Box,
  Trash2,
  Search,
  ArrowRight,
  ChevronRight,
  CheckCircle,
  ArrowLeft,
